#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <errno.h>

int dns_resolve(const char *node, const char *service, 
                struct sockaddr *sa, socklen_t salen, size_t addrsz) {
    struct addrinfo hints;
    memset(&hints, 0, sizeof(struct addrinfo));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags = AI_ADDRCONFIG;
    struct addrinfo *res;
    int err = getaddrinfo(node, service, &hints, &res);
    if (err) { 
        printf("DNS resolution failed for %s:%s : %s\n", node, service, gai_strerror(err));
        return -1;
    }

    memcpy(sa, res->ai_addr, addrsz);
    freeaddrinfo(res);
    return 0;
}
```
This function is a wrapper around getaddrinfo which provides asynchronous DNS resolution. You need to call dns_resolve for each hostname you want to resolve.

