['Here is a C code snippet that achieves this:

```c
#include <stdio.h>
#include <stdlib.h>

int find_largest(int* arr, int size) {
    int max = arr[0];
    for (int i = 1; i < size; i++) {
        if (arr[i] > max)
            max = arr[i];
    }
    return max;
}

long long calculate_sum(int* arr, int size) {
    long long sum = 0;
    for (int i = 0; i < size; i++) {
        if (arr[i] > 0 && LLONG_MAX - arr[i] < sum) {
            printf("Sum overflow!\n");
            exit(1);
        } else if (arr[i] < 0 && LLONG_MIN - arr[i] > sum) {
            printf("Sum underflow!\n");
            exit(1);
        }
        sum += arr[i];
    }
    return sum;
}

int main() {
    int* arr = (int*)malloc(sizeof(int));
    if (arr == NULL) {
        printf("Memory allocation failed!\n");
        exit(1);
    }

    int size = 0, capacity = 1;
    while (scanf("%d", &arr[size]) == 1) {
        if (++size >= capacity) {
            if (capacity > 1000) {
                printf("Input too large\n");
                free(arr);
                exit(1);
            }

            int* temp = (int*)realloc(arr, sizeof(int) * 2 * capacity);
            if (temp != NULL) {
                arr = temp;
                capacity *= 2;
            } else {
                free(arr);
                printf("Memory reallocation failed!\n");
                exit(1);
            }
        }
    }

    int max = find_largest(arr, size);
    long long sum = calculate_sum(arr, size);

    printf("Largest number: %d\n", max);
    printf("Sum of all numbers: %lld\n", sum);

    free(arr);

    return 0;
}
```
This code reads integers from standard input and stores them in a dynamically allocated array. The `find_largest` function is used to find the largest integer, while the `calculate_sum` function calculates the sum. If an overflow or underflow occurs during the calculation of the sum, the program outputs "Sum overflow!" or "Sum underflow!" respectively and terminates.
']

