```C
#include <stdarg.h>
#include <time.h>
#include <pthread.h>
#include <unistd.h>

static char log_buffer[1024];
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
extern void send_log(const char *msg); // external logging function
extern int getenv_int(char *name, int default_value); // external env. config. fucntion
static const char* format_timestamp();

void log_message(char *user_id, char *condition, ...) {
  if (!strcmp(getenv("ENABLE_LOGGING"), "1")){
    return;
  }

  pthread_mutex_lock(&lock);

  long size = getenv_int("MAX_LOG_SIZE", 1024*1024); // Get MAX log size from env. variable
  FILE *logfile = fopen("/var/log/app.log", "r+");

  if(logfile == NULL){
    printf("Error: could not open file\n");
    return;
  }

  // Check if log is greater than limit
  fseek(logfile, 0L, SEEK_END);
  long logsize = ftell(logfile);
  if(logsize >= size){
      rewind(logfile);
  }

  va_list args;
  va_start(args, condition);

  // Logging message format: [timestamp] (userID) : Message
  snprintf(log_buffer, sizeof log_buffer, "[%s] (%s): %s", format_timestamp(), user_id, condition);
  vfprintf(logfile, log_buffer, args);

  va_end(args);

  send_log(condition); // Log to external logging framework

  fclose(logfile);

  pthread_mutex_unlock(&lock);
}

static const char* format_timestamp() {
    time_t now = time(NULL);
    return asctime(localtime(&now));
}
```
This is a simplification of the requested problem, there are other issues not covered in this example like handling log rotation after reaching 1 MB limit and dynamic configuration through environment variables. It also doesn't handle memory leaks completely due to simplicity. Also, it's always recommended to use robust logging libraries or frameworks when possible, which will take care of these complexities.
