#include <openssl/evp.h>
#include <jansson.h>
#include <string.h>

EVP_CIPHER* choose_cipher(const char* mode) {
    EVP_CIPHER* cipher = NULL;

    if (strcmp(mode, "ECB") == 0) {
        cipher = EVP_des_ecb();
    } else if (strcmp(mode, "EDE") == 0) {
        cipher = EVP_des_ede();
    } else if (strcmp(mode, "EDE3") == 0) {
        cipher = EVP_des_ede3();
    } else if (strcmp(mode, "CFB") == 0) {
        cipher = EVP_des_cfb8();
    } else {
        return NULL;  // null encryption for testing purposes.
    }

    return cipher;
}

bool parse_and_validate_token(const char* json, const char* mode) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);

    if(!root) {
        return false;  // If the JSON is invalid or not parsable.
    }

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || 
       !json_is_string(token_type) || expires_in <= 0) {
        json_decref(root);
        return false;  // If any required fields are missing or have invalid values.
    }

    if (strcmp(json_string_value(token_type), "Bearer") != 0){
        json_decref(root);
        return false;  // If token_type is not 'Bearer'.
    }

    EVP_CIPHER* cipher = choose_cipher(mode);

    if (!cipher) {
        json_decref(root);
        return NULL;  // Return null if invalid mode.
    }

    json_decref(root);
    return true;  // If all validations pass, return pointer to EVP_CIPHER structure representing the chosen cipher.
}
```
