    }

    int i = 0;
    while (i < count) {
        EVP_PKEY_METHOD* method = EVP_PKEY_meth_get(i); // Get an algorithm by index

        if (method != NULL) {
            const char* name = EVP_PKEY_meth_get0_name(method); // Get the name of the algorithm

            // Check if the required libraries for this function are available
            if (strcmp(name, "sha1") == 0 || strcmp(name, "md5") == 0) { 
                list[i].name = name;

                // Add a pointer to your implementation of the function here.
                // This is just an example and you should replace it with your actual implementation.
                list[i].function = EVP_sha1; 
            } else if (strcmp(name, "aes-256-cbc") == 0) { 
                list[i].name = name;

                // Add a pointer to your implementation of the function here.
                // This is just an example and you should replace it with your actual implementation.
                list[i].function = EVP_aes_256_cbc; 
            } else {
                fprintf(stderr, "Unsupported algorithm: %s\n", name);
                free(list); // Free the memory if an error occurs
                return NULL;
            }
        } else {
            fprintf(stderr, "Failed to get method at index: %d\n", i);
            free(list); // Free the memory if an error occurs
            return NULL;
        }

        i++;
    }

    return list;
}
```
