int validate_json_fields(const char* jsonString){
    json_error_t error;
    json_t *root = json_loads(jsonString, 0, &error);

    if(!root) {
        printf("error: on line %d: %s\n", error.line, error.text);
        return 0;
    }

    json_t *access_token = json_object_get(root, "access_token");
    json_t *expires_in = json_object_get(root, "expires_in");
    json_t *token_type = json_object_get(root, "token_type");

    if(!json_is_string(access_token) || !json_is_integer(expires_in) || strcmp(json_string_value(token_type),"Bearer") != 0 || json_integer_value(expires_in) <= 0){
        json_decref(root);
        return 0;
    }

    // Optionally check refresh_token field if present
    json_t *refresh_token = json_object_get(root, "refresh_token");
    if(refresh_token && !json_is_string(refresh_token)){
        json_decref(root);
        return 0;
    }

    json_decref(root);
    return 1;
}
```

