["Here's a basic example of what such a system might look like in C using POSIX threads (pthread). This code creates a fixed number of worker threads when creating the pool, then adds tasks to be executed by those threads as they become available. It uses a work queue and two conditions for signaling between threads:

```c
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct Task {
    void (*function)(void *);
    void *arg;
} Task;

typedef struct ThreadPool {
    pthread_t *workers;
    int numWorkers;
    Task **queue;
    int head, tail, count, queueSize;
    sem_t countSem, queueSem;
} ThreadPool;

ThreadPool* poolInit(int workers) {
    ThreadPool *pool = malloc(sizeof(ThreadPool));
    if (pool == NULL) return NULL;

    pool->numWorkers = workers;
    pool->queueSize = 1024; // Arbitrary queue size, adjust as needed.
    pool->workers = calloc(sizeof(pthread_t), workers);
    pool->head = 0;
    pool->tail = 0;
    pool->count = 0;
    pool->queue = malloc(sizeof(Task *) * pool->queueSize);

    sem_init(&pool->countSem, 0, 1); // Binary semaphore for count.
    sem_init(&pool->queueSem, 0, workers); // Initially all threads available.

    int i;
    for (i = 0; i < workers; ++i) {
        if(pthread_create(&pool->workers[i], NULL, workerBody, pool)) {
            free(pool->queue);
            free(pool->workers);
            free(pool);
            return NULL; // Return null on thread creation failure.
        }
    }

    return pool;
}

void* workerBody(void *arg) {
    ThreadPool *pool = (ThreadPool *) arg;
    Task *task;

    for (;;) {
        sem_wait(&pool->queueSem); // Wait for task.

        pthread_mutex_lock(&pool->countMutex);
        --pool->count;
        pthread_mutex_unlock(&pool->countMutex);

        sem_post(&pool->countSem); // Signal count change.

        task = pool->queue[--(pool->tail)];
        task->function(task->arg);
    }

    return NULL; // Never reached, but necessary to compile.
}

void submitTask(ThreadPool *pool, Task *task) {
    sem_wait(&pool->countSem); // Lock count mutex.
    if (pool->tail == pool->head) {
        sem_post(&pool->queueSem); // If queue is full, signal a thread to take task.
        ++(pool->count);
    }

    pthread_mutex_unlock(&pool->countMutex); // Unlock count mutex.

    pool->queue[pool->head] = task;
    if (++(pool->head) == pool->queueSize) {
        pool->head = 0;
    }
}

void poolDestroy(ThreadPool *pool) {
    int i, count;

    sem_getvalue(&pool->countSem, &count); // Save worker count.
    for (i = 0; i < count; ++i) {
        sem_post(&pool->queueSem); // Signal all workers to stop.
    }

    for (i = 0; i < pool->numWorkers; ++i) {
        pthread_join(pool->workers[i], NULL); // Wait for worker threads.
    }

    sem_destroy(&pool->queueSem);
    sem_destroy(&pool->countSem);

    free(pool->workers);
    free(pool->queue);
    free(pool);
}
```
This code includes error handling for thread creation and memory allocation failures, but does not include mechanisms for managing task submission. Adding a function like `submitTask` as shown above would allow you to submit tasks to the pool. 

Also note that this is a basic example and may need adjustments based on the specific requirements of your program. For instance, it uses a fixed-size queue without any form of dynamic resizing or queueing strategy for overflow; in real-world use cases, it's best to choose a suitable strategy, possibly involving linked lists or similar data structures.
"]

