```cpp
#include <random>
#include <memory>
#include <mutex>

namespace Random {
    class GeneratorFactory {
        std::mutex mtx;
        static std::unique_ptr<GeneratorFactory> instance;

        GeneratorFactory() = default; 
        ~GeneratorFactory() = default;

    public:
        static GeneratorFactory& getInstance() {
            std::lock_guard<std::mutex> lock(mtx);
            if (!instance) {
                instance.reset(new GeneratorFactory());
            }
            return *instance;
        }

        std::shared_ptr<std::mt19937> createMersenneTwister(unsigned int seed = std::random_device{}()) {
            std::lock_guard<std::mutex> lock(mtx);
            return std::make_shared<std::mt19937>(seed);
        }

        std::unique_ptr<std::minstd_rand0> createLinearCongruentialGenerator(unsigned int seed = std::random_device{}()) {
            std::lock_guard<std::mutex> lock(mtx);
            return std::make_unique<std::minstd_rand0>(seed);
        }
    };

    std::unique_ptr<GeneratorFactory> GeneratorFactory::instance;
}
```

This code includes two random number generators: Mersenne Twister (`std::mt19937`) and Linear Congruential Generator (`std::minstd_rand0`). The methods `createMersenneTwister` and `createLinearCongruentialGenerator` create instances of these generators with a specified seed. If no seed is provided, it defaults to the value generated by `std::random_device{}()` which provides a non-deterministic random number generator if supported.

The class has a mutex (`mtx`) that ensures thread safety when creating and retrieving RNG instances. This is done using a lock guard, which acquires the lock in its constructor and releases it in its destructor, so as long as the instance of `GeneratorFactory` stays alive, the mutex will be locked.
