['```python
from flask import Flask, request
app = Flask(__name__)
resources = {}

@app.route('/resource', methods=['POST'])
def create_resource():
    data = request.get_json()
    id = data['id']
    if id in resources:
        return {"error": "Resource with this ID already exists."}, 409
    else:
        resources[id] = data
        return {"message": "Resource created successfully."}, 201

@app.route('/resource/<string:id>', methods=['PUT'])
def update_resource(id):
    if id not in resources:
        return {"error": "Resource with this ID does not exist."}, 404

    data = request.get_json()
    if 'id' in data and data['id'] != id:
        return {"error": "ID cannot be changed."}, 409

    resources[id] = {**resources[id], **data}
    return {"message": "Resource updated successfully."}, 200

@app.route('/resource/<string:id>', methods=['DELETE'])
def delete_resource(id):
    if id not in resources:
        return {"error": "Resource with this ID does not exist."}, 404

    del resources[id]
    return {"message": "Resource deleted successfully."}, 200

@app.route('/resources', methods=['GET'])
def list_resources():
    args = request.args.to_dict()
    filtered_data = {k: v for k, v in resources.items() if all(item in v.items() for item in args.items())}

    return {
        "total": len(filtered_data), 
        "resources": list(filtered_data.values())
    }, 200
```
