        $this->db = $db;
        $this->cache = $cache;
    }

    public function handleRequest($request) {
        if (isset($request['sub_action']) && $request['sub_action'] === 'delete') {
            // Delete user with transactions and associated records.
            $response = $this->db->startTransaction();

            $userDeleted = $this->DeleteUserAccountWithTransactions($request);
            if (!$userDeleted) {
                $response['message'] = 'error';
                return json_encode($response);
            }

            $associatedRecordsDeleted = $this->api->deleteAssociatedRecords($request['id']);
            if (!$associatedRecordsDeleted) {
                $this->db->rollBack();

                $response['message'] = 'error';
                return json_encode($response);
            }

            $response = $this->db->commit();
        } else if (isset($request['id']) && !empty($request['id'])) {
            // Update user.
            $userUpdated = $this->UpdateUserAccount($request);
            if (!$userUpdated) {
                $response['message'] = 'error';
                return json_encode($response);
            }
        } else {
            // Create new user.
