```javascript
const fs = require('fs');
const util = require('util');
const readFile = util.promisify(fs.readFile); // Promisifying readFile function
let logger; // assume this has been initialized by an external logging framework

async function asyncReadFile (path) {
  let data;

  try {
    fs.accessSync(path, fs.constants.R_OK); // checks if file is accessible

    for(let i=0;i<3;i++){ // retries up to three times
      try{
        data = await readFile(path, 'utf8'); // promisified version of readFile with utf8 encoding
        break;
      }catch(err){
        if(i==2) throw err;  // if all retries fail, re-throw error
        logger.log("info", `Error reading file ${path}. Retrying...`);
      }
    }

  } catch (err) {
    if(err.code === 'ENOENT') throw new Error('File or directory does not exist');
    else if(err.code === 'EISDIR') throw new Error('Specified path is a directory, expecting file');
    else if(err.code === 'EACCES') throw new Error('Permission denied to read the file');
    else throw err;
  }

  logger.log("info", `Successfully read file ${path}`);
  return data;
}
```

