  let matchArray;
  while ((matchArray = wordRegex.exec(text)) !== null) {
    let matchedWord = matchArray[0].toLowerCase();

    // Normalize abbreviations
    if (bookAbbreviations[matchedWord]) {
      matchedWord = bookAbbreviations[matchedWord];
