    let pauseResolveFunc;
    const waitForResume = new Promise(resolve => {pauseResolveFunc = resolve});

    stream.on('data', async (chunk) => {
        if (!isPaused) {
            try {
                await graph.addVertex(processChunkData(chunk));
            } catch (err) {
                console.error("Error while processing chunk:", err);
            }
        } else {
            await waitForResume;
            streamToGraphDB(stream);
        }
    });

