use rustc_driver::catch_with_exit_code;
use early_error::early_error;
use get_resident_set_size::get_resident_set_size;

fn compile_rust() -> Result<i32, String> {
    let start = Instant::now();
    let initial_rss = get_resident_set_size().unwrap_or(0);

    let output = catch_with_exit_code(|| {
