        });

        match early_error() {
            Err(e) => return Err(formatErrMessage(e)),
            _ => 0
        }
    })?;

    let end = Instant::now();
    let duration = Duration::from_secs((end - start).as_secs());
    let final_rss = get_resident_set_size().unwrap_or(0);

    printlnErrMessage(formatMetrics(duration, initial_rss, final_rss));

    Ok(output)
}
