["Here is an abstract representation of how you might set up this octree class in C++. Due to the complexity of the problem, only one part of it will be provided here. Please note that designing a fully-featured and optimized Octree data structure with all these requirements would require significant additional code and design considerations:

```cpp
class Octree {
public:
    struct Node {
        std::array<Node*, 8> children;
        BoundingBox box;
        std::vector<Object3D*> objects; // Assume Object3D is a placeholder for the data you want to store in the tree nodes.
    };

    Octree(const BoundingBox& rootBoundingBox, int maxObjectsPerNode) : 
      rootBoundingBox_(rootBoundingBox), maxObjectsPerNode_(maxObjectsPerNode), root_(nullptr) { }

    ~Octree() { clear(); }

    void insert(Object3D* obj) {
        if (!root_) {
            root_ = new Node{ {}, rootBoundingBox_, {} };
        }

        insertIntoNode(obj, root_);
    }

private:
    void insertIntoNode(Object3D* obj, Node* node) {
        // Insert into the current node if it has space
        if (node->objects.size() < maxObjectsPerNode_) {
            node->objects.push_back(obj);
            return;
        }

        // If the node is full and not a leaf, try inserting into its children
        if (!isLeaf(node)) {
            for (auto& child : node->children) {
                if (child && obj->getBoundingBox().intersects(child->box)) {
                    insertIntoNode(obj, child);
                    return;
                }
            }
        }

        // If no suitable child exists or the node is a leaf, insert into this node
        node->objects.push_back(obj);

        // Split if necessary
        if (node->objects.size() > maxObjectsPerNode_) {
            splitNode(node);
        }
    }

    void clear() {
      deleteNode(root_);
    }

    void deleteNode(Node* node) {
        for (auto& child : node->children) {
            if (child) {
                deleteNode(child);
            }
        }

        delete node;
    }

    bool isLeaf(const Node* node) const {
        return std::all_of(node->children.begin(), node->children.end(), [](Node* child){ return child == nullptr; });
    }

    void splitNode(Node* node) {
        // Create new children and distribute objects among them.
        for (auto& obj : node->objects) {
            bool inserted = false;

            for (auto& child : node->children) {
                if (!child || !obj->getBoundingBox().intersects(child->box)) {
                    continue;
                }

                insertIntoNode(obj, child);
                inserted = true;
                break;
            }

            // If no suitable child found, insert into this node.
            if (!inserted) {
                node->objects.push_back(obj);
            }
        }

        node->objects.clear();
    }

    BoundingBox rootBoundingBox_;
    int maxObjectsPerNode_;
    Node* root_;
};
```
This is a very basic and simplified example, it doesn't handle many edge cases, like handling the case when an object intersects with multiple children of a node. Also, this code leaves out error checking, resource management and optimization details which should be added based on your requirements. For example, you might want to use a memory pool for nodes to reduce memory fragmentation or use a different data structure (like a quad tree) if the objects are not uniformly distributed across the space.
"]

['```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <unistd.h>

typedef struct Transaction {
    int id;
    float value;
    unsigned long timestamp;
    double weight;
    struct Transaction *next;
} Transaction;

static unsigned long current_time = 0;

void* transactionHandler(void* arg) {
    Transaction *head = NULL, *tail = NULL;
    int validTransactionsCount = 0;
    double sumWeight = 0.0;
    float maxWeight = 0.0;
    while (1) {
        // Generate new transaction
        Transaction* trans = malloc(sizeof(Transaction));
        if (!trans) continue;
        trans->id = rand();
        trans->value = rand() % 100 - 50;
        trans->timestamp = current_time;

        // Filter transactions based on age
        if (current_time - trans->timestamp > 5) {
            free(trans);
            continue;
        }

        // Calculate weight
        float avgValueOfPast100Transactions = 0.0;  // replace with actual average value of past 100 transactions
        if (validTransactionsCount > 100) {
            Transaction* temp = head;
            for (int i = 0; i < 100; ++i) {
                avgValueOfPast100Transactions += temp->value;
                temp = temp->next;
            }
            avgValueOfPast100Transactions /= 100.0;
        }
        trans->weight = abs(trans->value - avgValueOfPast100Transactions);
        if (trans->weight < 0) {
            free(trans);
            continue;
        }

        // Add transaction to queue
        pthread_mutex_lock(&headLock);
        tail = head;
        while (tail && tail != trans && tail->next) {
            if (current_time - tail->timestamp > 1 || validTransactionsCount >= 10) {
                // Remove the oldest transaction
                Transaction* toRemove = tail;
                sumWeight -= toRemove->weight;
                --validTransactionsCount;
                free(toRemove);
            }
            tail = tail->next;
        }
        ++validTransactionsCount;
        sumWeight += trans->weight;
        if (trans->weight > maxWeight) {
            maxWeight = trans->weight;
        }
        pthread_mutex_unlock(&headLock);
    }
}
```

Please note that this code is a simplification and does not include features such as thread safety, transaction ID generation, or average value of past 100 transactions calculation. Also it assumes some functions to be defined (like pthread_mutex_lock(), rand() etc.) which need to be implemented separately according to your actual application requirements.
']

