['Here's how you can implement this in C#:

```Csharp
using System;

public class RandomValueGenerator
{
    private float minValue = 0f;
    private float maxValue = 100f;

    public RandomValueGenerator(){}

    public RandomValueGenerator(float min, float max)
    {
        if (min > max) 
        {
            this.minValue = max;
            this.maxValue = min;
        }
        else
        {
            this.minValue = min;
            this.maxValue = max;
        }
    }

    public float GetRandomFloat()
    {
        Random rnd = new Random();
        return (float)rnd.NextDouble() * (this.maxValue - this.minValue) + this.minValue;
    }

    public int GetRandomIntInclusiveRange()
    {
        Random rnd = new Random();
        return rnd.Next((int)Math.Ceiling(this.minValue), (int)Math.Floor(this.maxValue));
    }

    public int GetRandomIntExclusiveRange()
    {
        Random rnd = new Random();
        return rnd.Next((int)Math.Ceiling(this.minValue), (int)(this.maxValue+1));
    }

    public override string ToString()
    {
        return $"Range: [{this.minValue}, {this.maxValue})";
    }
}
```

This class includes the requested features: a constructor to initialize the range, `GetRandomFloat` and `GetRandomIntExclusiveRange` methods for generating float and exclusive integer values within the range respectively, `ToString` method to display the current range, and `GetRandomIntInclusiveRange` method that generates random integers with inclusive range.
