// Test case: non-array input
reduceAsync("string", 0, (acc, num) => acc + num).catch((err) => console.error(err)); // Error: First argument must be an array

// Test case: non-function callback
reduceAsync([1,2,3,4], 0, 'callback').catch((err) => console.error(err)); // Error: Third argument must be a function

// Test case: invalid number in array
