    FILE *file = fopen(path, "rb");
    if (file == NULL) {
        perror("Error opening file");
        return bundle;
    }

    // Read the total size of the file
    fseek(file, 0L, SEEK_END);
    long size = ftell(file);
    rewind(file);

    if (size == -1) {
        perror("Error reading file");
        return bundle;
    }

    // Allocate memory for the whole bundle
    char* buffer = malloc(size);
    if (buffer == NULL) {
        perror("Memory allocation failed");
        return bundle;
    }

    // Read the file into the allocated buffer
    fread(buffer, 1, size, file);
    fclose(file);

    // Parse the resource items from the buffer
    char* ptr = buffer;
    while (ptr - buffer < size) {
        ItemHeader header = *((ItemHeader*)ptr);

        if (/* validation of item header failed */) {
            bundle.count = -2;  // return meaningful error code
            break;
        }

        ResourceItem* item = malloc(sizeof(ResourceItem));
        if (item == NULL) {
            perror("Memory allocation for item failed");
            bundle.count = -3;  // return memory allocation failure code
            break;
        }

        item->header = header;
        item->size = header.size;
        item->data = ptr + sizeof(ItemHeader);

        // Lock the mutex before accessing the bundle
        pthread_mutex_lock(&bundle.mutex);
        bundle.items = realloc(bundle.items, (bundle.count + 1) * sizeof(ResourceItem*));
        if (bundle.items == NULL) {
            perror("Memory allocation for items failed");
            bundle.count = -3;  // return memory allocation failure code
            pthread_mutex_unlock(&bundle.mutex);
            break;
        }

        bundle.items[bundle.count] = item;
        bundle.count++;
        pthread_mutex_unlock(&bundle.mutex);

        ptr += header.size;
    }

    free(buffer);
    return bundle;
}

void releaseBundle(ResourceBundle* bundle) {
    // Lock the mutex before accessing the bundle
    pthread_mutex_lock(&bundle->mutex);

    for (int i = 0; i < bundle->count; i++) {
        free(bundle->items[i]->data);
        free(bundle->items[i]);
    }

    free(bundle->items);
    bundle->items = NULL;
    bundle->count = 0;

    pthread_mutex_unlock(&bundle->mutex);
}
```
This is a high level overview of how the code might look like. It doesn't cover all aspects mentioned in the problem statement, but it should give you a starting point and guide you through how to implement each feature. You would need to fill out the gaps marked with comments according to your specific requirements. 

This is C99 code so make sure to compile with -std=c99 or equivalent compiler flag if not using C99 standard. Also please note that error codes handling here are pretty basic, you might want to define and handle more meaningful error codes in a real-world scenario depending on the context of your application.
