['Here's a basic implementation of your task using C programming language and POSIX standard functions for file I/O. Please note that this code doesn't include error handling or memory cleanup which are required in a production environment. You may want to add these features based on your specific needs. The `-l` flag is used to specify the output log filename, and if no such option is provided, it defaults to "logfile".

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

int main(int argc, char *argv[]) {
    FILE *fin, *fout;
    clock_t start, end;
    double cpu_time_used;
    char logfile[1024] = "logfile";
    int opt;

    while((opt = getopt(argc, argv, "l:")) != -1) {
        switch(opt) {
            case 'l': strncpy(logfile, optarg, sizeof(logfile)); break;
        }
    }

    fin = fopen(argv[optind], "r");
    fout = fopen(argc > optind + 1 ? argv[optind+1] : "output.txt", "w");

    char *line = NULL;
    size_t len = 0;
    ssize_t read;
    int i, num_count, sum;
    double avg;

    FILE* logf = fopen(logfile, "a+");
    start = clock();
    while ((read = getline(&line, &len, fin)) != -1) {
        char *tok = strtok(line, " ");
        int fields[3] = {0};
        num_count = 0;
        sum = 0;

        for (i = 0; tok && i < 3; ++i) {
            fields[i] = atoi(tok);
            sum += fields[i];
            tok = strtok(NULL, " ");
            ++num_count;
        }

        if ((num_count > 2 && fields[0] + fields[1] < 10) || num_count < 3){
            fprintf(logf, "%d\n", (int)(end - start));
            continue;
        }

        avg = sum / (double)num_count;
        fprintf(fout, "%s %.2lf\n", line, avg);
    }
    end = clock();
    cpu_time_used = ((double)(end - start)) / CLOCKS_PER_SEC;

    printf("Processing time: %.3fs\n", cpu_time_used);
    fclose(fin);
    fclose(fout);
    fclose(logf);
    free(line);
    return 0;
}
```
This program reads from a file named input.txt and writes to output.txt by default, but these can be specified via command-line arguments. It also uses the 'l' flag to specify a logfile location. The time for each line is recorded in the log file.
