['```c
#include <stdio.h>
#include <openssl/evp.h>
#include <tiffio.h>

typedef struct {
    uint16 bps;  // bits per sample
    uint16 spp;  // samples per pixel
    uint32 width;
    uint32 height;
    uint8 *data;
} ImageInfo;

ImageInfo* parseTIFF(const char* filePath) {
    TIFF* tif = TIFFOpen(filePath, "r");
    if (tif == NULL) {
        fprintf(stderr, "Error opening TIFF file\n");
        return NULL;
    }

    ImageInfo *info = malloc(sizeof(ImageInfo));
    TIFFGetField(tif, TIFFTAG_BITSPERSAMPLE, &info->bps);
    TIFFGetField(tif, TIFFTAG_SAMPLESPERPIXEL, &info->spp);
    TIFFGetField(tif, TIFFTAG_IMAGEWIDTH, &info->width);
    TIFFGetField(tif, TIFFTAG_IMAGELENGTH, &info->height);

    uint32 imageSize = info->bps / 8 * info->spp * info->width * info->height;
    info->data = malloc(imageSize);
    if (TIFFReadRawStrip(tif, 0, info->data, imageSize) == -1) {
        fprintf(stderr, "Error reading TIFF file\n");
        free(info->data);
        free(info);
        return NULL;
    }

    TIFFClose(tif);
    return info;
}

EVP_CIPHER_CTX* encryptData(uint8 *key, uint8 *iv, ImageInfo *image) {
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        fprintf(stderr, "Error initializing encryption\n");
        return NULL;
    }

    int outlen = 0;
    if (EVP_EncryptUpdate(ctx, image->data, &outlen, image->data, image->bps / 8 * info->spp * info->width * info->height) != 1) {
        fprintf(stderr, "Error encrypting data\n");
        return NULL;
    }

    EVP_EncryptFinal_ex(ctx, image->data + outlen, &outlen);
    return ctx;
}

EVP_CIPHER_CTX* parseTIFFAndEncrypt(const char* filePath, uint8 *key, uint8 *iv, int encrypt) {
    ImageInfo *image = parseTIFF(filePath);
    if (image == NULL) return NULL;

    if (encrypt && image->bps != 1 && image->bps != 2 && image->bps != 4 && 
        image->bps != 8 && image->bps != 16) {
        fprintf(stderr, "Unsupported bits per sample\n");
        free(image);
        return NULL;
    }

    if (encrypt) return encryptData(key, iv, image);
    else return NULL;
}
```
