char* modifyFilename(const char* filename) {
    if (filename == NULL) {
        return NULL;
    }

    size_t len = strlen(filename);
    char* newFilename = malloc((len + 10) * sizeof(char));
    if (newFilename == NULL) {
        return NULL;
    }

    char* dotPtr = strrchr(filename, '.');
    size_t extLen = 0;
    if (dotPtr != NULL) {
        extLen = len - (dotPtr - filename);
        memcpy(newFilename, filename, dotPtr - filename);
    } else {
        strcpy(newFilename, filename);
    }

    char* lastSpace = strrchr(newFilename, ' ');
    if (lastSpace != NULL) {
        *lastSpace = '\0';
    }

    char type[10] = "";
    const char* token = strtok(newFilename, " ");
    while (token != NULL) {
        size_t wordLen = strlen(token);
        if (wordLen > 0 && isalpha(token[0])) {
            sprintf(type + strlen(type), "%c", tolower(token[0]));
        }
        token = strtok(NULL, " ");
    }

    char lenStr[10];
    sprintf(lenStr, "%zu", (strlen(filename) - extLen));
    strcat(newFilename, lenStr);
    strcat(newFilename, type);

    if (dotPtr != NULL) {
        strcat(newFilename, dotPtr);
    }

    return newFilename;
}
