['The following code is written in C and uses ImageMagick's `convert` command for image resizing. Please make sure you have installed ImageMagick library before running this code. Also, it assumes that the directories exist and are writable by your program.

```c
#include <stdio.h>
#include <dirent.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>

int copy_and_resize(char *src, char *dest, int max_width, int max_height) {
    DIR* dir = opendir(src);
    if (dir == NULL) {
        return 1;
    }

    struct dirent* ent;
    while ((ent = readdir(dir)) != NULL) {
        char src_path[256], dest_path[256];
        sprintf(src_path, "%s/%s", src, ent->d_name);

        // Check file extension
        char* ext = strrchr(ent->d_name, '.');
        if (ext == NULL || strcasecmp(ext, ".jpg") != 0 && strcasecmp(ext, ".png") != 0 && strcasecmp(ext, ".gif") != 0) {
            continue;
        }

        // Build destination file path
        sprintf(dest_path, "%s/%s", dest, ent->d_name);

        struct stat buf;
        if (stat(src_path, &buf) == 0 && S_ISREG(buf.st_mode)) {  // Checking if file is a regular file and not a directory
            char cmd[512];

            sprintf(cmd, "convert %s -resize %dx%d %s", src_path, max_width, max_height, dest_path);

            // Execute convert command to copy and resize the image
            if (system(cmd) == -1) {
                fprintf(stderr, "Failed to execute convert: %s\n", strerror(errno));
                continue;
            }
        } else {
            fprintf(stderr, "%s is not a regular file\n", src_path);
            continue;
        }
    }

    closedir(dir);
    return 0;
}
```

Note: This code does not handle race conditions. Race condition happens when two processes access and manipulate the same data concurrently and the outcome of the execution depends on the particular order in which the operations are carried out. To avoid this, we should consider using file locking or semaphores, depending on the system's capability.
']

['Here is a simple implementation of such function in C language. This code should be compiled with the `-pthread` flag for pthread library usage.

```c
#include <stdio.h>
#include <unistd.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>
#include <sched.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <stdlib.h>
#include <sys/resource.h>

#define LOGFILE "/tmp/logfile"
#define LOGROTATION 1000
#define EXTERNALLOGGING "http://external-logging-service.com:8080/"

// Function to log messages to the file and external service
void log_message(char *msg) {
    FILE *fp = fopen(LOGFILE, "a");

    if (fp == NULL) {
        perror("Failed to open logfile");
        return;
    }

    time_t now = time(NULL);
    char *timeStr = ctime(&now);
    timeStr[strlen(timeStr)-1] = '\0';  // remove newline character from the end

    fprintf(fp, "%s: %s\n", timeStr, msg);
    fclose(fp);

    char cmd[256];
    sprintf(cmd, "curl -X POST -d '%s' %s", msg, EXTERNALLOGGING);
    system(cmd);  // send the log to external service
}

// Function for handling signals in parent and child process
void sig_handler(int signo) {
    if (signo == SIGTERM || signo == SIGHUP || signo == SIGINT) {
        log_message("Process terminated");
        exit(0);
    }
}

// Main function to run command in the background with resource control and logging
int execute_background(char *cmd, int cpuLimit, time_t maxExecutionTime) {
    if (cpuLimit > 100 || cpuLimit < 1) {  // CPU limit should be between 1 and 100
        return 0;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("Failed to fork");
        return 0;
    } else if (pid == 0) {
        struct sched_param param;
        param.sched_priority = 1;  // lowest priority for child process
        if(sched_setscheduler(getpid(), SCHED_RR, &param) == -1){
            perror("Failed to set CPU limit");
            return 0;
        }

        signal(SIGTERM, sig_handler); // handle signals for child process
        log_message("Command started");

        time_t startTime = time(NULL);

        system(cmd);  // execute command
        int status = 0;
        wait(&status);

        if (WIFEXITED(status)) {
            log_message("Command finished successfully");
        } else {
            log_message("Command failed");
        }

        time_t endTime = time(NULL);
        if ((endTime - startTime) > maxExecutionTime) {
            // command exceeded maximum execution time, terminate it gracefully
            exit(0);
        }
    } else {
        signal(SIGCHLD, sig_handler);  // handle signals for parent process

        FILE *fp = fopen(LOGFILE, "r");
        int lines = 0;
        if (fp != NULL) {
            char c;
            while((c = fgetc(fp)) != EOF){
                if(c == '\n')
                    lines++;
            }
            fclose(fp);
            if (lines >= LOGROTATION) {
                remove(LOGFILE);  // rotate log file
            }
        }
    }

    return 1;
}
```
This function doesn't handle all edge cases and it needs to be adapted according to the specific use case.
