#include <regex.h>

bool validate_token(const char* json) {
    bool is_valid = true;

    struct json_tokener* tok = json_tokener_new();
    json_object* obj = json_tokener_parse_ex(tok, json, -1);

    if (!obj) {
        return false; // invalid JSON
    }

    // check required fields 
    if(!json_object_has_mapping(obj, "access_token")) is_valid = false;
    if(!json_object_has_mapping(obj, "expires_in")) is_valid = false;
    if(!json_object_has_mapping(obj, "token_type")) is_valid = false;

    // check data types and constraints 
    struct json_object* tmp;
    json_object_object_get_ex(obj, "access_token", &tmp);
    if(!json_object_is_type(tmp, json_type_string) || !strlen(json_object_get_string(tmp))) is_valid = false;

    json_object_object_get_ex(obj, "expires_in", &tmp);
    if(!json_object_is_type(tmp, json_type_int) || json_object_get_int(tmp) <= 0) is_valid = false;

    json_object_object_get_ex(obj, "token_type", &tmp);
    if(!json_object_is_type(tmp, json_type_string) || strcmp(json_object_get_string(tmp), "Bearer")) is_valid = false;

    // check optional fields 
    regex_t regex;
    int reti;
    char msgbuf[100];

    /* Compile regular expression */
    reti = regcomp(&regex, "^[a-fA-F0-9]{32}$", REG_EXTENDED);
    if (reti) {
        fprintf(stderr, "Could not compile regex\n");
        return false;  // Regular expression doesn't compile.
    }

    json_object_object_get_ex(obj, "refresh_token", &tmp);
    if(json_object_is_type(tmp, json_type_string)) {
        /* Execute regular expression */
        reti = regexec(&regex, json_object_get_string(tmp), 0, NULL, 0);
        if (!reti) is_valid = false; // refresh_token does not match the pattern.
    } else {
        return false; // refresh_token field exists but is not a string.
    }

    /* Free compiled regular expression */
    regfree(&regex);

    json_object_put(obj);
    json_tokener_free(tok);

    return is_valid;
}
```

This code uses the json-c library to parse and manipulate JSON data. It checks for each required field and its constraints, and then performs an optional check on the `refresh_token` field using a regular expression. 

