public class UserProcessor
{
    private ReaderWriterLockSlim _lock = new ReaderWriterLockSlim();

    public void ProcessLargeJSONFile(string filePath)
    {
        using (StreamReader reader = File.OpenText(filePath))
        {
            string json;
            while ((json = reader.ReadLine()) != null)
            {
                ThreadPool.QueueUserWorkItem(_ => ProcessUserData(json));
            }
        }
    }

    private void ProcessUserData(string json)
    {
        User user = JsonConvert.DeserializeObject<User>(json);

        _lock.EnterWriteLock();
        try
        {
            UpdateDatabase(user);
        }
        finally
        {
            _lock.ExitWriteLock();
        }
    }

    private void UpdateDatabase(User user)
    {
        using (SqlConnection connection = new SqlConnection("Your Connection String"))
        {
            connection.Open();

            using (SqlCommand command = new SqlCommand())
            {
                // Assuming your User class has properties such as Id, Name and Email
                string query = $"UPDATE Users SET Name='{user.Name}', Email='{user.Email}' WHERE Id={user.Id}";

                command.Connection = connection;
                command.CommandText = query;

                // Check if the user exists in the database before updating
                string countQuery = $"SELECT COUNT(*) FROM Users WHERE Id={user.Id}";
                int count = (int)new SqlCommand(countQuery, connection).ExecuteScalar();

                if (count > 0)  // User already exists, update the data
                    command.ExecuteNonQuery();
                else  // New user, insert a new row
                {
                    query = $"INSERT INTO Users VALUES({user.Id}, '{user.Name}', '{user.Email}')";
                    command.CommandText = query;
                    command.ExecuteNonQuery();
                }
            }
        }
    }
}

public class User
{
    public int Id { get; set; }
    public string Name { get; set; }
    public string Email { get; set; }
}
