using System;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Collections.Generic;

public class DataSetLoader {
    private Dictionary<string, object> cache = new Dictionary<string, object>();

    public T LoadAndProcessLargeDataset<T>(string filePath) where T : class {
        if (cache.ContainsKey(filePath)) return cache[filePath] as T;

        BinaryFormatter formatter = new BinaryFormatter();

        using (FileStream stream = new FileStream(filePath, FileMode.Open)) {
            try {
                object obj = formatter.Deserialize(stream);

                if (obj is T) {
                    cache[filePath] = obj;
                    return (T)obj;
                } else {
                    throw new InvalidCastException("The deserialized data does not match the expected type.");
                }
            } catch (IOException ex) {
                Console.WriteLine($"An error occurred while reading from file: {ex.Message}");
                return null;
            } finally {
                stream?.Close();
            }
        }
    }
}
```
