C function:
```c
#include <openssl/evp.h>
#include <openssl/rand.h>

typedef struct AES_ctx {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
    unsigned char iv[16];
} AES_ctx;

void cleanup(AES_ctx *aes) {
    if (aes->ctx != NULL) EVP_CIPHER_CTX_free(aes->ctx);
    OPENSSL_cleanse(&aes->key, sizeof(aes->key));
    OPENSSL_cleanse(&aes->iv, sizeof(aes->iv));
}

AES_ctx* initialize_cipher(const char *password) {
    AES_ctx *aes = calloc(1, sizeof(*aes));
    if (aes == NULL) return NULL;

    aes->ctx = EVP_CIPHER_CTX_new();
    if (aes->ctx == NULL) { cleanup(aes); return NULL; }

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    unsigned int iterations = 10000;

    // Ensure password is at least 16 characters
    if (strlen(password) < 16) {
        cleanup(aes); return NULL;
    }

    // Derive key and iv from password
    PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, iterations, EVP_sha256(), 32, aes->key);
    PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, iterations, EVP_sha256(), 16, aes->iv);

    if (EVP_CIPHER_CTX_set_padding(aes->ctx, 1) != 1 ||
        EVP_EncryptInit_ex(aes->ctx, cipher, NULL, aes->key, aes->iv) != 1) {
        cleanup(aes); return NULL;
    }

    return aes;
}
```
