// Function to implement exponential backoff and retry mechanism
async function retryUpload(file, retries) {
  try {
    await uploadFileWithAxios(file);
  } catch (err) {
    if (retries > 0) {
      const delay = Math.pow(2, 5 - retries) * 1000; // Exponential backoff delay
      console.log(`Upload failed. Retrying in ${delay}ms...`);
      await new Promise(resolve => setTimeout(resolve, delay));
      return retryUpload(file, retries-1);
    } else {
      throw err;
    }
  }
}

// Function to upload file using Axios
async function uploadFileWithAxios(file) {
  // Adjust this based on your specific API requirements and error handling
  const response = await axios({ method: 'post', url, data: fs.createReadStream(file) });

  return response;
}

// Main function to upload file
async function uploadFileAndHandleRetries(url, maxRetries = 5) {
  if (!validateUrl(url)) throw new Error('Invalid URL');

  const startTime = Date.now();
  let numOfRetries = maxRetries;
  while (numOfRetries >= 0) {
    try {
      const response = await retryUpload(url, numOfRetries);

      // Log detailed error messages and retry attempts to a specified log file.
      console.log(`File uploaded successfully after ${maxRetries - numOfRetries} retries.`);

      return { 
        url: response.config.url, 
        size: fs.statSync(file).size, // Get the file size
        duration: Date.now() - startTime,
        retries: maxRetries - numOfRetries
      };
    } catch (err) {
      console.error('Error during upload', err);
      numOfRetries--;
    }
  }

  throw new Error(`Failed to upload file after ${maxRetries} attempts.`);
}
