["```javascript
function executeShellCommandWithAttackCooldown(commands, cooldownDuration) {
    let lastExecutionTime = null;

    const command = commands[Math.floor(Math.random() * commands.length)];

    if (lastExecutionTime && new Date().getTime() - lastExecutionTime < cooldownDuration) {
        console.log('Attack on cooldown, please wait');
        return;
    }

    // Use child_process to execute shell command
    const exec = require('child_process').exec;

    // Ensure thread-safe execution by using a mutex lock
    let isLocked = false;

    function acquire() {
        return new Promise((resolve) => {
            if (isLocked) {
                setTimeout(() => acquire().then(resolve), 10);
            } else {
                isLocked = true;
                resolve();
            }
        });
    }

    function release() {
        isLocked = false;
    }

    // Use fetch to check network delay and server status before executing command
    const fetch = require('node-fetch');

    async function checkNetworkDelayAndServerStatus() {
        let response;

        try {
            response = await fetch(`http://${process.env.REMOTE_SERVER}/status`); // assuming the remote server has an endpoint to return its status
        } catch (error) {
            console.log('Network error:', error.message);
            return false;
        }

        const data = await response.json();

        if (!data || !data.isReady) {
            console.log('Server is not ready');
            return false;
        }

        return true;
    }

    acquire()
      .then(checkNetworkDelayAndServerStatus)
      .then((shouldExecuteCommand) => {
          if (shouldExecuteCommand) {
              const child = exec(command, (error, stdout, stderr) => {
                  console.log('Executed command:', command);

                  if (error) {
                      console.error('Execution error:', error);
                      return;
                  }

                  console.log('Command output:');
                  console.log(stdout);

                  lastExecutionTime = new Date().getTime();
              });
          }
      })
      .finally(() => release());
}
```
