    private static final int AES_KEYLEN = 256;  // in bits

    public static void main(String[] args) throws NoSuchAlgorithmException, NoSuchPaddingException, IllegalBlockSizeException, BadPaddingException {
        Graph<Integer, DefaultWeightedEdge> g = new SimpleDirectedWeightedGraph<>(DefaultWeightedEdge.class);
        GnmRandomGraphGenerator generator = new GnmRandomGraphGenerator();
        int vertices = 10 + RANDOM.nextInt(20);  // random number of vertices between 10 and 30
        int edges = vertices * (vertices - 1) / 4;  // approximately half the number of edges as vertices
        generator.generateGraph(g, new Integer[vertices], new DefaultWeightedEdge(), vertices, edges);

        SecretKey key = generateSecretKey("password");
        Cipher cipher = Cipher.getInstance("AES/CBC/PKCS5Padding");
        cipher.init(Cipher.ENCRYPT_MODE, key);
        byte[] encryptedData = cipher.doFinal("Hello, world!".getBytes());
        System.out.println("Encrypted data: " + Base64.getEncoder().encodeToString(encryptedData));
    }

    private static SecretKey generateSecretKey(String password) throws NoSuchAlgorithmException {
        if (password == null || password.length() < 16) {
            throw new IllegalArgumentException("Password must be at least 16 characters");
        } else if (password.length() > 32) {
            password = password.substring(0, 32);  // truncate to 32 chars
        }
        return new SecretKeySpec(password.getBytes(), "AES");
    }
}
