```rust
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::fs::Metadata;
use std::ffi::OsString;
use libloading::library_filename;
use lazy_static::lazy_static;
use std::path::PathBuf;

lazy_static![SHARED_LIBRARIES: Mutex<HashMap<&'static str, Arc<Library>>> = Mutex::new(HashMap::new())];

struct Library {
    handle: libloading::Library,
    version: u64, // assuming the library has a version number
}

fn load_library(path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let metadata = match Metadata::new(path) {
        Ok(metadata) => metadata,
        Err(_) => return Err("Library not found".into()),
    };

    let modified_time = match metadata.modified()?.duration_since(std::time::UNIX_EPOCH) {
        Ok(duration) => duration.as_secs(),
        Err(_) => return Err("Couldn't get library version".into()),
    };

    let libraries = SHARED_LIBRARIES.lock().unwrap();

    if let Some(library) = libraries.get(path) {
