            return Ok(()); // library is already loaded and its version hasn't changed, so we can skip loading it again
        } else {
            libraries.remove(path); // remove old version of the library from cache before reloading
        }
    }

    let handle = libloading::Library::new(path)?;

    let configuration_object: OsString = unsafe { /* initialize your object using the API */ }; 

    libraries.insert(path, Arc::new(Library { handle, version: modified_time }));

    Ok(())
}
```
