['Here's a basic implementation in Python:

```python
import json
from abc import ABCMeta, abstractmethod

class Config(metaclass=ABCMeta):
    _registry = {}

    def __init__(self, data):
        self.data = data

    @abstractmethod
    def to_json(self):
        pass

    @staticmethod
    def from_json():
        pass

    @classmethod
    def register(cls, id, factory):
        cls._registry[id] = factory

    @classmethod
    def create(cls, id, data=None):
        if id not in cls._registry:
            raise ValueError("Unsupported configuration type")

        return cls._registry[id](data)

    def update(self, data):
        self.data = {**self.data, **data}

class DatabaseConfig(Config):
    def to_json(self):
        return json.dumps(self.data)

    @staticmethod
    def from_json(s):
        try:
            data = json.loads(s)
        except ValueError as e:
            raise ValueError("Invalid JSON for DatabaseConfig") from e

        return DatabaseConfig(data)

DatabaseConfig.register('database', DatabaseConfig.from_json)
```

This code defines the base class `Config` and subclass `DatabaseConfig` to manage database configurations. The registry is a static variable in the base class that maps IDs to factory functions for creating new instances of the classes. When a subclass is created, it's automatically registered with its own factory function.

The abstract methods `to_json` and `from_json` are implemented by each subclass to convert between instances of the class and JSON strings. 

A unit test for this code could look something like:

```python
def test_config():
    db = DatabaseConfig({"host": "localhost", "port": 5432})

    assert json.loads(db.to_json()) == {"host": "localhost", "port": 5432}

    db_from_json = Config.create('database', '{"user":"admin","password":"secret"}')
    assert isinstance(db_from_json, DatabaseConfig)
    assert db_from_json.data == {"host": "localhost", "port": 5432, "user":"admin","password":"secret"}

    try:
        Config.create('database', 'Invalid JSON')
        assert False, "Expected ValueError"
    except ValueError as e:
        assert str(e) == "Invalid JSON for DatabaseConfig"

test_config()
```
