Java version:
```java
import java.net.*;
import java.util.*;

public class URLStatusFetcher {
    private final Map<String, Integer> cache = new HashMap<>();

    public Map<URL, Integer> getLatestStatusCodes(List<URL> urls) {
        Map<URL, Integer> result = new HashMap<>();
        for (URL url : urls) {
            if (!cache.containsKey(url)) {
                try {
                    HttpURLConnection conn = (HttpURLConnection) url.openConnection();
                    conn.setRequestMethod("GET");
                    conn.connect();
                    int statusCode = conn.getResponseCode();
                    cache.put(url, statusCode);
                    result.put(url, statusCode);
                } catch (Exception ex) {
                    System.out.println("Failed to fetch status code for " + url + ". Error: " + ex.getMessage());
                }
            } else {
                result.put(url, cache.get(url));
            }
        }
        return result;
    }
}
```
C version:
```c
#include <stdio.h>
#include <pthread.h>
#include <curl/curl.h>

struct ThreadData {
    char* url;
};

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s)
{
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

void* fetchUrl(void *args) {
    struct ThreadData* data = (struct ThreadData*) args;
    CURL *curl;
    CURLcode res;

    curl = curl_easy_init();
    if(curl) {
        struct string s;

        init_string(&s);

        curl_easy_setopt(curl, CURLOPT_URL, data->url);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

        res = curl_easy_perform(curl);

        if(res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", 
                    curl_easy_strerror(res));
        } else {
            printf("%s fetched\n", data->url);
        }

        free(data->url);
        curl_easy_cleanup(curl);
    }

    free(data);

    return NULL;
}
```
This C version uses `libcurl` for HTTP requests which handles network connections and error handling in a more efficient way than the Java `HttpURLConnection` API. However, it is much less straightforward to implement a thread pool with proper resource management using raw pthreads library in C, so please be careful when writing C code that involves concurrency.
