#include <string.h>

typedef struct Config {
    char *mode;
    int blockSize;
    int ivLength;
} Config;

int loadConfig(const char *path, Config *config) {
    json_error_t error;
    json_t *root = json_load_file(path, 0, &error);

    if(!root) {
        fprintf(stderr, "Error loading config file: %s\n", error.text);
        return -1;
    }

    const char *modeStr = json_string_value(json_object_get(root, "mode"));

    if(!modeStr) {
        fprintf(stderr, "Invalid config file: missing 'mode'\n");
        return -1;
    } else {
        config->mode = strdup(modeStr);
    }

    json_t *blockSize = json_object_get(root, "blockSize");

    if(!json_is_integer(blockSize)) {
        fprintf(stderr, "Invalid config file: missing 'blockSize'\n");
        return -1;
    } else {
        config->blockSize = json_integer_value(blockSize);
    }

    json_t *ivLength = json_object_get(root, "ivLength");

    if(!json_is_integer(ivLength)) {
        fprintf(stderr, "Invalid config file: missing 'ivLength'\n");
        return -1;
    } else {
        config->ivLength = json_integer_value(ivLength);
    }

    json_decref(root);

    return 0;
}

int processStream(const char *path, const Config *config) {
    DES_cblock key;
    DES_key_schedule schedule;

    if(DES_random_key(&key) != 0) {
        fprintf(stderr, "Error generating random key\n");
        return -1;
    }

    if(DES_set_key_checked(&key, &schedule) != 0) {
        fprintf(stderr, "Error setting key\n");
        return -1;
    }

    int fd = open(path, O_RDONLY);

    if(fd == -1) {
        perror("Failed to open stream file");
        return -1;
    }

    unsigned char buffer[config->blockSize];
    size_t bytesRead;

    while((bytesRead = read(fd, buffer, config->blockSize)) > 0) {
        DES_ecb_encrypt(buffer, buffer, &schedule, 1);

        // Log operation here

        if(write(STDOUT_FILENO, buffer, bytesRead) != (ssize_t)bytesRead) {
            perror("Failed to write processed stream");
            return -1;
        }
    }

    close(fd);

    // Log operation here

    if(bytesRead == -1) {
        perror("Error reading stream file");
        return -1;
    }

    return 0;
}
```
This code uses the OpenSSL library for DES encryption and the Jansson library for JSON parsing. The loadConfig function loads a configuration from a JSON file, while the processStream function processes an encrypted data stream with the specified configuration. Note that this is just a basic implementation and does not fully cover all aspects of the problem statement.
