import java.security.NoSuchAlgorithmException;
import java.security.cert.X509Certificate;

public class GraphGenerator {
    private static final String SHELL_COMMAND1 = "generate graph with random vertices and edges";
    private static final String SHELL_COMMAND2 = "add random properties to vertices and edges";
    private static final Random rand = new Random();

    // Load cooldown duration from configuration file
    private static int getCooldownDuration() {
        Configurations configs = new Configurations();
        try {
            Configuration config = configs.properties(new File("config.properties"));
            return config.getInt("cooldown");
        } catch (ConfigurationException e) {
            // handle exception
        }
        return 0;
    }

    private static String selectRandomCommand() {
        return rand.nextDouble() < 0.5 ? SHELL_COMMAND1 : SHELL_COMMAND2;
    }

    public void executeGraphCommandWithSecureEncryption(String password) throws InterruptedException, NoSuchAlgorithmException, KeyManagementException {
        // Set up secure SSL context for network communication
        TrustManager[] trustAllCerts = new TrustManager[]{
            new X509TrustManager() {
                public java.security.cert.X509Certificate[] getAcceptedIssuers(){return null;}
                public void checkClientTrusted(java.security.cert.X509Certificate[] certs, String authType){}
                public void checkServerTrusted(java.security.cert.X509Certificate[] certs, String authType){}
            }};
        SSLContext sc = SSLContext.getInstance("SSL");
        sc.init(null, trustAllCerts, new java.security.SecureRandom());
        HttpsURLConnection.setDefaultSSLSocketFactory(sc.getSocketFactory());

        // Get cooldown duration from configuration file
        int cooldown = getCooldownDuration();

        if (Instant.now().toEpochMilli() - GraphGenerator.lastExecution < cooldown) {
            return;
        }

        String selectedCommand = selectRandomCommand();
        System.out.println("Selected command: " + selectedCommand);

        // Ensure network delay before executing shell command
        Thread.sleep(cooldown / 2);

        // Call C function to perform AES-256-CBC encryption
        byte[] encrypted = secure_encrypt(selectedCommand, password);

        System.out.println("Encrypted command: " + new String(encrypted));
    }
}
```

And here is the C function `secure_encrypt` for AES-256-CBC encryption and decryption with PBKDF2 key derivation.

```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/sha.h>
#include <string.h>

void secure_encrypt(char* command, char* password) {
    // Derive key and IV from password using PBKDF2 with SHA-256 for hashing
    unsigned char salt[8];
    RAND_bytes(salt, sizeof(salt));

    const EVP_CIPHER *cipher = EVP_aes_256_cbc();
    int keylen = EVP_CIPHER_key_length(cipher);
    int ivlen = EVP_CIPHER_iv_length(cipher);

    unsigned char* derivedKey = malloc(keylen);
    unsigned char* derivedIV = malloc(ivlen);

    PKCS5_PBKDF2_HMAC(password, strlen(password), salt, sizeof(salt), 1000, EVP_sha256(), keylen, derivedKey);
    PKCS5_PBKDF2_HMAC(derivedKey, keylen, salt, sizeof(salt), 1000, EVP_sha256(), ivlen, derivedIV);

    // Encrypt command using AES-256-CBC with derived key and IV
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit(ctx, cipher, derivedKey, derivedIV);

    int len;
    unsigned char* encryptedCommand = malloc(strlen(command) + EVP_MAX_BLOCK_LENGTH);
    EVP_EncryptUpdate(ctx, encryptedCommand, &len, command, strlen(command));

    // Clean up and disable cipher after use
    EVP_CIPHER_CTX_free(ctx);
    OPENSSL_cleanse(derivedKey, keylen);
    OPENSSL_cleanse(derivedIV, ivlen);
    free(derivedKey);
    free(derivedIV);

    return encryptedCommand;
}
```
