    private int minValue, maxValue;
    private ObjectInputStream inputStream;

    public FileBasedRandomValueGenerator(int min = 0, int max = 100)
    {
        if (min > max) throw new ArgumentException("Minimum value cannot be greater than maximum value");

        this.minValue = min;
        this.maxValue = max + 1;
    }

    public float GetRandomFloat()
    {
        Random rand = new Random();
        double val = rand.NextDouble();

        return (float)(val * (this.maxValue - this.minValue) + this.minValue);
    }

    public int GetRandomInt()
    {
        Random rand = new Random();
        return rand.Next(this.minValue, this.maxValue);
    }

    public int GetRandomIntInRange(int min, int max)
    {
        if (min >= max) throw new ArgumentException("Minimum value cannot be greater than or equal to maximum value");

        Random rand = new Random();
        return rand.Next(min, max);
    }

    public override string ToString()
    {
        return $"Range: [{this.minValue}, {this.maxValue})";
    }

    public MoSTState LoadStateFromFile(string filename)
    {
        this.inputStream = new ObjectInputStream(new FileStream(filename, FileMode.Open));

        try
        {
            object obj = inputStream.readObject();

            if (obj is MoSTState) return (MoSTState)obj;
            else return null;
        }
        catch (Exception e)
