```java
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.util.*;
import java.time.*;

public class BatchProcessor {
    private static final int VALID_TIMESTAMP_RANGE = 60 * 60 * 24 * 30; // 30 days in seconds

    public Map<String, Object> processBatchData(List<Record> batch) {
        long startTime = System.currentTimeMillis();

        Map<String, Object> resultMap = new HashMap<>();
        List<Record> validRecords = new ArrayList<>();
        StringBuilder hashInput = new StringBuilder();

        // validate and process each record in parallel
        batch.parallelStream().forEach(record -> {
            try {
                if (isValidUserId(record) && isValidAmount(record) && isValidTimestamp(record)) {
                    validRecords.add(record);
                    hashInput.append(concatRecordFields(record));
                } else {
                    System.out.println("Invalid record: " + record);
                }
            } catch (Exception e) {
                System.err.println("Error processing record: " + record);
                e.printStackTrace();
            }
        });

        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");

            byte[] hashBytes = digest.digest(hashInput.toString().getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();

            for (byte b : hashBytes) {
                hexString.append(String.format("%02x", b));
            }

            resultMap.put("hash", hexString.toString());
        } catch (NoSuchAlgorithmException e) {
            System.err.println("Failed to generate SHA-256 hash");
            e.printStackTrace();
        }

        int totalAmount = validRecords.stream().mapToInt(Record::getTransactionAmount).sum();
        resultMap.put("total", totalAmount);

        long duration = System.currentTimeMillis() - startTime;
        System.out.println("Processing took " + duration + " milliseconds");

        return resultMap;
    }

    private String concatRecordFields(Record record) {
        return record.getUserId() + "," 
            + Integer.toString(record.getTransactionAmount()) + "," 
            + Long.toString(record.getTimestamp());
    }

    private boolean isValidUserId(Record record) {
        return record.getUserId() != null && !record.getUserId().isEmpty();
    }

    private boolean isValidAmount(Record record) {
        return record.getTransactionAmount() >= 0;
    }

    private boolean isValidTimestamp(Record record) {
        long now = Instant.now().getEpochSecond();

        return Math.abs(record.getTimestamp() - now) <= VALID_TIMESTAMP_RANGE;
    }
}
```
In this example, I assume you have a `Record` class that contains getters for the user ID, transaction amount, and timestamp fields. This is just one possible implementation and there might be other ways to solve this problem depending on your exact requirements and constraints. For instance, you may need to adjust the validation rules or add more sophisticated error handling. Please replace the record class with your actual class name.
']

