['Here is the C++ function you requested. Note that this solution uses STL `forward_list` and its associated functions. Also, it assumes that each filename in the list has only one period (.) and no other periods in between which are part of the actual filename but not extension. 

```cpp
#include <string>
#include <forward_list>
#include <cstdio>
#include <iostream>
using namespace std;

void modifyFileNameAndInsertString(forward_list<string>& flist, const string& targetFilename, const string& newExtension) {
    auto it = flist.begin();
    bool found = false;
    for (; it != flist.end(); ++it) {
        if (*it == targetFilename) {
            found = true;
            break;
        }
    }

    // If target filename is not found, append new extension to the end of the list and return.
    if (!found) {
        flist.insert_after(flist.before_begin(), newExtension);
        return;
    }

    int numberOfDigits = 0;
    for (char c : *it) {
        if (isdigit(c)) ++numberOfDigits;
    }

    char buffer[100];
    sprintf(buffer, "%d%s", numberOfDigits, newExtension.c_str());

    // Find position of last period in filename and replace extension
    size_t pos = it->rfind('.');
    if (pos != string::npos) {
        *it = it->substr(0, pos + 1) + buffer;
    } else {
        *it += buffer;
    }
}
```
