['Here is a C# class that fulfills the requirements you provided:

```csharp
using System;

public enum DistributionType { Uniform, Normal, Exponential }

public class RandomValueGenerator
{
    private Random _randomNumberGen;
    private int _lastGeneratedVal;
    private DistributionType _currentDistribution = DistributionType.Uniform;

    public RandomValueGenerator(int seed = 0) {
        _randomNumberGen = new Random(seed);
    }

    public void SetSeed(int seed) {
        _randomNumberGen = new Random(seed);
    }

    public int NextUniform(int min, int max) {
        _currentDistribution = DistributionType.Uniform;
        return _lastGeneratedVal = _randomNumberGen.Next(min, max + 1);
    }

    public float NextNormal(float mean, float stdDev) {
        // Note: This is a simplistic implementation using Box-Muller transform to generate normally distributed random numbers
        double u1 = 1.0 - _randomNumberGen.NextDouble(); 
        double u2 = 1.0 - _randomNumberGen.NextDouble();
        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2);
        return (float)(_lastGeneratedVal = mean + stdDev * randStdNormal);
    }

    public float NextExponential(float lambda) {
        _currentDistribution = DistributionType.Exponential;
        double uniformRandomValue = _randomNumberGen.NextDouble();
        return (float)(_lastGeneratedVal = (-1 / lambda) * Math.Log(1 - uniformRandomValue));
    }

    public override string ToString() {
        return $"Seed:{_randomNumberGen.GetHashCode()}, Last Generated Value:{_lastGeneratedVal}, Current Distribution:{_currentDistribution}";
    }
}
``` 
Please note that this code uses the Box-Muller transform to generate normally distributed random numbers, which is a common method but it's not exact due to the limitations of floating point precision. If you need more accurate results for normal distributions, consider using an external library or implementing your own implementation.
