import java.util.stream.Collectors;

public class Main {
    public static void main(String[] args) throws Exception {
        System.out.println("MD5 hash of 'Hello-World': " + computeAndLogHash("Hello", "World")); // Expected: ed076287532e86365e841e92bfc50d8c9
    }

    public static String computeAndLogHash(String... args) {
        Instant startTime = Instant.now();

        // Concatenate all input strings with a hyphen separator using Java 8 Streams
        String strToHash = Arrays.stream(args).collect(Collectors.joining("-"));

        try {
            // Compute MD5 hash
            String hashedStr = Hashing.md5().hashString(strToHash, StandardCharsets.UTF_8).toString();

            // Log duration of computation and the resulting hash
            Duration duration = Duration.between(startTime, Instant.now());
            System.out.println("Hashed '" + strToHash + "' in " + duration.toMillis() + "ms: " + hashedStr);

            return hashedStr;
        } catch (Exception e) {
            // Log exception details
            System.err.println("Failed to hash string after " + Duration.between(startTime, Instant.now()).toMillis() + "ms: " + e);
            throw e;
        }
    }
}
```
