void addContext(LTE_RRC_UE_CONTEXT_T* context) {
    pthread_mutex_lock(&lock);  // acquire lock to avoid concurrent access

    if (size == 5000){
        printf("Maximum limit reached. Cannot add more contexts.\n");
        return;
    }

    if (!isValidIP(context->ip_address)) {
        printf("Invalid IP address. Context not added.\n");
        fprintf(logFile, "Addition of context with invalid IP failed: %s\n", context->ip_address);  // log failure
        return;
