    contextArray = realloc(contextArray, sizeof(*contextArray) * (size + 1));  // increase size of array
    contextArray[size++] = context;  // add new context to end of array

    fprintf(logFile, "Addition of context successful: %s\n", contextToJSON(context));  // log success

    pthread_mutex_unlock(&lock);  // release lock
}

void updateContext(int index, LTE_RRC_UE_CONTEXT_T* newContext) {
    if (index >= 0 && index < size) {
        free(contextArray[index]->buffer);  // free old buffer before updating

        contextArray[index] = newContext;  // update context at given index

        fprintf(logFile, "Update of context successful: %s\n", contextToJSON(newContext));  // log success
    } else {
        printf("Index out of bounds. Update failed.\n");
        fprintf(logFile, "Update of context with invalid index failed: %d\n", index);  // log failure
    }
}

void deleteContext(int index) {
    if (index >= 0 && index < size) {
        free(contextArray[index]->buffer);  // free buffer before deleting

        for (int i = index; i < size - 1; ++i) {
            contextArray[i] = contextArray[i + 1];  // shift elements to fill gap
        }

        --size;

        contextArray = realloc(contextArray, sizeof(*contextArray) * size);  // decrease array size

        fprintf(logFile, "Deletion of context successful: %d\n", index);  // log success
    } else {
        printf("Index out of bounds. Deletion failed.\n");
        fprintf(logFile, "Deletion of context with invalid index failed: %d\n", index);  // log failure
    }
}
