public class DatabaseRandomValueGenerator : IDisposable
{
    private readonly Random _random;
    private DistributionType _currentDistribution = DistributionType.Uniform;
    private int? _lastGenerated;

    public enum DistributionType { Uniform, Normal, Exponential, Triangular }

    public DatabaseRandomValueGenerator(int seed)
    {
        _random = new Random(seed);
    }

    public void SetSeed(int seed)
    {
        lock (_random)
        {
            _random = new Random(seed);
        }
    }

    public int NextUniform(int min, int max)
    {
        _currentDistribution = DistributionType.Uniform;
        return _lastGenerated = _random.Next(min, max + 1);
    }

    public float NextNormal(float mean, float stdDev)
    {
        _currentDistribution = DistributionType.Normal;
        double u1 = 1.0 - _random.NextDouble(); //uniform(0,1] random doubles
        double u2 = _random.NextDouble();
        double randStdNormal = Math.Sqrt(-2.0 * Math.Log(u1)) * Math.Sin(2.0 * Math.PI * u2); //random normal(0,1)
        return _lastGenerated = (int)(mean + stdDev * randStdNormal); 
    }

    public int NextExponential(float lambda)
    {
        _currentDistribution = DistributionType.Exponential;
        double uniformRandomValue = _random.NextDouble();
        return _lastGenerated = (int)(-Math.Log(1 - uniformRandomValue) / lambda); 
    }

    public override string ToString()
    {
        lock (_random)
        {
            return $"Seed: {_random.GetHashCode()}, Last Generated Value: {_lastGenerated?.ToString() ?? "None"}, Current Distribution Type: {_currentDistribution}";
        }
    }

    public DataTableReader GetData(byte[] data)
    {
        // Assuming some method DatabaseQuery that sends the byte array to a database server and returns a DataTableReader.
        // return DatabaseQuery(data); 
    }

    public void Dispose()
    {
        _random?.Dispose();
    }
}
```
']

