```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include "json-c/json.h"

typedef struct {
    char mac[20];
    int crnti;
    void* sib_buffer;
    size_t buffer_size;
} LTE_RRC_UE_CONTEXT_T;

#define MAX_BUFFER 1024
#define MAX_CONTEXTS 5000
LTE_RRC_UE_CONTEXT_T contexts[MAX_CONTEXTS];
int num_contexts = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_context(char* mac, int crnti) {
    // Validate MAC address here

    pthread_mutex_lock(&lock);
    if (num_contexts < MAX_CONTEXTS) {
        strncpy(contexts[num_contexts].mac, mac, sizeof(contexts[num_contexts].mac));
        contexts[num_contexts].crnti = crnti;
        contexts[num_contexts].sib_buffer = malloc(MAX_BUFFER);
        contexts[num_contexts].buffer_size = MAX_BUFFER;
        ++num_contexts;
    } else {
        fprintf(stderr, "Maximum number of contexts reached\n");
    }
    pthread_mutex_unlock(&lock);
}

void remove_context(int crnti) {
    // Find and delete the context here
    pthread_mutex_lock(&lock);
    for (int i = 0; i < num_contexts; ++i) {
        if (contexts[i].crnti == crnti) {
            free(contexts[i].sib_buffer);
            contexts[i] = contexts[num_contexts - 1];
            --num_contexts;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

char* export_to_json() {
    json_object *jobj = json_object_new_array();

    for (int i = 0; i < num_contexts; ++i) {
        json_object *jtmp = json_object_new_object();
        json_object_object_add(jtmp,"mac", json_object_new_string(contexts[i].mac));
        json_object_object_add(jtmp,"crnti", json_object_new_int(contexts[i].crnti));
        json_object_array_add(jobj, jtmp);
    }

    return (char*)json_object_to_json_string(jobj);
}
```
This is just a sample code that shows how you can create and manage contexts. To implement the remaining features like periodic context purging, logging, integration with external systems etc., would require a more comprehensive approach and possibly multiple files and functions. Moreover, this code assumes a lot of things (like memory allocated for SIB buffer) which are not mentioned in your question but should be considered in real-world applications.
