['Here is a simple implementation in C using mmap for large scale memory allocation, munmap for unmapping, and rand() with srand() to generate random values. Note that this is an illustrative example and might not fulfill all your requirements perfectly but will provide the basic idea. 

The example uses an array of structures which consist key (an integer) and offset (a long). Each struct's size is assumed as 12 bytes due to padding by the compiler (4 byte for int + 4 byte for long). 

```c
#include <stdio.h>
#include <sys/mman.h>
#include <unistd.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

Record *allocate_records(size_t num, size_t seed) {
    srand((unsigned int) time(NULL) + (seed & 0xFFFF)); // use the least significant bits of the seed for random number generation
    Record *records = mmap(NULL, sizeof(*records) * num, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (records == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    for(size_t i=0;i<num;++i){
        records[i].key = rand();
        records[i].offset = (long)rand() * RAND_MAX + rand(); // generate a random long number
    }

    return records;
}

void deallocate_records(Record *records, size_t num) {
    if (munmap(records, sizeof(*records) * num)) {
        perror("munmap");
    }
}
```

To allocate records:
