#include <time.h>

typedef struct {
    int key;
    long offset;
} Record;

Record* records = NULL;
int num_records = 0;
int max_records = 0;
pthread_mutex_t lock;

void initialize() {
    srand(time(NULL)); // Initialize seed for pseudo-random number generation

    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Failed to initialize mutex\n");
        exit(1);
    }
}

int fetch_key() {
    // Asynchronous fetching and caching logic goes here.
    return rand();  // Placeholder for external data source or async fetch
}

void add_record(long offset) {
    pthread_mutex_lock(&lock);

    if (num_records >= max_records) {
        max_records = max_records * 2 + 1; // Expand records array when it's full

        Record* new_records = realloc(records, max_records * sizeof(Record));
        if (new_records == NULL) {
            fprintf(stderr, "Failed to allocate memory\n");
            pthread_mutex_unlock(&lock);  // Unlock before returning
            return;
        }

        records = new_records;
    }

    Record* record = &records[num_records++];
    record->key = fetch_key();
    record->offset = offset;

    pthread_mutex_unlock(&lock);
}

void update_record(int key, long new_offset) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_records; ++i) {
        if (records[i].key == key) {
            records[i].offset = new_offset;
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}

void delete_record(int key) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < num_records; ++i) {
        if (records[i].key == key) {
            records[i] = records[--num_records];  // Overwrite with last record
            break;
        }
    }

    pthread_mutex_unlock(&lock);
}
```
This is a simple example and lacks many of the more complex aspects of distributed systems that you would need in practice. It's designed to highlight key principles, but real-world code would be much more complex and likely involve significant use of libraries or frameworks for threading, networking, memory management, logging, etc.
