    RX_UE_INFORMATION_TAG info;
    CRC_INDICATION_REL8_TAG crc;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // for thread safety

NFAPI_CRC_INDICATION_PDU_T* create_structs(int num) {
    if (num <= 0) return NULL; // invalid input parameters check

    srand(time(NULL));  // seed random number generator

    NFAPI_CRC_INDICATION_PDU_T *arr = calloc(num, sizeof(*arr));
    if (!arr) {
        log_info("Memory allocation failed!");
        return NULL;
    }

    pthread_mutex_lock(&lock);  // acquire the lock to ensure thread safety

    for (int i = 0; i < num; ++i) {
        arr[i].crc.CRCFLAG = rand() % 256; // set CRCFLAG with random value
        log_info("Created structure #%d with RNTI: %d and CRCFLAG: %hhu", i, arr[i].info.RNTI, arr[i].crc.CRCFLAG);
    }

    pthread_mutex_unlock(&lock); // release the lock after modifying data

    return arr;
}
