    if(strcmp(modeStr, "ECB") == 0) {
        mode = ECB;
    } else if(strcmp(modeStr, "EDE") == 0) {
        mode = EDE;
    } else if(strcmp(modeStr, "EDE3") == 0) {
        mode = EDE3;
    } else {
        handleError("Invalid Mode");
    }

    return mode;
}

int main() {
    // Read the configuration file
    MODE mode = readConfigFile();

    DES_cblock key, iv;
    unsigned char in[BUFFER_SIZE], out[BUFFER_SIZE];
    int len;

    // Initialize encryption
    DES_key_schedule schedule;
    if(mode == ECB) {
        DES_set_key(&key, &schedule);
    } else if (mode == EDE || mode == EDE3) {
        DES_set_2key_checked(&key, &iv, &schedule);
    }

    // Example of encryption using the configured mode
    for(;;) {
        len = fread(in, 1, sizeof in, stdin);
        if (ferror(stdin)) handleError("Read error");
        DES_ecb2_encrypt(&in, &out, len, &schedule, &iv, DES_ENCRYPT);
        fwrite(out, 1, len, stdout);
    }

    return 0;
}
```
