```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.time.*;
import java.util.logging.*;
import java.util.stream.*;
import java.util.concurrent.*;

class Transaction {
    String customerId;
    double amount;
    String currencyType;
    LocalDate transactionDate;
}

public class Main {

    private static final Logger logger = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) throws NoSuchAlgorithmException {
        // Assuming transactions come in as a list of Transaction objects...
        List<Transaction> transactionList = getTransactions();
        processFinancialTransactions(transactionList);
    }

    private static Map<String, String> processFinancialTransactions(List<Transaction> transactions) throws NoSuchAlgorithmException {

        Set<String> validCurrencies = new HashSet<>(Arrays.asList("USD", "EUR")); // List of supported currencies
        int batchSize = 500; 

        MessageDigest md = MessageDigest.getInstance("MD5");

        Instant startTime = Instant.now();

        Map<String, String> resultMap = transactions.parallelStream()
            .map(transaction -> {
                // Validation of each transaction record goes here...
                if (validCurrencies.contains(transaction.currencyType) 
                    && !transaction.customerId.isEmpty() 
                    && transaction.amount > 0){

                    String hash = bytesToHex(md.digest((transaction.customerId + "," + 
                                                       transaction.amount + "," + 
                                                       transaction.currencyType + "," +
                                                       transaction.transactionDate).getBytes(StandardCharsets.UTF_8))); 

                    return new AbstractMap.SimpleEntry<>(hash, transaction);
                } else {
                    logger.info("Invalid record: " + transaction.toString());
                    return null; // Skipping invalid records
                }
            })
            .collect(Collectors.groupingBy(entry -> entry.getValue().transactionDate)) // Groups by date (batch)
            .entrySet()
            .stream()
            .map(entry -> { 
                String batchSummary = getBatchSummary(entry.getValue()); // Aggregate each batch's data

                return new AbstractMap.SimpleEntry<>(
                    bytesToHex(md.digest((batchSummary).getBytes(StandardCharsets.UTF_8))), // Generating unique identifier for the batch
                    batchSummary); 
            })
            .collect(Collectors.toMap(Map.Entry::getKey, Map.Entry::getValue)); // Collecting to a map

        Instant endTime = Instant.now();
        logger.info("Processing duration: " + Duration.between(startTime, endTime).toMillis() + " ms"); 

        return resultMap;
    }

    private static String getBatchSummary(List<Map.Entry<String, Transaction>> batch){
      // Implementation of summary report for each batch
      double totalAmount = 0;

      for(Map.Entry<String, Transaction> entry : batch) { 
          totalAmount += entry.getValue().amount;
      }

      return "Total Amount: " + totalAmount + ", Average Amount: " + (totalAmount / batch.size());
    }

    // Convert bytes to hexadecimal for readability
    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) 
                hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

}
```

This is a simplified example, and the actual implementation may differ based on the specific requirements of your project, such as how to get transactions or handle exceptions. Also please note that logging should be used with care in production code, as it can have significant performance implications if not managed properly. 

Remember also, this sample does not include any validation checks for transaction date (such as ensuring it falls within a valid range and format), as these would depend on your specific project requirements.
