import java.util.concurrent.CompletableFuture;
import java.text.*;
import java.time.*;

public class Main {
    private static final Map<String, String> cache = new HashMap<>();
    private static final SimpleDateFormat sdf = new SimpleDateFormat("yyyy.MM.dd.HH.mm.ss");

    public static void main(String[] args) {
        System.out.println(hashFileOrContentAsync("input_file.txt").join());
    }

    private static CompletableFuture<String> hashFileOrContentAsync(String input){
        return (isValidPath(input)) ? readAndHashFileAsync(input) : CompletableFuture.completedFuture(hashContent(input));
    }

    private static CompletableFuture<String> readAndHashFileAsync(String path) {
        return CompletableFuture.supplyAsync(() -> {
            try (BufferedReader br = new BufferedReader(new FileReader(path, StandardCharsets.UTF_8))) {
                StringBuilder sb = new StringBuilder();
                String line;
                while ((line = br.readLine()) != null) {
                    sb.append(line).append("\n");
                }
                return hashContent(sb.toString());
            } catch (IOException e) {
                logError("Could not read file " + path, e);
                return "";
            }
        });
    }

    private static String hashContent(String content){
        if (!cache.containsKey(content)){
            try{
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                byte[] hashBytes = digest.digest(content.getBytes(StandardCharsets.UTF_8));

                StringBuilder hexString = new StringBuilder();
                for (byte b : hashBytes) {
