// Global variables
Record* records = NULL;
Algorithm* algorithms = NULL;
pthread_mutex_t record_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t algorithm_lock = PTHREAD_MUTEX_INITIALIZER;

// Forward declarations
Record* get_record(int key);
Algorithm* get_algorithm(char* name);
