void add_algorithm(char* name, void* implementation, char** config_options);
void cleanup();

// Example usage:
int main() {
    // Initialize records and algorithms...

    return 0;
}

Record* get_record(int key) {
    pthread_mutex_lock(&record_lock);
    Record* record = NULL;
    // Lookup the record in records linked list...
    if (!record) {
        syslog(LOG_INFO, "Record not found: %d", key);
    } else {
        syslog(LOG_DEBUG, "Record found: %d", key);
    }
    pthread_mutex_unlock(&record_lock);
    return record;
}

Algorithm* get_algorithm(char* name) {
    pthread_mutex_lock(&algorithm_lock);
    Algorithm* algorithm = NULL;
    // Lookup the algorithm in algorithms linked list...
    if (!algorithm) {
        syslog(LOG_INFO, "Algorithm not found: %s", name);
    } else {
        syslog(LOG_DEBUG, "Algorithm found: %s", name);
    }
    pthread_mutex_unlock(&algorithm_lock);
    return algorithm;
}

void add_record(int key, long offset_value) {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        syslog(LOG_ERR, "Failed to allocate memory for new record");
        exit(EXIT_FAILURE);
    }

    // Initialize the record...
}

void add_algorithm(char* name, void* implementation, char** config_options) {
    Algorithm* algorithm = malloc(sizeof(Algorithm));
    if (!algorithm) {
        syslog(LOG_ERR, "Failed to allocate memory for new algorithm");
        exit(EXIT_FAILURE);
    }

    // Initialize the algorithm...
}

void cleanup() {
    Record* record = records;
    while (record) {
        Record* next = record->next;
        free(record);
        record = next;
    }

    Algorithm* algorithm = algorithms;
    while (algorithm) {
        Algorithm* next = algorithm->next;
        dlclose(algorithm->implementation);
        free(algorithm);
        algorithm = next;
    }
}
``` 
Please remember, this is a simplified example. A real-world implementation would involve more considerations for thread safety, error checking and handling, efficient memory management, asynchronous fetching of external data, library dependency checks, dynamic library loading and unloading, multi-node synchronization etc. Also, the cleanup function assumes that all threads have finished their work before it's called. In a real-world scenario, you would need to implement a way to ensure all threads are done with all resources before cleaning them up.
