import java.util.*;

public class DOMTraversal {
    private static final Object LOCK = new Object();

    public interface Selector {
        boolean matches(Element element);
    }

    public List<Element> traverseDOM(Element root, Selector selector) {
        synchronized (LOCK) {
            if(root == null || selector == null) return Collections.emptyList();

            List<Element> result = new ArrayList<>();

            if(selector.matches(root)) result.add(root);

            for(Element child : root.getChildren()) {
                result.addAll(traverseDOM(child, selector));
            }

            return result;
        }
    }
}
