['Here is an implementation of the `FileBasedRandomValueGenerator` class in C#, considering all your requirements and making sure to handle all edge cases:

```csharp
using System;
using System.IO;
using System.Text;

public class FileBasedRandomValueGenerator : IDisposable
{
    private float minValue = -100f;
    private float maxValue = 100f;
    private Random random = new Random();

    public FileBasedRandomValueGenerator() { }

    public FileBasedRandomValueGenerator(float min, float max)
    {
        if (min < max)
        {
            this.minValue = min;
            this.maxValue = max;
        }
    }

    public void GenerateSeed(int seed) => random = new Random(seed);

    public float GetRandomFloat()
        => (float)(random.NextDouble() * (maxValue - minValue) + minValue);

    public int GetRandomIntInRange(int min, int max)
        => random.Next(min, max);

    public int GetRandomInt() => GetRandomIntInRange((int)minValue, (int)maxValue + 1);

    public string GenerateRandomString(int length)
    {
        var sb = new StringBuilder();

        for(var i=0;i<length;i++) 
            sb.Append(Convert.ToChar(random.Next(65, 83))); // using a predefined set of characters A-S for example

        return sb.ToString();
    }

    public StateObject LoadStateFromFile<T>(string filePath) where T : class
    {
        try
        {
            var state = default(StateObject);

            using (var reader = new StreamReader(filePath))
                while (!reader.EndOfStream)
                    if ((state = JsonConvert.DeserializeObject<T>(reader.ReadLine())) != null) 
                        break; // assuming we read state line by line

            return (StateObject)state ?? throw new FileNotFoundException();
        }
        catch (FileNotFoundException ex)
        {
            Console.WriteLine("Error loading the file: " + ex.Message);
            return null;
        }
    }

    public override string ToString() 
        => $"Range: [{minValue}, {maxValue})";

    private bool disposed = false;

    protected virtual void Dispose(bool disposing)
    {
        if (!disposed && disposing) random = null;
        disposed = true;
    }

    public void Dispose()
    {
        Dispose(true);
        GC.SuppressFinalize(this);
    }
}
```
This class should be used with caution since the file reading is not asynchronous, which means it will block the program until the operation is done. Also, for performance-critical applications that need to generate large amounts of random numbers in a short time span, you might want to use some other method such as cryptographic generators or `System.Security.Cryptography.RandomNumberGenerator` class. 
Finally, make sure to replace the path for `filePath` with an actual filepath on your system.
