public class OrderProcessing {
    private ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public ConfirmationToken processCustomerOrder(String orderId, CustomerDetails customerDetails, PaymentInformation paymentInformation) 
        throws NoSuchAlgorithmException {

        // validate the order ID and customer details here...

        String concatData = orderId + ";" + customerDetails.toString();
        MessageDigest md5Hasher = MessageDigest.getInstance("MD5");
        byte[] hashedBytes = md5Hasher.digest(concatData.getBytes(StandardCharsets.UTF_8));

        String hashedConcatData = bytesToHex(hashedBytes);

        if (cache.containsKey(orderId)) { // check if order ID is in cache
            return new ConfirmationToken(orderId, cache.get(orderId));
        } else {
            String randomSequence = generateRandomAlphanumericString();

            String finalHashedValue = hashedConcatData + randomSequence;
            cache.put(orderId, finalHashedValue); // add the result to the cache

            return new ConfirmationToken(orderId, finalHashedValue);
        } 
    }

    private String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder();
        for (byte b : hash) {
            String hex = Integer.toHexString(0xff & b);
            if(hex.length() == 1) 
                hexString.append('0');
            hexString.append(hex);
