    public Map<String, Object> processFinancialTransactions(List<TransactionRecord> records) {
        // Validate and hash each record
        List<CompletableFuture<String>> hashFutures = new ArrayList<>();
        for (TransactionRecord record : records) {
            CompletableFuture<String> future = CompletableFuture.supplyAsync(() -> 
                validateAndHash(record), ForkJoinPool.commonPool());
            hashFutures.add(future);
        }

        // Create summary report and aggregate all the hashes
        Map<String, Object> resultMap = new HashMap<>();
        List<CompletableFuture<Void>> summaryReportFutures = new ArrayList<>();
        for (int i = 0; i < records.size(); i += MAX_BATCH_SIZE) {
            int endIndex = Math.min(i + MAX_BATCH_SIZE, records.size());
            CompletableFuture<Void> summaryReportFuture = FutureUtils.allOf(hashFutures.subList(i, endIndex))
                .thenAccept(hashes -> {
                    String batchId = DigestUtils.md5Hex(String.join(",", hashes));
                    Map<String, Object> summaryReport = computeSummaryReport(records.subList(i, endIndex), batchId);
                    resultMap.put("Batch " + (i / MAX_BATCH_SIZE + 1) + " Summary Report", summaryReport);
                });
            summaryReportFutures.add(summaryReportFuture);
        }

        // Wait for all futures to complete and return the final map
        CompletableFuture<Void> allDone = FutureUtils.allOf(summaryReportFutures)
            .whenComplete((voidValue, throwable) -> {
                if (throwable != null) {
                    log.error("An error occurred while processing transactions", throwable);
