        boost::lock_guard<boost::mutex> lock(mtx_);

        if (sessions_.size() >= MAX_SESSIONS) {
            purgeExpiredSessions();
        }

        UserSession newSession;
        newSession.sessionID = id;
        newSession.buffer = buffer;
        newSession.bufferSize = bufferSize;
        newSession.ipAddress = ipAddress;
        newSession.port = port;
        newSession.metadata = boost::make_shared<SessionMetaData>();
        newSession.lastActivityTime = std::chrono::system_clock::now();

        sessions_.insert(std::make_pair(id, newSession));
    }

    void updateSessionBuffer(unsigned int id, char* buffer, size_t bufferSize) {
        boost::lock_guard<boost::mutex> lock(mtx_);

        auto it = sessions_.find(id);
        if (it != sessions_.end()) {
            delete[] it->second.buffer; // clean up old buffer first

            it->second.buffer = new char[bufferSize];
            std::copy(buffer, buffer + bufferSize, it->second.buffer);
            it->second.bufferSize = bufferSize;
        }
    }

    void purgeExpiredSessions() {
        boost::lock_guard<boost::mutex> lock(mtx_);

        auto now = std::chrono::system_clock::now();
        if (std::chrono::duration_cast<std::chrono::seconds>(now - lastPurgeTime_).count() < PURGE_INTERVAL) {
            return; // it's not time to purge yet
        }

        for (auto it = sessions_.begin(); it != sessions_.end(); ) {
            if (std::chrono::duration_cast<std::chrono::seconds>(now - it->second.lastActivityTime).count() > 300) { // purge sessions that haven't been active for 5 minutes
                delete[] it->second.buffer;
                it = sessions_.erase(it);
            } else {
                ++it;
            }
        }

        lastPurgeTime_ = now;
    }

    static std::string getMD5Hash(const std::string& input) {
        unsigned char digest[MD5_DIGEST_LENGTH];
        MD5((unsigned char*)input.c_str(), input.size(), digest);    

        std::ostringstream sout;
        sout<<std::hex<<std::setfill('0');
        for(long long c: digest) 
            sout<<std::setw(2)<<(unsigned int)c;

        return sout.str();
    }

    // ... more methods go here
};
```
This code uses Boost's `shared_ptr` for reference-counted pointer and `lock_guard` to ensure thread safety. It also makes use of the OpenSSL library for MD5 hashing. This is a rudimentary design and could be improved upon significantly depending on your specific needs or constraints (like adding error checking, implementing logging, etc.).
