import java.net.*;
import java.util.*;
import java.io.*;

public class HttpStatusFetcher {
    private Map<String, Integer> cache = new HashMap<>();
    private List<URL> urls;

    public HttpStatusFetcher(List<URL> urls) {
        this.urls = new ArrayList<>(urls);
        refreshCache(); // Initialize the cache
    }

    public void updateUrls(List<URL> urls) {
        this.urls = new ArrayList<>(urls);
        refreshCache(); // Refresh the cache after URLs change
    }

    private String getHostFromUrl(String url) {
        try {
            URI uri = new URI(url);
            return uri.getHost();
        } catch (URISyntaxException e) {
            e.printStackTrace();
        }
        return null;
    }

    public Map<String, Integer> getStatuses() {
        refreshCache();
        return cache;
    }

    private void refreshCache() {
        for (URL url : urls) {
            String host = getHostFromUrl(url.toString());

            try {
                HttpURLConnection conn = (HttpURLConnection) url.openConnection();
                int statusCode = conn.getResponseCode();
                cache.put(host, statusCode); // Update the cache

            } catch (IOException e) {
                System.err.println("Failed to get HTTP status for " + host);
                continue; // Skip this URL and proceed with next one
            }
        }
    }
}
