int copyAndAnalyzeFiles(char *source_dir, char *destination_dir) {
    DIR *directory;
    struct dirent *entry;

    if (!(directory = opendir(source_dir))) return 1;
    while ((entry = readdir(directory)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

        // Check if the file is a text file.
        char *extension = strrchr(entry->d_name, '.');
        if (extension == NULL || (strcasecmp(extension, ".txt") != 0 && 
                                   strcasecmp(extension, ".csv") != 0 && 
                                   strcasecmp(extension, ".json") != 0)) {
            continue;
        }

        // Create a thread to copy and parse the file.
        pthread_t thread;
        thread_data_t data = {source_dir, destination_dir};
        if (pthread_create(&thread, NULL, &copyFile, &data)) return 1;
    }

    // Wait for all threads to finish.
    while(1) {
        int count = 0;
        pthread_t thread = pthread_self();
        if (pthread_equal(thread, pthread_self())) ++count;
        if (!count) break;
    }

    // Find and print the largest integer from standard input.
    findLargestInteger();

    closedir(directory);
    return 0;
}
