['Creating a full implementation for such complex system in C is beyond the capacity of this platform as it involves many aspects which need separate discussion, detailed architecture design, various libraries, extensive testing, and a lot more work. However, I can provide a simplified example using POSIX threads (pthread) that meets your requirements in a high-level view:

```C
#include <pthread.h>
#include <semaphore.h>
#define MAX_TASKS 1024
#define MAX_THREADS 64

typedef struct Task {
    // Define your task here
} Task;

Task tasks[MAX_TASKS];
int taskCount = 0;
sem_t taskSemaphore;
pthread_mutex_t taskMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t taskCondition = PTHREAD_COND_INITIALIZER;
int workerCount = 0;
sem_t workerSemaphore;
pthread_mutex_t workerMutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t workerCondition = PTHREAD_COND_INITIALIZER;
int shutdownFlag = 0;

void *worker(void *arg) {
    while (1) {
        sem_wait(&taskSemaphore);  // wait for a task
        pthread_mutex_lock(&taskMutex);
        Task task = tasks[--taskCount];
        pthread_mutex_unlock(&taskMutex);
        if (shutdownFlag) {
            break;
        }
        // Perform the task here
    }
    sem_post(&workerSemaphore);  // notify that a worker is ready
    return NULL;
}

void submitTask(Task task) {
    pthread_mutex_lock(&taskMutex);
    tasks[taskCount++] = task;
    int newThreadFlag = 0;
    if (workerCount < MAX_THREADS && taskCount > workerCount + 1) {
        // Start a new thread to handle the task load
        ++workerCount;
        pthread_t thread;
        pthread_create(&thread, NULL, worker, NULL);
        newThreadFlag = 1;
    }
    pthread_mutex_unlock(&taskMutex);
    sem_post(&taskSemaphore);  // notify that a task is ready
    if (newThreadFlag) {
        sem_wait(&workerSemaphore);  // wait for the thread to start
    }
}

void shutdown() {
    shutdownFlag = 1;
    // Notify all tasks and workers
    for(int i = 0; i < taskCount; ++i) {
        sem_post(&taskSemaphore);
    }
    for (int i = 0; i < workerCount; ++i) {
        sem_post(&workerSemaphore);
    }
}
```

The above code does not include details such as error handling, integration with external services, task prioritization, resource management, performance optimization etc. This is just a starting point and needs to be extended according to your requirements.
