// Function to add an event to the queue safely
Event * add_event(int id, char * message, size_t limit, Event ** lastEvent) {
    if (message == NULL || limit == 0) return NULL; // Handle null inputs

    size_t len = strlen(message);
    if (len > limit - 1) len = limit - 1; // Ensure we don't exceed the limit minus newline

    Event * newEvent = malloc(sizeof(Event));
    if (newEvent == NULL) return NULL; // Check memory allocation

    newEvent->id = id;
    newEvent->serializedMessage = malloc(len + 2); // +1 for null terminator, +1 for newline
    if (newEvent->serializedMessage == NULL) {
        free(newEvent); // Cleanup on allocation failure
        return NULL; 
    }

    strncpy(newEvent->serializedMessage, message, len);
    newEvent->length = len + 1;

    // Add custom encoding scheme here, for example:
    newEvent->serializedMessage[len] = '\n'; 
    newEvent->serializedMessage[len+1] = '\0'; // Null terminate string

    pthread_mutex_lock(&lock); // Lock to ensure thread safety

    (*lastEvent)->next = newEvent; // Update the last event's next pointer
    *lastEvent = newEvent; // Update the last event

    pthread_mutex_unlock(&lock);

    return newEvent;
}
