#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char mac[6];  // Each MAC address is 48 bits = 6 bytes
    int ip;       // IP Address represented as an integer for simplicity
} NIC_config_t;

typedef struct {
    NIC_config_t *array;
    size_t used;
    size_t size;
} Array;

void initArray(Array *a, size_t initialSize) {
    a->array = (NIC_config_t *)malloc(initialSize * sizeof(NIC_config_t));
    a->used = 0;
    a->size = initialSize;
}

void insertArray(Array *a, NIC_config_t element) {
    // Check if the MAC address is already present
    for (int i=0; i<a->used; i++) {
        if (!memcmp(a->array[i].mac, element.mac, sizeof(element.mac))) return;
    }

    // Check if reallocation is needed
    if (a->used == a->size) {
        a->size *= 2;  // double the size
        a->array = (NIC_config_t *)realloc(a->array, a->size * sizeof(NIC_config_t));
    }

    // Add new element
    memcpy(&a->array[a->used], &element, sizeof(NIC_config_t));
    (a->used)++;
}
```
