    private ConcurrentQueue<string> transactionQueue = new ConcurrentQueue<string>(); // Queue to hold transactions
    private HttpClient client = new HttpClient(); // Client for calling API
    private Stopwatch stopWatch = new Stopwatch(); // Timer
    private CancellationTokenSource cancellationTokenSource = new CancellationTokenSource(); // Source for handling cancellation
    private FileLogger fileLogger;  // Logger to log anomalies and performance data

