        while (!transactionQueue.IsEmpty) 
        {
            if (stopWatch.ElapsedMilliseconds >= 500) // Checking if we need to process anomalies
            {
                stopWatch.Restart();
                ProcessAnomalies(client, transactionQueue); 
            }

            ThreadPool.QueueUserWorkItem(ProcessTransaction); // Process transactions concurrently
        }
    }

