    {
        using (var reader = new StreamReader(csvFilePath))
        {
            while (!reader.EndOfStream)
            {
                var line = await reader.ReadLineAsync(); // read the file asynchronously 
                transactionQueue.Enqueue(line); // Add transactions to queue
            }
        }
