extern int validateData(PHY_STATS_RECORD* record);  // A function to check validity of data
extern void logEvent(const char* event);  // Logging mechanism

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // Mutex for thread safety

PHY_STATS_RECORD* createArray(int size) {
    if (size <= 0) return NULL;

    pthread_mutex_lock(&lock);  // Lock the mutex to ensure atomicity
    PHY_STATS_RECORD* array = malloc(size * sizeof(PHY_STATS_RECORD));
    if (array == NULL) {
        logEvent("Memory allocation failed");
        pthread_mutex_unlock(&lock);  // Unlock before return to ensure atomicity
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        PHY_STATS_RECORD record = {i, 0};  // Initialize each struct with id and default data

        if (!validateData(&record)) {
            logEvent("Invalid data");
            free(array);
            pthread_mutex_unlock(&lock);  // Unlock before return to ensure atomicity
            return NULL;
        }

        memcpy(&array[i], &record, sizeof(PHY_STATS_RECORD));
    }

    externalModule();  // Call the data processing module

    logEvent("Array created successfully");

    pthread_mutex_unlock(&lock);  // Unlock mutex after all operations are completed
    return array;
}
```
This example uses heap allocation for efficiency in a high-concurrency scenario. It ensures atomicity by locking and unlocking the mutex around each operation to prevent race conditions when called from multiple threads simultaneously. It logs events for debugging purposes, includes validation checks to ensure data validity, and gracefully handles memory failures. Note that you should adapt this code according to your specific use case, especially if your `PHY_STATS_RECORD` structure is more complex or requires different behavior.
']

['Here is a simple C code example that meets your requirements. In this case, a HashMap is used to store configurations based on MAC address and IP address for rapid access during network data processing tasks. The program uses Pthreads for managing multiple threads safely without causing race conditions. A callback function is invoked when an item is added or removed.

```c
#include <stdio.h>
#include <pthread.h>
#include <string.h>
#include <stdlib.h>

typedef struct NIC_config {
    char mac[20];
    char* IPs; // Space separated IP addresses
    void* packet_stats; // Dynamically allocated buffer for packet statistics
} NIC_config_t;

typedef struct HashMapItem {
    NIC_config_t config;
    struct HashMapItem *next;
} HashMapItem_t;

typedef struct HashMap {
    pthread_mutex_t mutex;
    int size;
    HashMapItem_t **items;
} HashMap_t;

HashMap_t* create_hashmap(int size) {
    HashMap_t *hm = malloc(sizeof(HashMap_t));

    if (pthread_mutex_init(&hm->mutex, NULL) != 0) {
        printf("\n Mutex init failed\n");
        return NULL;
    }

    hm->size = size;
    hm->items = malloc(sizeof(HashMapItem_t*) * size);

    int i;
    for (i = 0; i < size; i++) {
        hm->items[i] = NULL;
    }
    return hm;
}

void destroy_hashmap(HashMap_t* hm) {
    pthread_mutex_destroy(&hm->mutex);

    int i;
    for (i = 0; i < hm->size; i++) {
        HashMapItem_t *item = hm->items[i];

        while(item != NULL) {
            HashMapItem_t *next = item->next;

            free(item->config.IPs);
            free(item->config.packet_stats);
            free(item);

            item = next;
        }
    }

    free(hm->items);
    free(hm);
}

unsigned long hash(char *str, int size) {
    unsigned long hash = 5381;
    int c;

    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */

    return hash % size;
}

void add_nic(HashMap_t* hm, NIC_config_t config, void (*callback)(NIC_config_t)) {
    unsigned long index = hash(config.mac, hm->size);

    pthread_mutex_lock(&hm->mutex);

    HashMapItem_t *item = malloc(sizeof(HashMapItem_t));
    item->config = config;
    item->next = hm->items[index];
    hm->items[index] = item;

    pthread_mutex_unlock(&hm->mutex);

    callback(config);
}

void remove_nic(HashMap_t* hm, char *mac) {
    unsigned long index = hash(mac, hm->size);

    pthread_mutex_lock(&hm->mutex);

    HashMapItem_t **link = &hm->items[index];

    while (*link != NULL) {
        if (strcmp((*link)->config.mac, mac) == 0) {
            HashMapItem_t *next = (*link)->next;

            free((*link)->config.IPs);
            free((*link)->config.packet_stats);
            free(*link);

            *link = next;
            break;
        }

        link = &(*link)->next;
    }

    pthread_mutex_unlock(&hm->mutex);
}

NIC_config_t* get_nic(HashMap_t* hm, char *key) {
    unsigned long index = hash(key, hm->size);

    pthread_mutex_lock(&hm->mutex);

    HashMapItem_t *item = hm->items[index];

    while (item != NULL) {
        if (strcmp(item->config.mac, key) == 0 || strstr(item->config.IPs, key)) {
            pthread_mutex_unlock(&hm->mutex);

            return &item->config;
        }

        item = item->next;
    }

    pthread_mutex_unlock(&hm->mutex);

    return NULL;
}
``` 
This is a very basic implementation and does not consider many aspects such as memory fragmentation, buffer overflows, error handling, etc. It's just for demonstration purposes of how you can handle multi-threaded access, callbacks, hash maps and memory management in C. The use of the POSIX threads library (pthreads) guarantees thread safety but may increase overhead depending on your specific usage patterns.
']

