    SIB_BUFFER sib_buffer;
} LTE_RRC_UE_CONTEXT_T;
```
We can start with managing dynamic arrays of this context:
```c
typedef struct {
    size_t capacity;
    size_t size;
    LTE_RRC_UE_CONTEXT_T *contexts;
} ContextArray;

void initContextArray(ContextArray *array, size_t initialCapacity) {
    array->capacity = initialCapacity;
    array->size = 0;
    array->contexts = (LTE_RRC_UE_CONTEXT_T *) malloc(initialCapacity * sizeof(LTE_RRC_UE_CONTEXT_T));
}

void addContextToArray(ContextArray *array, LTE_RRC_UE_CONTEXT_T context) {
    if (array->size == array->capacity) {
        // Array is full; resize it
        array->capacity *= 2;
        array->contexts = (LTE_RRC_UE_CONTEXT_T *) realloc(array->contexts, array->capacity * sizeof(LTE_RRC_UE_CONTEXT_T));
    }
    array->contexts[array->size++] = context; // Add the new context to the end of the array
}
```
For managing concurrent access and potential race conditions, a lock-based approach could be used:
```c
#include <pthread.h>

typedef struct {
    pthread_mutex_t mutex;
    ContextArray array;
} LockedContextArray;

void initLockedContextArray(LockedContextArray *array, size_t initialCapacity) {
    pthread_mutex_init(&array->mutex, NULL); // Initialize the lock
    initContextArray(&array->array, initialCapacity);
}

void addContextToLockedArray(LockedContextArray *array, LTE_RRC_UE_CONTEXT_T context) {
    pthread_mutex_lock(&array->mutex); // Lock the array
    addContextToArray(&array->array, context);
    pthread_mutex_unlock(&array->mutex); // Unlock the array
}
```
For the purge mechanism, we could use a simple approach of marking contexts for deletion and then compacting the array:
```c
typedef struct {
    size_t capacity;
    size_t size;
    LTE_RRC_UE_CONTEXT_T *contexts;
    char *flags; // Flags indicating which contexts are valid
} ContextArrayWithFlags;

void markContextForDeletion(ContextArrayWithFlags *array, size_t index) {
    array->flags[index] = 0; // Mark the context for deletion
}

void compactContextArray(ContextArrayWithFlags *array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (!array->flags[i]) { // This context is marked for deletion
            --array->size; // Decrease the size of the array
            // Move the last valid context to fill the gap
            while (i < array->size && !array->flags[array->size]) --array->size;
            if (i < array->size) {
                array->contexts[i] = array->contexts[array->size];
                array->flags[i] = array->flags[array->size];
            }
        }
    }
}
```
This approach ensures optimal resource utilization by avoiding the need for frequent reallocations and by only moving valid contexts to fill gaps when a context is deleted.

The logging strategy could be simple, just printing out the metrics at regular intervals:
```c
