```c
#include <stdlib.h>
#include <string.h>

char* append_slash_if_within_limit(const char* input, size_t size_limit) {
    // check if input is larger than limit
    if (strlen(input) > size_limit) {
        return NULL;
    }

    // allocate memory for new string and copy input to it
    char *output = malloc((size_limit + 2) * sizeof(char));
    strcpy(output, input);

    // append slash at the end of output string
    size_t len = strlen(output);
    if (output[len - 1] != '/') {
        output[len] = '/';
        output[len + 1] = '\0';
    }

    return output;
}
