// Define a cache node structure to hold the cache entries.
typedef struct CacheNode {
    NFAPI_CRC_INDICATION_PDU_T* item;
    struct CacheNode *next;
} CacheNode;

// Define a cache structure that contains the head of the cache and a mutex for thread-safety.
typedef struct {
    pthread_mutex_t lock;
    CacheNode *head;
} Cache;

Cache cache[VARIANT2 + 1]; // Create a separate cache for each variant.

// Function to allocate memory and initialize the structure.
NFAPI_CRC_INDICATION_PDU_T* createStructure(int RNTI, CRC_VARIANT variant) {
    NFAPI_CRC_INDICATION_PDU_T *newItem = NULL;

    // Attempt to allocate memory.
    newItem = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newItem == NULL) {
        return NULL;
    }

    // Initialize the structure with valid data.
    newItem->RX_UE_Info.RNTI = RNTI;
    srand(time(NULL));
    newItem->CRC_Info.CRCFLAG = rand();
    newItem->CRC_Info.variant = variant;

    return newItem;
}

// Function to add an item to the cache.
void addToCache(NFAPI_CRC_INDICATION_PDU_T *item, CRC_VARIANT variant) {
    pthread_mutex_lock(&cache[variant].lock);

    CacheNode *newNode = malloc(sizeof(CacheNode));
    if (newNode == NULL) {
        // Handle memory allocation failure...
        return;
    }

    newNode->item = item;
    newNode->next = cache[variant].head;

    cache[variant].head = newNode;

    pthread_mutex_unlock(&cache[variant].lock);
}

// Function to retrieve an item from the cache.
NFAPI_CRC_INDICATION_PDU_T* getFromCache(CRC_VARIANT variant) {
    NFAPI_CRC_INDICATION_PDU_T *item = NULL;

    pthread_mutex_lock(&cache[variant].lock);

    if (cache[variant].head != NULL) {
        CacheNode *nodeToRemove = cache[variant].head;
        item = nodeToRemove->item;

        // Remove the retrieved item from the cache.
        cache[variant].head = nodeToRemove->next;
        free(nodeToRemove);
    }

    pthread_mutex_unlock(&cache[variant].lock);

    return item;
}
```
