void checkSystemResources() {
    struct rusage usage;
    getrusage(RUSAGE_SELF, &usage);

    if (usage.ru_maxrss > 0.9 * sysconf(_SC_PHYS_PAGES) * sysconf(_SC_PAGE_SIZE)) {
        printf("Warning: System resources are critically low.\n");
    }
}

JNIEXPORT jstring JNICALL 
Java_com_example_md5_getMD5 (JNIEnv *env, jobject obj, jstring input) {
    const char* str = (*env)->GetStringUTFChars(env, input, NULL);

    unsigned char digest[16];
    MD5((unsigned char*)str, strlen(str), (unsigned char*)&digest);    

    char mdString[33];

    for(int i = 0; i < 16; i++)
         sprintf(&mdString[i*2], "%02x", (unsigned int)digest[i]);

    jstring result = (*env)->NewStringUTF(env, mdString);

    return result;
}

char* processLargeFile(char *inputFileName, char *outputFileName, char *query, int sortFlag, size_t memLimit) {
    FILE *infile  = fopen (inputFileName, "rb");
    FILE *outfile = fopen (outputFileName, "wb");

    if(!infile || !outfile) { 
        printf("Error opening files.\n"); 
        return NULL;
    }

    struct rusage usageBefore, usageAfter;
    getrusage(RUSAGE_SELF, &usageBefore);

    size_t bytesRead = 0;
    char *buffer = malloc(memLimit * 1024); // Dynamically allocating memory only for necessary operations.

    if (!buffer) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    clock_t start, end;

    while(!feof(infile)) {
        size_t bytesToRead = fread(buffer, 1, memLimit * 1024, infile); // Reading data in chunks.

        checkSystemResources();

        if (sortFlag) {
            qsort(buffer, bytesToRead / sizeof(char), sizeof(char), comparator); // If sorting is enabled then sorting the buffer.
        }

        fwrite(buffer, 1, bytesToRead, outfile); // Writing the sorted data back into file.
        bytesRead += bytesToRead;
    }

    getrusage(RUSAGE_SELF, &usageAfter);

    free(buffer);
    fclose (infile);
    fclose (outfile);

    start = usageBefore.ru_utime.tv_sec; // Time before processing.
    end = usageAfter.ru_utime.tv_sec; // Time after processing.

    printf("Processing took %ld seconds.\n", (end - start));

