['```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

// AES-256-CBC cipher secure initialization function with PBKDF2
EVP_CIPHER_CTX *aes_init(unsigned char* key, unsigned char* iv) {
    EVP_CIPHER_CTX *ctx;
    if(!(ctx = EVP_CIPHER_CTX_new())) return NULL;
    if(1 != EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }
    EVP_CIPHER_CTX_set_padding(ctx, 1);
    return ctx;
}

// AES-256-CBC cipher secure cleanup function
void aes_cleanup(EVP_CIPHER_CTX *ctx) {
    if(ctx != NULL) EVP_CIPHER_CTX_free(ctx);
}

int BinaryFileParser(const char* input, const char* output, const char* password, unsigned int iterations) {
    FILE* fin = fopen(input, "rb");
    if(!fin) return -1;  // error opening input file

    FILE* fout = fopen(output, "wb");
    if(!fout) {
        fclose(fin);
        return -2;  // error opening output file
    }

    unsigned char key[EVP_MAX_KEY_LENGTH];
    unsigned char iv[EVP_MAX_IV_LENGTH];
    PKCS5_PBKDF2_HMAC(password, strlen(password), NULL, 0, iterations, EVP_sha256(), EVP_MAX_KEY_LENGTH, key, EVP_MAX_IV_LENGTH, iv);

    // Initialize cipher with AES-256-CBC and the derived key/iv
    EVP_CIPHER_CTX *ctx = aes_init(key, iv);
    if(!ctx) {
        fclose(fin);
        fclose(fout);
        return -3;  // error initializing cipher
    }

    unsigned char buffer[1024];  // read and write in chunks of 1024 bytes
    int nread, outlen = 0;
    while((nread = fread(buffer, 1, sizeof(buffer), fin))) {
        if(!EVP_EncryptUpdate(ctx, buffer, &outlen, buffer, nread)) {
            aes_cleanup(ctx);
            fclose(fin);
            fclose(fout);
            return -4;  // error encrypting update
        }
        if(!fwrite(buffer, outlen, 1, fout)) {
            aes_cleanup(ctx);
            fclose(fin);
            fclose(fout);
            return -5;  // error writing to output file
        }
    }

    if(!EVP_EncryptFinal_ex(ctx, buffer, &outlen)) {
        aes_cleanup(ctx);
        fclose(fin);
        fclose(fout);
        return -6;  // error finalizing encryption
    }

    if(!fwrite(buffer, outlen, 1, fout)) {
        aes_cleanup(ctx);
        fclose(fin);
        fclose(fout);
        return -7;  // error writing to output file
    }

    aes_cleanup(ctx);
    fclose(fin);
    fclose(fout);
    OPENSSL_cleanse(key, EVP_MAX_KEY_LENGTH);
    OPENSSL_cleanse(iv, EVP_MAX_IV_LENGTH);

    return 0;  // success
}
```
']

