  atomic_uint_fast32_t count;
  _Atomic(NFAPI_CRC_INDICATION_PDU_T*) head;
  pthread_mutex_t lock;
} Cache;

Cache cache[NUMBER_OF_TAGS]; // replace NUMBER_OF_TAGS with actual number of variants

void init_cache(Cache* c) {
  atomic_init(&c->count, 0);
  c->head = NULL;
  pthread_mutex_init(&c->lock, NULL);
