NFAPI_CRC_INDICATION_PDU_T* allocate(Cache* c) {
  NFAPI_CRC_INDICATION_PDU_T* item = atomic_load(&c->head);

  if (item != NULL) {
    atomic_store(&c->head, item->next);
    atomic_fetch_sub(&c->count, 1);
    return item;
  } else {
    // Handle allocation failures
    return malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  }
}

void deallocate(Cache* c, NFAPI_CRC_INDICATION_PDU_T* item) {
  pthread_mutex_lock(&c->lock); // to be replaced with lock-free mechanism if possible

  atomic_store(&item->next, c->head);
  atomic_store(&c->head, item);
  atomic_fetch_add(&c->count, 1);

  pthread_mutex_unlock(&c->lock);
}

