["```C
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    char* ip_address;
    char* buffer;
    size_t buffer_size;
    time_t timestamp;
} TCPConnection;

// Define the array of connections and associated lock
TCPConnection** connections;
int numConnections = 0;
pthread_mutex_t connectionLock = PTHREAD_MUTEX_INITIALIZER;

void addOrUpdateConnection(char* ip, char* buffer, size_t bufferSize) {
    pthread_mutex_lock(&connectionLock);
    for (int i = 0; i < numConnections; ++i) {
        if (!strcmp(connections[i]->ip_address, ip)) {
            // Update existing connection
            connections[i]->buffer = realloc(connections[i]->buffer, bufferSize);
            strncpy(connections[i]->buffer, buffer, bufferSize);
            connections[i]->buffer_size = bufferSize;
            goto updateTimestampAndUnlock;
        }
    }
    // Add new connection
    ++numConnections;
    connections = realloc(connections, numConnections * sizeof(TCPConnection*));
    connections[numConnections - 1] = malloc(sizeof(TCPConnection));
    connections[numConnections - 1]->ip_address = strdup(ip);
    connections[numConnections - 1]->buffer = malloc(bufferSize);
    strncpy(connections[numConnections - 1]->buffer, buffer, bufferSize);
    connections[numConnections - 1]->buffer_size = bufferSize;

updateTimestampAndUnlock:
    // Update timestamp and unlock
    connections[i]->timestamp = time(NULL);
    pthread_mutex_unlock(&connectionLock);
}

void purgeInactiveConnections() {
    pthread_mutex_lock(&connectionLock);
    for (int i = 0; i < numConnections; ++i) {
        if ((time(NULL) - connections[i]->timestamp) > INACTIVITY_THRESHOLD) {
            // Free memory and remove connection
            free(connections[i]->ip_address);
            free(connections[i]->buffer);
            free(connections[i]);
            for (int j = i; j < numConnections - 1; ++j) {
                connections[j] = connections[j + 1];
            }
            --numConnections;
        }
    }
    // Reallocate array to match actual number of connections and unlock
    connections = realloc(connections, numConnections * sizeof(TCPConnection*));
    pthread_mutex_unlock(&connectionLock);
}
``` 

