// Helper function to convert hostname to IP
int resolve_host(const char* hostname, u_char* ip, int timeout, size_t resp_size) {
    unsigned char response[resp_size];

    // Resolve DNS query
    res_init();
    _res.nscount = MAXNS;  // Set nameserver count
    _res.options |= RES_USEVC|RES_IGNTC; // Use TCP only and ignore truncation

    int retval = res_query(hostname, C_INET, T_A, response, resp_size);

    if (retval < 0) {
        fprintf(stderr, "Error resolving host: %s\n", hstrerror(h_errno));
        return -1;  // Return error code on failure
    } else {
        struct in_addr addr;
        memcpy(&addr.s_addr, response+retval, sizeof(struct in_addr));

        // Convert address to u_char array
        for (int i = 0; i < sizeof(u_char); ++i) {
            ip[i] = ((unsigned char*)&addr)[i];
        }
    }
    return 0;  // Return success code on success
}
