class UEContextManager {
public:
    UEContextManager(ExternalDependency& dep) : dependency_(dep), rng_(std::random_device{}()) {}
    ~UEContextManager() = default;

    void addContext(const std::string& mac, int c_rnti);
    bool updateContext(int old_c_rnti, int new_c_rnti);
    void purgeUnusedContexts();

private:
    ExternalDependency& dependency_;
    std::vector<LTE_RRC_UE_CONTEXT_T> contexts_;
    mutable std::mutex mtx_; // for thread safety
    mutable std::mt19937 rng_; // random number generator
};

void UEContextManager::addContext(const std::string& mac, int c_rnti) {
    std::lock_guard<std::mutex> lock(mtx_);

    contexts_.push_back({mac, c_rnti});
}

bool UEContextManager::updateContext(int old_c_rnti, int new_c_rnti) {
    std::lock_guard<std::mutex> lock(mtx_);

    auto it = std::find_if(contexts_.begin(), contexts_.end(), 
                           [&old_c_rnti](const LTE_RRC_UE_CONTEXT_T& ctx) { return ctx.c_rnti == old_c_rnti; });

    if (it != contexts_.end()) {
        it->c_rnti = new_c_rnti;
        return true;
    }

    return false;
}

void UEContextManager::purgeUnusedContexts() {
    std::lock_guard<std::mutex> lock(mtx_);

    contexts_.erase(std::remove_if(contexts_.begin(), contexts_.end(), 
                                  [this](const LTE_RRC_UE_CONTEXT_T& ctx) {
                                      // condition for purging unused context
                                      return rng_() % 10 == 0; // example condition
                                  }),
                    contexts_.end());
}
```
