    public List<String> batchProcess(List<Pokemon> pokemons) {
        List<String> reports = new ArrayList<>();

        for (int i = 0; i < pokemons.size(); i += 1000) {
            processBatch(pokemons.subList(i, Math.min(i + 1000, pokemons.size())));
        }

        return reports;
