        List<Thread> threads = new ArrayList<>();

        for (Pokemon p : batch) {
            Thread thread = new Thread(() -> {
                try {
                    String report = generateReport(p);

                    // Ensure thread safety while adding to the list
                    synchronized (reports) {
                        reports.add(report);
                    }
                } catch (Exception e) {
                    logError("Failed to process pokemon " + p.getId(), e);
                }
            });

            thread.start();
            threads.add(thread);
        }

        // Wait for all threads to finish
        for (Thread t : threads) {
            try {
