// Function to perform transformation based on the rule provided.
std::string applyTransform(int num, const std::string& rule) {
    if (rule == "square") return std::to_string(num * num);
    else if (rule == "double") return std::to_string(num * 2);
    // Add more rules as needed.

    return "";
}

// Function to insert number and transform forward list.
void transformAndInsert(std::forward_list<int>& flist, int num1, int num2, const std::string& rule) {
    auto pos = std::find(flist.begin(), flist.end(), num1);

    if (pos != flist.end()) {
        flist.insert_after(pos, num2);
    } else {
        flist.push_back(num2);
    }

    // Transform each element in the list using given rule.
    for (auto& num : flist) {
        num = std::stoi(applyTransform(num, rule));
    }

    // Sorting the list after transformation.
    flist.sort();
}

// Function to read and write file with transformation rules.
void readAndWriteFile(const char* inputPath, const char* outputPath, const std::string& rule) {
    std::ifstream inFile;
    std::ofstream outFile;

    // Open the files.
    inFile.open(inputPath);
    if (!inFile) {
        std::cerr << "Could not open input file." << std::endl;
        exit(1);  // Exit program if we couldn't open input file.
    }

    outFile.open(outputPath);
    if (!outFile) {
        inFile.close();
        std::cerr << "Could not open output file." << std::endl;
        exit(1);  // Exit program if we couldn't open output file.
    }

    // Read input, apply transformation and write to the output file.
    int num;
    while (inFile >> num) {
        outFile << applyTransform(num, rule) << ' ';
    }

    // Close the files.
    inFile.close();
    outFile.close();
}
