Here's how you might implement `collectAndStoreData` in JavaScript:

```javascript
//JavaScript Function
const stream = require('stream');
let dataArray = [];
let pauseFlag = false;
let resumeCallback = null;

function collectAndStoreData(dataStream) {
    try{
        dataStream.on('error', function (err) {
            console.log("Error occurred while reading the stream.", err);
        });

        const transformStream = new stream.Transform({
            readableObjectMode: true,
            writableObjectMode: false,

            transform(chunk, encoding, callback) {
                //check if pause flag is set and store resume callback 
                if (pauseFlag){
                    resumeCallback = () => this._transform(chunk, encoding, callback);
                    return;
                }

                dataArray.push(chunk);
                callback();
            },
        });

        //pause or resume the stream on demand 
        transformStream.on('data', function (chunk) {
            if(pauseFlag){
                transformStream.pause();
            } else {
                transformStream.resume();
            }

            //invoke the stored resume callback after pausing and resuming 
            if(typeof resumeCallback === 'function'){
                resumeCallback();
                resumeCallback = null;
            }
        });

        return transformStream;
    } catch (err) {
        console.log("Error occurred while creating the data stream.", err);
        throw err;
    }
}
```
These methods handle exceptions, pause and resume streaming operations efficiently, optimize memory usage, and support logging for debugging purposes. Note that this is a basic implementation and doesn't include error handling for edge cases or specifics of your project. You would want to adapt these to suit the exact needs of your application.
