```javascript
const os = require('os');
const blueslip = require('blueslip'); // hypothetical mocking library 

async function runTests(moduleName, testCases, config, environment) {
    let module;

    try {
        console.log(`Loading module: ${moduleName}`);
        module = require(moduleName);
    } catch (error) {
        console.error(`Failed to load module: ${moduleName}`, error);
        return;
    }

    const maxParallelTests = Math.min(config.maxParallelTests || os.cpus().length, environment.cpuCores || 1);

    console.log(`Testing module: ${moduleName} with ${testCases.length} test cases in parallel (limit: ${maxParallelTests})`);

    const startTime = Date.now();
    let passed = 0;
    let failed = 0;
    let previousRunStats = {}; // hypothetical previous run statistics data structure

    while(testCases.length) {
        let currentBatchSize = Math.min(maxParallelTests, testCases.length);

        const batchResults = await Promise.all(testCases.splice(0, currentBatchSize).map(async (testCase) => {
            blueslip.reset(); // reset module between each test using blueslip mocking library

            try {
                console.log(`Running test: ${testCase.name}`);

                await testCase(config, environment, previousRunStats[testCase.name]); // adaptive testing strategy

                console.log(`Test passed: ${testCase.name}`);
                return 'pass';
            } catch (error) {
                console.error(`Test failed: ${testCase.name}`, error);
                return 'fail';
            }
        }));

        const batchPassed = batchResults.filter(result => result === 'pass').length;
        passed += batchPassed;
        failed += (currentBatchSize - batchPassed);
    }

    console.log(`Testing complete: ${moduleName} [${passed}/${passed + failed}] tests passed, in ${Date.now() - startTime}ms`);
    return {
        module: moduleName,
        passed: passed,
        failed: failed,
        resourceUsage: { // hypothetical method to retrieve system resource usage metrics 
            cpu: os.loadavg(),
            memory: process.memoryUsage()
        }
    };
}
```
In this code example, the function first tries to load the module using the `require` function and handles any potential errors by logging an error message to the console and returning from the function early. It then calculates the maximum number of tests that can be run in parallel based on the configuration settings or system constraints. The function then sets up a while loop to run all the test cases, dynamically adjusting the number of parallel tests runners between each batch depending on available resources and the number of remaining tests.
