const oldTestamentBooks = require('./oldTestamentBooks'); // Assume this file contains names of books in Old Testament
const newTestamentBooks = require('./newTestamentBooks'); // Assume this file contains names of books in New Testament

let cache = {}; // Create a cache for book summaries and counts

