function countBooks(text) {
    const books = [...oldTestamentBooks, ...newTestamentBooks]; // Combine both testaments books into one array

    let counts = {}; 
    let words = text.toLowerCase().match(/[a-zA-Z]+/g); // Match only words in the input text

    for (let word of words) {
        if(books.includes(word)) {
            if(!counts[word]) counts[word] = 0; 
            ++counts[word]; 
        }
    }

    let result = {};

    // Fetch book summaries and store in the cache
    for (let [book, count] of Object.entries(counts)) {
         if (!cache[book]) {
            try {
                cache[book] = await fetchSummary(book); // Assume this function fetches a summary from an API
            } catch(e) {
                console.error('Error when trying to fetch book summary', e);
                cache[book] = 'No summary available'; // Default fallback value in case of error
            }
         }

         result[book] = { count, summary: cache[book] }; 
    }

    return result; 
}
```
The function `countBooks` counts the occurrence of books from both testaments in a given text. It then fetches summaries for each book and stores them in the cache. If an API call fails, it provides a default fallback value ('No summary available'). The cache ensures that we don't make redundant calls to the API, improving performance by avoiding unnecessary network requests.
