    void* SIBs;  // Pointer to dynamically allocated buffer
} LTE_RRC_UE_CONTEXT_T;

LTE_RRC_UE_CONTEXT_T** contexts = NULL;  // Array of pointers to contexts
int numContexts = 0;  // Current number of contexts

void addContext(LTE_RRC_UE_CONTEXT_T* context) {
    numContexts++;
    contexts = realloc(contexts, sizeof(*contexts)*numContexts);
    contexts[numContexts-1] = context;
}

void deleteContext(int C_RNTI) {
    for (int i = 0; i < numContexts; ++i) {
        if (contexts[i]->C_RNTI == C_RNTI) {
            free(contexts[i]->SIBs);  // Free allocated SIBs memory
            free(contexts[i]);  // Free context itself

            contexts[i] = contexts[numContexts-1];  // Replace with last element
            numContexts--;

            contexts = realloc(contexts, sizeof(*contexts)*numContexts);  // Resize array
            break;
        }
    }
}

