from redis import Redis
import json

class DataFetcher:
    def __init__(self, config):
        self.config = config
        self.redis = Redis(host='localhost', port=6379) # assuming you have a redis server running locally
        self.engine = create_engine('postgresql://{}:{}@localhost/data'.format(os.getenv('DB_USER'), os.getenv('DB_PASSWORD')))  # assuming PostgreSQL database

    def fetch_from_api(self, source):
        url = self.config[source]['url']
        response = self.redis.get(url)

        if response:
            return json.loads(response)

        try:
            response = requests.get(url)
            response.raise_for_status()
            data = response.json()
            self.redis.setex(url, 60 * 5, json.dumps(data)) # caching for 5 minutes
        except (requests.exceptions.HTTPError, requests.exceptions.ConnectionError) as e:
            print('There was an issue:', str(e))
            data = {} 

        return data

    def process_data(self, data):
        # implement your own logic here to process the fetched data
        pass

    def store_in_db(self, data):
        with self.engine.connect() as connection:
            for item in data:
                # assuming you have a "data" table and each item is a dictionary
                connection.execute("INSERT INTO data VALUES (%s)" % ', '.join([f'"{value}"' for value in item.values()]))

    def fetch_and_store(self, source):
        data = self.fetch_from_api(source)
        processed_data = self.process_data(data)
        self.store_in_db(processed_data)

if __name__ == '__main__':
    config = {}
    for entry_point in iter_entry_points('my_package.datasources'):  # assuming you have an entry point group defined in your setup.py
        source, url = entry_point.load()()
        config[source] = {'url': url}

    fetcher = DataFetcher(config)

    for source in config.keys():
        fetcher.fetch_and_store(source)
```
In this example, we are assuming that the packages defining the data sources provide a function to load them which returns a tuple `('name of the data source', 'url of the API')`. You'll have to adjust based on your actual setup and requirements.
