```python
import time
from threading import Lock
from queue import Queue

class ConfigUpdateError(Exception):
    pass

class CacheInvalidationManager:

    def __init__(self, max_attempts=3):
        self.cache = {}  # assume this is your distributed cache
        self.max_attempts = max_attempts
        self.lock = Lock()
        self.notification_queue = Queue()

    def update_config(self, service_instance, critical_settings):
        attempts = 0
        while attempts < self.max_attempts:
            try:
                with self.lock:  # ensure thread-safe access to cache
                    for setting in critical_settings:
                        if setting not in self.cache[service_instance]:
                            raise ConfigUpdateError(f'Setting {setting} does not exist')
                        del self.cache[service_instance][setting]

                        # notify dependent services
                        self.notification_queue.put((service_instance, setting))
                    return {'success': True, 'message': 'Configuration updated successfully'}
            except Exception as e:
                attempts += 1
                if attempts == self.max_attempts:  # retry limit reached
                    return {'success': False, 'error': str(e)}  

                time.sleep((2 ** attempts) * 0.1 * (random.random() + 0.5))  # exponential backoff with some jitter

    def notify_dependents(self):
        while True:
            service_instance, setting = self.notification_queue.get()

            try:
                # assuming dependent services are available in another distributed cache and accessible via a method
                dependent_services = self.cache['dependent_service_registry'][service_instance]

                for service in dependent_services:
                    # notify each service about the change using an appropriate mechanism like HTTP requests, message queues etc.
                    notify(service, {'service': service_instance, 'setting': setting})
            except Exception as e:
                print(f'Failed to notify {service}: {e}')  # retry on failure is handled by the consumer of this method
```
