['Below is a basic example using Node.js, Express.js and MongoDB. Note that there are many ways to implement this depending on your exact requirements, DBMS you're using, your data structure etc. This is just one of many possible solutions.

```javascript
const express = require('express');
const router = express.Router();
const cacheManager = require('cache-manager');
const mongoose = require('mongoose');

// Assuming you have a User model and Post model set up with Mongoose
const User = mongoose.model('User'); 
const Post = mongoose.model('Post');

// Setup in-memory cache to store frequently accessed user and post data
let memoryCache = cacheManager.caching({store: 'memory', max: 100, ttl: 60/*seconds*/});

router.get('/users/role/:role/posts', async (req, res) => {
    const role = req.params.role;
    let page = parseInt(req.query.page);
    if(!page || page < 1) page = 1;

    // Check if the data is already in cache
    const cachedData = await memoryCache.get(`${role}_${page}`);
    if (cachedData){ 
        return res.json(cachedData); 
    }

    let limit = 10; // Assuming a page size of 10, you can change this according to your needs
    try {
        const users = await User.find({ role: role })
            .skip((page - 1) * limit)
            .limit(limit);

        let data = [];
        for (let user of users){
            const posts = await Post.find({ author: user._id });
            data.push({ user, posts});
        }

        // Store the fetched data in cache and set a time-to-live (TTL) value
        memoryCache.set(`${role}_${page}`, data);

        res.json(data);
    } catch (error){
        console.log(error);
        res.status(500).send("An error occurred while retrieving users and their posts.");
    }
});

module.exports = router;
``` 

This assumes that you have User and Post models in Mongoose with the fields "role" for Users and "author" for Posts. It also uses `cache-manager` library to implement caching. The time-to-live (TTL) value can be adjusted based on your need. 

