#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <string.h>

typedef struct logEntry {
    time_t timestamp;
    unsigned long sequenceNumber;
    float weight;
} LogEntry;

typedef struct metrics {
    double maxWeightedSum;
    unsigned long transactionID;
} Metrics;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
Metrics mtxs;

void processLogFile(char *fileName) {
    FILE* file = fopen(fileName, "r");
    if (file == NULL) {
        printf("Failed to open log file.\n");
        return;
    }

    LogEntry entry;
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        pthread_mutex_lock(&lock);

        if (sscanf(buffer, "%ld %lu %f", &entry.timestamp, &entry.sequenceNumber, &entry.weight) != 3) {
            printf("Invalid entry format, skipping.\n");
            continue;
        }

        if (difftime(time(NULL), entry.timestamp) > 3) {
            printf("Entry is older than 3 seconds, skipping.\n");
            continue;
        }

        double weightedSum = entry.weight * entry.sequenceNumber;
        if (weightedSum > mtxs.maxWeightedSum) {
            mtxs.transactionID = entry.sequenceNumber;
            mtxs.maxWeightedSum = weightedSum;
        }

        pthread_mutex_unlock(&lock);
    }

    fclose(file);
}
```

This function reads the log file line by line, parsing each entry into a LogEntry struct. It then computes the weighted sum of the transaction and compares it to the current maximum weighted sum. If this is greater, it updates the metrics with the new max weighted sum and corresponding transaction ID. The function also handles entries that are older than 3 seconds or have invalid formats by skipping them.
']

