#define MAX_FIELDS 1024
#define FIELD_LEN 64
#define LINE_LEN (MAX_FIELDS * FIELD_LEN)
#define FILENAME_LEN 256

typedef struct {
    double values[MAX_FIELDS];
    int numFields;
} Entry;

void processFile(char* inFilename, char* outFilename, double (*filter)(Entry)) {
    clock_t start = clock();
    FILE *inFile  = fopen(inFilename, "r");
    FILE *outFile = fopen(outFilename, "w+");

    if (inFile == NULL || outFile == NULL) {
        printf("Unable to open file!\n");
        exit(1); 
    }

    char line[LINE_LEN];
    while (fgets(line, sizeof(line), inFile)) {
        Entry* entry = malloc(sizeof(Entry));
        entry->numFields = 0;

        char *token = strtok(line, " ");
        while (token != NULL && entry->numFields < MAX_FIELDS) {
            if (sscanf(token, "%lf", &entry->values[entry->numFields]) == 1) {
                entry->numFields++;
            }
            token = strtok(NULL, " ");
        }

        double avg = 0.0;
        if (entry->numFields > 2) {
            for (int i=entry->numFields-3; i<entry->numFields; ++i) {
                avg += entry->values[i];
            }
            avg /= 3.0;
        } else if (entry->numFields > 0) {
            for (int i=0; i<entry->numFields; ++i) {
                avg += entry->values[i];
            }
            avg /= entry->numFields;
        }

        if ((*filter)(*entry)) {
            fprintf(outFile, "%s %.2f\n", line, avg);
        } else {
            printf("Skipped: %s", line);
        }

        free(entry);
    }

    clock_t end = clock();
    double timeSpent = (double)(end - start) / CLOCKS_PER_SEC;
    printf("Processing took %f seconds\n", timeSpent);

    fclose(inFile);
    fclose(outFile);
}

