['Here's an example code snippet in C using jansson library for JSON processing:

```c
#include <jansson.h>
#include <time.h>
#include <stdbool.h>
#include <pthread.h>
#include <regex.h>

typedef struct {
    pthread_mutex_t lock;
    regex_t pattern;
} ValidatorConfig;

static const int GRACE_PERIOD = 300; // 5 minutes in seconds
ValidatorConfig config = {{PTHREAD_MUTEX_INITIALIZER},{.re_nsub=1}};

bool validate(const char *json, time_t gracePeriod) {
    json_error_t error;
    json_t *root = json_loads(json, 0, &error);
    if(!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return false;
    }

    pthread_mutex_lock(&config.lock);

    json_t *accessToken = json_object_get(root, "access_token");
    if(!json_is_string(accessToken) || !strlen(json_string_value(accessToken))) {
        fprintf(stderr, "Invalid access_token\n");
        goto cleanup;
    }

    json_t *expiresIn = json_object_get(root, "expires_in");
    if(!json_is_integer(expiresIn) || json_integer_value(expiresIn) <= 0) {
        fprintf(stderr, "Invalid expires_in\n");
        goto cleanup;
    }

    time_t expiryTime = time(NULL) + gracePeriod + (int)json_integer_value(expiresIn);
    if(time(NULL) > expiryTime) {
        fprintf(stderr, "Token has already expired\n");
        goto cleanup;
    }

    json_t *tokenType = json_object_get(root, "token_type");
    if(!json_is_string(tokenType) || strcmp(json_string_value(tokenType), "Bearer")) {
        fprintf(stderr, "Invalid token_type\n");
        goto cleanup;
    }

    json_t *refreshToken = json_object_get(root, "refresh_token");
    if(json_is_string(refreshToken)) {
        const char *value = json_string_value(refreshToken);
        int status = regexec(&config.pattern, value, 0, NULL, 0);
        if (status != 0) {
            fprintf(stderr, "Invalid refresh_token\n");
            goto cleanup;
        }
    } else if(!json_is_null(refreshToken)) {
        fprintf(stderr, "Invalid refresh_token\n");
        goto cleanup;
    }

    pthread_mutex_unlock(&config.lock);
    json_decref(root);
    return true;

cleanup:
    pthread_mutex_unlock(&config.lock);
    json_decref(root);
    return false;
}
```

This function assumes that you initialize the `pattern` in your code before calling `validate()` like so:
```c
if (regcomp(&config.pattern, "^[0-9a-f]{32}$", REG_NOSUB|REG_EXTENDED) != 0) {
    // handle error
}
```
The `gracePeriod` can be adjusted at runtime by changing the value of `GRACE_PERIOD`. It's not a dynamic setting since it would require making the function take an extra parameter and modifying all callers to pass in this new configuration value which could lead to mistakes. It might make more sense for this to be a compile-time constant or to be set via environment variable or command line argument if you need runtime changes.
']

