```javascript
const axios = require('axios');
const FormData = require('form-data');
let retryCount = 0;

async function uploadFile(url, libraryUploader, externalAPI) {
    const data = new FormData();

    // validate URL and file type (here we only consider images for the example)
    if (!validateUrlAndType(url)) throw new Error('Invalid URL or not an image');

    let fileSize; 
    try {
        const headRequest = await axios.head(url);
        fileSize = parseInt(headRequest.headers['content-length']);

        // check if file is too large (we consider files larger than 10MB as too large for the example)
        if (!validateFileSize(fileSize)) throw new Error('File too large');

    } catch (error) {
      externalAPI.logError(`Failed to get file size: ${error}`);
      return null;
    }

    // add file to form data for upload
    const response = await axios({ url, method: 'GET', responseType: 'stream' });
    data.append('file', response.data, { knownLength: fileSize });

    // retry logic in case of an error during the upload
    let uploadedUrl;
    while (!uploadedUrl && retryCount < 3) { 
        try {
            const result = await libraryUploader(data);
            uploadedUrl = result.url;

            // extract metadata from the uploaded file if needed
            const metaDataRequest = await axios.get(`${uploadedUrl}?metadata`);
            console.log('Metadata: ', metaDataRequest.data);
        } catch (error) {
            externalAPI.logError(`Upload failed, retrying... ${retryCount + 1}/3`);
            retryCount++;
        } 
    }

    if (!uploadedUrl) throw new Error('Failed to upload file after multiple attempts');

    return uploadedUrl;
}

function validateUrlAndType(url){
    // basic URL and image type validation, should be improved
    return url.startsWith('http') && (url.endsWith('.jpg') || url.endsWith('.png')); 
}

function validateFileSize(size) {
    // reject files larger than 10MB
    const fileLimit = 1e+7; //10 MB in bytes
    return size <= fileLimit;
}
```

In the real-world scenario, you would want to have more sophisticated URL and file type validations, as well as a more advanced retry logic. You also need error handling for all possible scenarios which are not covered in this example like network issues, incorrect libraryUploader function or externalAPI, etc. This code assumes that `libraryUploader` is an async function that takes FormData as input and returns an object with the uploaded URL, and `externalAPI.logError` is a function that logs errors to your chosen logging service.
