    int throughput_limit;
    int cpu_usage_cap;
} Arguments;

void monitor(Arguments args) {
   // Code for monitoring system to be inserted here.
}

void handleFileTranscoding(char *input_file, char *output_dir, char *encoding_params, int throughput_limit) {
    // Code for transcoding the file and handling of potential network delays goes here. 
}

void* processFile(void* arg) {
    Arguments *args = (Arguments*)arg;
    DIR *dirp;
    struct dirent *entry;

    dirp = opendir(args->input_dir);
    if (dirp == NULL) return;

    while ((entry = readdir(dirp)) != NULL) {
        if (entry->d_type == DT_REG) {  // only files, not directories
            char input_file[1024];
            snprintf(input_file, sizeof(input_file), "%s/%s", args->input_dir, entry->d_name);

            handleFileTranscoding(input_file, args->output_dir, args->encoding_params, args->throughput_limit);
        }
    }

    closedir(dirp);
}

void videoStreamingService(Arguments args) {
    pthread_t thread;
    int latency_target = args.latency_target;
    int cpu_usage_cap = args.cpu_usage_cap;

    time_t start, end;

    start = time(NULL);
    do {
        // Create a new thread to process files
        pthread_create(&thread, NULL, &processFile, &args);

        monitor(args);  // Monitor system usage in another thread

        pthread_join(thread, NULL);  // Wait for the transcoding thread to finish

        end = time(NULL);
    } while ((end - start) * 1000 < latency_target && getCPUUsage() > cpu_usage_cap);
}
```
