['Here's a simple implementation of such a class in Java using the MessageDigest library for MD5 hashing and ByteArrayOutputStream for efficient handling of large input streams:

```java
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.locks.ReentrantLock;
import java.io.*;

public class MD5Utility {
    private static final ReentrantLock lock = new ReentrantLock();

    public static String getMD5(String input) throws Exception{
        return getMD5(input.getBytes(StandardCharsets.UTF_8));
    }

    public static String getMD5(byte[] bytes) throws Exception {
        lock.lock();
        try {
            byte[] hash = MessageDigest.getInstance("MD5").digest(bytes);
            return convertToHex(hash);
        } finally {
            lock.unlock();
        }
    }

    public static String getMD5FromStream(InputStream stream) throws Exception{
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] buffer = new byte[1024];
        int length;

        lock.lock();
        try {
            while ((length = stream.read(buffer)) != -1) {
                baos.write(buffer, 0, length);
            }

            return getMD5(baos.toByteArray());
        } finally {
            lock.unlock();
        }
    }

    private static String convertToHex(byte[] data) {
        StringBuilder sb = new StringBuilder();

        for (byte b : data) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }
}
```
