['Below is an example Java class implementing a utility for hashing strings using MD5 while adhering to strict memory management policies and supporting asynchronous processing. The configuration parameters are loaded from a properties file. 

```Java
import org.apache.commons.codec.digest.DigestUtils;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.Properties;
import org.apache.commons.codec.binary.Base64;
import org.apache.log4j.Logger;

public class MD5HashUtility {
    private static final Logger LOGGER = Logger.getLogger(MD5HashUtility.class);

    private int chunkSize;
    private long memoryLimit;
    private ExecutorService executor;

    public MD5HashUtility() {
        try (InputStream input = new FileInputStream("config.properties")) {
            Properties prop = new Properties();
            prop.load(input);

            chunkSize = Integer.parseInt(prop.getProperty("chunkSize"));
            memoryLimit = Long.parseLong(prop.getProperty("memoryLimit"));
            int threadCount = Integer.parseInt(prop.getProperty("threadCount"));

            executor = Executors.newFixedThreadPool(threadCount);
        } catch (IOException ex) {
            LOGGER.error("Error loading configuration properties", ex);
        }
    }

    public void hashText(String text, Callback callback) {
        executor.submit(() -> {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] data = text.getBytes(StandardCharsets.UTF_8);

                for (int i = 0; i < data.length; i += chunkSize) {
                    if ((long) i * chunkSize > memoryLimit) {
                        throw new RuntimeException("Memory limit exceeded");
                    }

                    int end = Math.min(i + chunkSize, data.length);
                    md.update(data, i, end - i);
                }

                byte[] digest = md.digest();
                callback.onComplete(Base64.encodeBase64String(digest));
            } catch (Exception ex) {
                LOGGER.error("Error processing text hash", ex);
                callback.onFailure(ex);
            } finally {
                Arrays.fill(data, (byte) 0); // Overwrite sensitive data with zeros
            }
        });
    }

    public void hashBinaryData(InputStream is, Callback callback) {
        executor.submit(() -> {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] buffer = new byte[chunkSize];

                int bytesRead;
                while ((bytesRead = is.read(buffer)) != -1) {
                    if (bytesRead > memoryLimit) {
                        throw new RuntimeException("Memory limit exceeded");
                    }

                    md.update(buffer, 0, bytesRead);
                    Arrays.fill(buffer, (byte) 0); // Overwrite sensitive data with zeros
                }

                byte[] digest = md.digest();
                callback.onComplete(Base64.encodeBase64String(digest));
            } catch (Exception ex) {
                LOGGER.error("Error processing binary hash", ex);
                callback.onFailure(ex);
            } finally {
                Arrays.fill(buffer, (byte) 0); // Overwrite sensitive data with zeros
            }
        });
    }

    public interface Callback {
        void onComplete(String hash);
        void onFailure(Exception ex);
    }
}
```
Note: To run the above code, Apache commons-codec library is needed. Make sure to add it as a dependency in your project. Also, log4j for logging error messages and properties file with chunkSize and memoryLimit should be provided. Unit tests and stress tests are not included here due to space constraints, but they can be easily implemented by developers familiar with JUnit or other testing frameworks.
']

