public class HashUtil {
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public String hashTextSync(String input) {
        return DatatypeConverter.printHexBinary(hashBinarySync(input.getBytes()));
    }

    public Future<byte[]> hashTextAsync(String input) {
        return executor.submit(() -> hashBinarySync(input.getBytes()));
    }

    private byte[] hashBinarySync(byte[] input) {
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return digest.digest(input);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private Future<byte[]> hashBinaryAsync(ByteBuffer input) {
        return executor.submit(() -> {
            try {
                MessageDigest digest = MessageDigest.getInstance("SHA-256");
                digest.update(input);
                return digest.digest();
            } catch (Exception e) {
                throw new RuntimeException(e);
            }
        });
    }
}
```

