typedef struct {
    char mac_addr[18]; // MAC address (e.g., "00:0a:95:9d:68:16")
    char* ip_addrs;   // Dynamic array of IP addresses (use '|' to split them)
    int buffer_size;  // Size of packet statistics buffer
    void (*callback)(struct NICConfig*, int); // Callback function for configuration changes
} NICConfig;

typedef struct {
    pthread_mutex_t lock; // Mutex for thread safety
    NICConfig** configs;  // Dynamic array of configurations
    int count;           // Current number of configurations
    int capacity;        // Maximum limit
} NICManager;

void initNICManager(NICManager* manager, int initialCapacity) {
    manager->configs = malloc(sizeof(NICConfig*) * initialCapacity);
    manager->count = 0;
    manager->capacity = initialCapacity;
    pthread_mutex_init(&manager->lock, NULL);
}

void addConfig(NICManager* manager, NICConfig* config) {
    pthread_mutex_lock(&manager->lock); // Lock for synchronization

    if (manager->count == manager->capacity) {
        manager->capacity *= 2; // Double the capacity when full
        manager->configs = realloc(manager->configs, sizeof(NICConfig*) * manager->capacity);
    }

    manager->configs[manager->count++] = config;
    if (manager->callback != NULL) { // Notify of addition via callback if available
        manager->callback(config, 0);
    }

    pthread_mutex_unlock(&manager->lock); // Unlock after modification
}

NICConfig* getConfigByMAC(NICManager* manager, const char* mac) {
    for (int i = 0; i < manager->count; ++i) {
        if (strcmp(manager->configs[i]->mac_addr, mac) == 0) {
            return manager->configs[i];
        }
    }
    return NULL; // Not found
}

NICConfig* getConfigByIP(NICManager* manager, const char* ip) {
    for (int i = 0; i < manager->count; ++i) {
        char *ip_addr = strtok(manager->configs[i]->ip_addrs, "|");

        while (ip_addr != NULL) {
            if (strcmp(ip_addr, ip) == 0) {
                return manager->configs[i];
            }
            ip_addr = strtok(NULL, "|");
        }
    }

    return NULL; // Not found
}

// Assume some other functions to manage the configurations (e.g., updateConfig, removeConfig)
```
