void checkAndResize() {
    if (array.size == array.capacity) {
        size_t newCapacity = array.capacity * 2;
        LTE_RRC_UE_CONTEXT_T *newArray = realloc(array.array, sizeof(LTE_RRC_UE_CONTEXT_T) * newCapacity);

