void insertDynamicArray(DynamicArray *a, VM element) {
    pthread_mutex_lock(&a->lock);
    if (a->used == a->size) {
        a->size *= 2;
        a->array = (VM*)realloc(a->array, a->size * sizeof(VM));
    }
    a->array[a->used++] = element;
    pthread_mutex_unlock(&a->lock);
}

