    for (size_t i = 0; i < a->used; i++) {
        pthread_mutex_lock(&a->array[i].lock);
        if (strcmp(a->array[i].id, id) == 0) {
            return &a->array[i];
        }
        pthread_mutex_unlock(&a->array[i].lock);
