typedef struct node {
    int id;
    char status[50];
    time_t last_update_time;
} Node;

typedef struct metric {
    time_t timestamp;
    double value;
    char type[50];
} Metric;

Node* loadNodesFromConfig(char* fileName, int *numOfNodes) {
    json_error_t error;
    json_t *root = json_load_file(fileName, 0, &error);

    if(!root) {
        fprintf(stderr, "Error loading config: on line %d: %s\n", error.line, error.text);
        return NULL;
    }

    json_t *nodes = json_object_get(root, "nodes");
    if(!json_is_array(nodes)) {
        fprintf(stderr, "Expected 'nodes' to be an array\n");
        goto error;
    }

    *numOfNodes = json_array_size(nodes);
    Node* nodeArr = malloc(*numOfNodes * sizeof(Node));

    for (int i = 0; i < *numOfNodes; i++) {
        json_t *nodeJson = json_array_get(nodes, i);

        if(!json_is_object(nodeJson)) {
            fprintf(stderr, "Expected node to be an object\n");
            goto error;
        }

        Node* node = &nodeArr[i];
        json_t *id = json_object_get(nodeJson, "id");
        if(!json_is_integer(id)) {
            fprintf(stderr, "Expected 'id' to be an integer\n");
            goto error;
        }

        node->id = (int)json_integer_value(id);

        // similarly for status and last_update_time...
    }

    json_decref(root);
    return nodeArr;

error:
    json_decref(root);
    free(nodeArr);
    return NULL;
}
``` 

