['```c
#include <stdlib.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct PHY_RxPdu {
    // add relevant data members
} PHY_RxPdu;

typedef struct RRC_RxPdu {
    // add relevant data members
} RRC_RxPdu;

typedef struct LTEPHY_RxPdu {
    PHY_RxPdu *phy;
    RRC_RxPdu *rrc;
} LTEPHY_RxPdu;

typedef struct LTEPHY_DynamicArray {
    LTEPHY_RxPdu *array;
    size_t capacity;
    atomic_size_t count;
    pthread_mutex_t lock;
} LTEPHY_DynamicArray;

void init_dynamic_array(LTEPHY_DynamicArray *arr, size_t initial_capacity) {
    arr->array = (LTEPHY_RxPdu *) malloc(initial_capacity * sizeof(LTEPHY_RxPdu));
    arr->capacity = initial_capacity;
    atomic_init(&arr->count, 0);
    pthread_mutex_init(&arr->lock, NULL);
}

void resize_dynamic_array(LTEPHY_DynamicArray *arr) {
    arr->capacity *= 2;
    arr->array = (LTEPHY_RxPdu *) realloc(arr->array, arr->capacity * sizeof(LTEPHY_RxPdu));
}

void add_element(LTEPHY_DynamicArray *arr, LTEPHY_RxPdu element) {
    pthread_mutex_lock(&arr->lock);
    if (atomic_load(&arr->count) >= arr->capacity) {
        resize_dynamic_array(arr);
    }
    arr->array[atomic_fetch_add(&arr->count, 1)] = element;
    pthread_mutex_unlock(&arr->lock);
}

LTEPHY_RxPdu get_element(LTEPHY_DynamicArray *arr, size_t index) {
    pthread_mutex_lock(&arr->lock);
    LTEPHY_RxPdu element = arr->array[index];
    pthread_mutex_unlock(&arr->lock);
    return element;
}

size_t get_count(LTEPHY_DynamicArray *arr) {
    return atomic_load(&arr->count);
}

void free_dynamic_array(LTEPHY_DynamicArray *arr) {
    pthread_mutex_destroy(&arr->lock);
    free(arr->array);
}
```
This code implements a dynamic array that tracks the number of allocated structures and ensures thread safety. It uses atomic operations for concurrent access to the count, and mutex locks for ensuring that memory usage does not exceed predefined limits under heavy load conditions. The initial allocation size can be adjusted depending on expected use, with more efficient policies such as doubling when full providing a balance between efficiency and resource consumption.
']

