#include <forward_list>
#include <string>
using namespace std;

void modifyFileNameAndInsertString(forward_list<string>& fileList, string targetFilename, 
                                  string newExtension, char delimiter) {
    auto iter = fileList.before_begin();
    bool found = false;

    for (auto currIter = fileList.begin(); currIter != fileList.end(); ++currIter) {
        size_t dotPos = (*currIter).find('.');
        if(dotPos == string::npos) continue;  // no '.' in filename, skip it
        ++iter;

        string nameWithoutExt = (*currIter).substr(0, dotPos);
        if (nameWithoutExt != targetFilename) continue;  // not the target file, skip it

        found = true;

        size_t numCharsInName = nameWithoutExt.size();
        (*currIter).insert(dotPos, to_string(numCharsInName) + delimiter);

        break;
    }

    if(!found) {
        fileList.push_front(".");  // add dummy string to be able to insert after it
        targetFilename += ".";  
    }

    string extWithDelimiter = newExtension.empty() ? "" : delimiter + newExtension;
    fileList.insert_after(iter, targetFilename + extWithDelimiter);  // insert after found or dummy element
}
```
