```python
import os
import subprocess
from hashlib import md5, sha256
from Crypto.Hash import SHA256
from multiprocessing import Pool
import json
import random

def secure_random():
    return int(sha256((str(random.SystemRandom().randint(0, 100))).encode()).hexdigest(), 16) % 10**8

def initializeRecordsWithRandomValues(lower_bound: int, upper_bound: int):
    if lower_bound > upper_bound:
        print("Lower bound is greater than Upper Bound. Skipping Processing")
        return {}

    offsets = []
    keys = []
    records = []
    hash_map = {}

    for i in range(lower_bound, upper_bound+1):
        offsets.append(secure_random())
        key = secure_random()
        value = {"value": secure_random()}

        keys.append(key)
        records.append({"offset": offsets[-1], "key": keys[-1], **value})

    if len(records) > 500:
        with Pool(os.cpu_count()) as p:
            hash_map = dict(p.map(generate_hash, records))
    else:
        for record in records:
            generate_hash(record)

    return hash_map

def generate_hash(record):
    concatenated = f"{record['offset']}, {record['key']}, {record['value']}"
    md5_digest = md5(concatenated.encode()).hexdigest()
    return record['key'], md5_digest

def modify_config(json_config, weaknesses):
    password = SHA256.new(data=str(weaknesses).encode('utf-8')).hexdigest()

    with open("modified_config.txt", "w") as outfile:
        json_string = json.dumps(json_config)

        for password in [password]:
            json_string = json_string.replace('[PASSWORD]', password)

        subprocess.run(['sed', '-e', f's/\\[PASSWORD\\]/{password}/g', "config.txt"], stdout=outfile, check=True)

def determine_weakness(value: int):
    weaknesses = {1: 'Very Weak', 2: 'Weak', 3: 'Good', 4: 'Strong'}

    if value < 50:
        return weaknesses[1]
    elif value < 75:
        return weaknesses[2]
    elif value < 90:
        return weaknesses[3]
    else:
        return weaknesses[4]
``` 
