}

void initializeRecordsWithRandomValues(int lower, int upper) {
    if (lower > upper) {
        printf("Invalid range. Lower bound must be less than or equal to upper bound.\n");
        return;
    }

    srand(time(NULL));
    long* offsets = malloc(3 * sizeof(long));
    int* keys = calloc(3, sizeof(int));
    record* records = malloc(3 * sizeof(record));
    BatchRecord batch[3];

    if (offsets == NULL || keys == NULL || records == NULL) {
        printf("Memory allocation failed.\n");
        return;
    }

    RAND_seed(md5, MD5_DIGEST_LENGTH);
    for(int i = 0; i < 3; i++) {
        offsets[i] = random() % (upper - lower + 1) + lower;
        keys[i] = rand();
        records[i].val = rand() % (upper - lower + 1) + lower;

        batch[i].offset = offsets[i];
        batch[i].key = keys[i];
        batch[i].value = records[i];
    }

    pthread_t threadId;
    int status = pthread_create(&threadId, NULL, &processBatch, batch);

    if (status != 0) {
        printf("Thread creation failed with error: %d\n", status);
    } else {
        void* result;
        pthread_join(threadId, &result);
    }

    free(offsets);
    free(keys);
    free(records);
}
