// Function to validate IP address
int isValidIpAddress(char *ipAddress) {
    struct in_addr addr;
    return inet_pton(AF_INET, ipAddress, &addr) == 1;
}

// Function for logging
void logEvent(LogLevel level, char* message) {
    pthread_mutex_lock(&lock); // Lock mutex to ensure thread safety
    if (logFile == NULL) {
        logFile = fopen("lte.log", "a");
    }

    switch (level) {
        case DEBUG: fprintf(logFile, "[DEBUG] %s\n", message); break;
        case INFO:  fprintf(logFile, "[INFO ] %s\n", message); break;
        case WARN:  fprintf(logFile, "[WARN ] %s\n", message); break;
        case ERROR: fprintf(logFile, "[ERROR] %s\n", message); break;
    }

    pthread_mutex_unlock(&lock); // Unlock mutex after log operation
}

// Function to add context
void addContext(LTE_RRC_UE_CONTEXT_T *context) {
    if (currentContextCount >= maxContextCount || !isValidIpAddress(context->ipAddress)) {
        return; // Reject or remove least recently used contexts based on system constraints
    }

    pthread_mutex_lock(&lock); 
    contextArray[currentContextCount++] = context; 
    logEvent(INFO, "Added new context");
    pthread_mutex_unlock(&lock); 
}
