    system->records = malloc(sizeof(TrafficRecord*) * system->max_concurrent_sessions);
    pthread_mutex_init(&system->lock, NULL);
}

void add_record(TrafficManagementSystem *system, TrafficRecord *record) {
    pthread_mutex_lock(&system->lock);  // Acquire the lock

    if (system->next_free_index >= system->max_concurrent_sessions){
        system->records = realloc(system->records, sizeof(TrafficRecord*) * system->max_concurrent_sessions * 2); // Double the size of the array if we run out of space
    }

    system->records[system->next_free_index] = record;
    system->next_free_index++;

    pthread_mutex_unlock(&system->lock); // Release the lock
}

