def process_metrics(filename):
    with file_read_lock: # Ensures only one thread reads the file at a time
        try:
            with open(filename, "r") as f:
                lines = f.readlines()
                last_line = lines[-1].strip()

                # Split line into sequence number and metrics
                seq_num, *metrics = last_line.split(',')

