NFAPI_CRC_INDICATION_PDU_T* generateList(size_t N) {
    pthread_mutex_lock(&lock);  // Lock mutex to ensure thread-safety.

    srand(time(NULL));  // Seed the random number generator.

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));  // Allocate memory for the array.

    if (list == NULL) {
