["Here is a basic implementation in C that outlines the main functionalities for thread pool. This code doesn't contain any error handling or extensive testing, but it gives an idea about how to approach this problem:

```C
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    void (*task)(void *);
    void *arg;
} task_t;

typedef struct thread_pool_s {
    pthread_mutex_t lock;
    sem_t availableTasks;
    int numOfThreads;
    int sizeQueue;
    task_t **taskQueue;
    int head, tail;
} thread_pool_t;

void *worker(void *arg) {
    thread_pool_t *tp = (thread_pool_t *) arg;

    while (1) {
        sem_wait(&(tp->availableTasks));

        pthread_mutex_lock(&(tp->lock));

        task_t *nextTask = tp->taskQueue[tp->head++];

        if (tp->head == tp->sizeQueue) {
            tp->head = 0;
        }

        pthread_mutex_unlock(&(tp->lock));

        nextTask->task(nextTask->arg);
    }
}

void threadPoolInitialize(thread_pool_t *tp, int numOfThreads, int sizeQueue) {
    tp->numOfThreads = numOfThreads;
    tp->sizeQueue = sizeQueue;
    pthread_mutex_init(&(tp->lock), NULL);
    sem_init(&(tp->availableTasks), 0, 0);

    tp->head = 0;
    tp->tail = 0;
    tp->taskQueue = (task_t **) malloc(sizeof(task_t *) * sizeQueue);

    for (int i=0; i<numOfThreads; ++i) {
        pthread_t thread;
        pthread_create(&thread, NULL, worker, tp);
    }
}

void taskSubmit(thread_pool_t *tp, void (*task)(void *), void *arg) {
    task_t *newTask = (task_t *) malloc(sizeof(task_t));
    newTask->task = task;
    newTask->arg = arg;

    pthread_mutex_lock(&(tp->lock));

    tp->taskQueue[tp->tail++] = newTask;

    if (tp->tail == tp->sizeQueue) {
        tp->tail = 0;
    }

    pthread_mutex_unlock(&(tp->lock));

    sem_post(&(tp->availableTasks));
}
```
This code creates a basic thread pool that can be configured with the number of threads and task queue size. It uses `pthread` for creating threads, which is POSIX standard API. It also uses `semaphore` to wait and signal between threads. Task submission is done by adding the new task into the queue and notifying the workers about available tasks. The workers then fetch a task from the queue and execute it.
Please note that this is a simplified version of thread pool, and some improvements could be made for example better handling of high-level task prioritization and error handling can be added to avoid leaks or crashes. Also, consider using condition variables for more precise control over task scheduling.
"]

