RX_UE_REL8_Info_T *manageStructs(int N, int MAX_STRUCTS) {
    if (N > MAX_STRUCTS) {
        fprintf(stderr, "Error: Number of structures exceeds maximum limit\n");
        return NULL;
    }

    RX_UE_REL8_Info_T *info = calloc(1, sizeof(RX_UE_REL8_Info_T));
