#define MAX_ELEMENTS 1000

typedef struct {
    uint32_t rnti;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

// Define hash table with pthread mutexes for thread-safe operations
pthread_mutex_t rnti_table[MAX_ELEMENTS];
atomic_uint rnti_count = 0;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate(uint32_t rnti) {
    if (rnti_count >= MAX_ELEMENTS) return NULL; // List full

    uint32_t index = rnti % MAX_ELEMENTS; // Simple hash function

    pthread_mutex_lock(&rnti_table[index]);
    NFAPI_CRC_INDICATION_PDU_T* element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (element == NULL) { // Memory allocation failed
        pthread_mutex_unlock(&rnti_table[index]);
        return NULL;
    }

    element->rnti = rnti;
    // Other initializations...
    rnti_count++;
    pthread_mutex_unlock(&rnti_table[index]);

    return element;
}
