int validatePort(int port) {
    return (port >= 0 && port <= 65535);
}

void initializePDU(Pdu pdus[], int size) {
    for (int i = 0; i < size; ++i) {
        // Generate a unique MAC address. 
        sprintf(pdus[i].mac, "MAC%d", i);

        // Generate a unique IP address.
        sprintf(pdus[i].ip, "192.168.0.%d", i);

        // Generate a unique TCP/UDP port pair. 
        pdus[i].port = validatePort(5000 + i) ? (5000 + i) : 5000;
    }
}

int main() {
    Pdu pdus[MAX_PDU];

    initializePDU(pdus, MAX_PDU);

    for (int i = 0; i < MAX_PDU; ++i) {
        printf("MAC: %s IP: %s Port: %d\n", pdus[i].mac, pdus[i].ip, pdus[i].port);
    }

    return 0;
}
