int inventorySize = 0;

void addToInventory(int productID, int stockQuantity, double price, int supplierIDs[]) {
    for (int i = 0; i < inventorySize; ++i) {
        if (inventory[i].productID == productID) {
            printf("Warning: Duplicate product ID detected. Updating stock quantity.\n");
            inventory[i].stockQuantity = stockQuantity;
            return;
        }
    }

    inventorySize++;
    inventory = (InventoryItem*)realloc(inventory, inventorySize * sizeof(InventoryItem));
    InventoryItem newItem = {productID, abs(stockQuantity), price};
    for (int i = 0; i < 10 && supplierIDs[i] != 0; ++i) 
        newItem.supplierIDs[i] = supplierIDs[i];
    inventory[inventorySize - 1] = newItem;
}

void temporarilyOutOfStock(int productID) {
    for (int i = 0; i < inventorySize; ++i) {
        if (inventory[i].productID == productID) {
            inventory[i].stockQuantity = 0;
            return;
        }
    }
}

void backInStock(int productID, int stockQuantity) {
    for (int i = 0; i < inventorySize; ++i) {
        if (inventory[i].productID == productID) {
            inventory[i].stockQuantity = abs(stockQuantity);
            return;
        }
    }
}
