#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct DPU {
    int hardware_id;
    void* memory_address;
    char* instruction_set;
    time_t timestamp;
} DPU;

DPU** dpuArray = NULL;
int arraySize = 0;
pthread_mutex_t lock;  // Mutual exclusion for concurrent accesses.

void* allocateMemory() {
    void* mem = malloc(sizeof(void*));  // Replace with appropriate memory allocation based on your system
    if (mem == NULL) {
        fprintf(stderr, "Out of memory!\n");
        exit(1);
    }
    return mem;
}

int addDPU(int hardware_id, void* memory_address, char* instruction_set) {
    pthread_mutex_lock(&lock);  // Lock for thread-safe access.

    int i;
    for (i = 0; i < arraySize; ++i) {
        if (dpuArray[i]->memory_address == memory_address) {
            fprintf(stderr, "Warning: Duplicate memory address found. Reassigning...\n");
            dpuArray[i]->timestamp = time(NULL);  // Update the timestamp for reassignments.
        } else if (dpuArray[i]->hardware_id == hardware_id) {
            fprintf(stderr, "Error: Duplicate hardware ID found. Aborting...\n");
            return -1;
        }
    }
    ++arraySize;
    dpuArray = realloc(dpuArray, arraySize * sizeof(DPU*));  // Reallocate memory for the new DPU entry.
    if (dpuArray == NULL) {
        fprintf(stderr, "Out of memory!\n");
        exit(1);
    }
    dpuArray[arraySize - 1] = malloc(sizeof(DPU));  // Allocate memory for the new DPU.
    if (dpuArray[arraySize - 1] == NULL) {
        fprintf(stderr, "Out of memory!\n");
        exit(1);
    }

    dpuArray[arraySize - 1]->hardware_id = hardware_id;
    dpuArray[arraySize - 1]->memory_address = memory_address;
    dpuArray[arraySize - 1]->instruction_set = instruction_set;
    dpuArray[arraySize - 1]->timestamp = time(NULL);  // Timestamp for when the DPU was added.

    pthread_mutex_unlock(&lock);  // Unlock after modifying shared data.
    return arraySize - 1;  // Return index of newly added DPU.
}
```
