['Here's a simplified version of such a C program using `getopt` to parse command-line arguments and handling input file reading in chunks:
```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <getopt.h>
#include <string.h>
#include <fcntl.h>

#define MAX_LINE_LENGTH 4096
#define CHUNK_SIZE 1024

void printUsage() {
    printf("Usage: ./program [-c] [-l] [-o output_file] [--manpage] [-n max_lines] file\n");
}

int main(int argc, char *argv[]) {
    const char* shortOptions = "clo:n:";
    struct option longOptions[] = {
        {"manpage", no_argument, NULL, 'm'},
        {0, 0, 0, 0}
    };

    int c;
    int countCharacters = 0, printLineNumbersOnly = 0;
    char* outputFilePath = NULL;
    long maxLines = -1;

    while ((c = getopt_long(argc, argv, shortOptions, longOptions, NULL)) != -1) {
        switch (c) {
            case 'c':
                countCharacters = 1;
                break;
            case 'l':
                printLineNumbersOnly = 1;
                break;
            case 'o':
                outputFilePath = optarg;
                break;
            case 'm':
                printf("Manpage goes here...\n");
                return 0;
            case 'n':
                maxLines = strtol(optarg, NULL, 10);
                break;
            default:
                printUsage();
                exit(EXIT_FAILURE);
        }
    }

    if (optind >= argc) {
        printf("Expected input file argument.\n");
        printUsage();
        exit(EXIT_FAILURE);
    }

    char *inputFilePath = argv[optind];
    FILE* outputFileHandle = stdout;

    if (outputFilePath != NULL) {
        outputFileHandle = fopen(outputFilePath, "w");
        if (!outputFileHandle) {
            perror("Error opening file for writing");
            exit(EXIT_FAILURE);
        }
    }

    FILE* inputFileHandle = fopen(inputFilePath, "r");
    if (!inputFileHandle) {
        perror("Error opening file for reading");
        exit(EXIT_FAILURE);
    }

    char buffer[CHUNK_SIZE];
    long totalLines = 0;
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), inputFileHandle)) > 0) {
        if (ferror(inputFileHandle)) {
            perror("Error reading file");
            exit(EXIT_FAILURE);
        }

        for (size_t i = 0; i < bytesRead; ++i) {
            if (!printLineNumbersOnly && !countCharacters)
                fputc(buffer[i], outputFileHandle);

            if (buffer[i] == '\n')
                ++totalLines;
        }
    }

    printf("Total lines: %ld\n", totalLines);

    // Close all open handles
    fclose(inputFileHandle);
    if (outputFileHandle != stdout)
        fclose(outputFileHandle);
}
```
Please note that this is a very basic example and doesn't handle many edge cases, like the case when `max_lines` option is given but no file is specified. It also doesn't count characters in any way since it doesn't actually read lines, instead it reads bytes from the file which may lead to incorrect results if your files contain multi-byte characters and you want to count characters.
']

