    public Map<String, Object> processFinancialTransactions(List<TransactionRecord> records) throws NoSuchAlgorithmException {
        Map<String, Object> resultMap = new HashMap<>();

        long startTime = System.currentTimeMillis();

        // Parallel stream for performance optimization
        Stream<TransactionRecord> parallelStream = records.parallelStream();

        List<String> hashes = parallelStream.map(record -> {
            try {
                validateRecord(record);

                String recordAsStr = recordToString(record);

                // Compute MD5 hash of the concatenated string
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] digest = md.digest(recordAsStr.getBytes(StandardCharsets.UTF_8));
                String myHash = DatatypeConverter.printHexBinary(digest);

                return myHash;
            } catch (Exception e) {
                // Log the exception and skip to next record
                System.out.println("Error processing transaction: " + e.getMessage());
                return null;
            }
        })
        .filter(Objects::nonNull)
        .collect(Collectors.toList());

        long endTime = System.currentTimeMillis();

        // Calculate summary report and derive unique identifier for the batch
        int totalTransactions = records.size() - Collections.frequency(hashes, null);
        double avgTransactionAmount = hashes.stream().mapToDouble(h -> Double.parseDouble(h)).average().orElse(0);
        String uniqueId = generateMD5HashFromList(hashes);

        resultMap.put("Summary", new SummaryReport(totalTransactions, avgTransactionAmount));
        resultMap.put("Processing Time (ms)", endTime - startTime);
        resultMap.put("Record Hashes", hashes);
        resultMap.put("Batch Id", uniqueId);

