['Here is a simple implementation of `DataProcessor` class using Apache Commons library for MD5 hash computation, Guava for caching and RateLimiter for managing external API calls:

```java
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.util.concurrent.RateLimiter;
import org.apache.commons.codec.digest.DigestUtils;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.concurrent.TimeUnit;
import java.util.logging.Level;
import java.util.logging.Logger;

public class DataProcessor {

    private static final Logger logger = Logger.getLogger(DataProcessor.class.getName());
    private static final RateLimiter rateLimiter = RateLimiter.create(10.0); // 10 calls per second
    private static LoadingCache<String, String> cache;

    static {
        cache = CacheBuilder.newBuilder()
                .maximumSize(10_000)
                .expireAfterWrite(24, TimeUnit.HOURS) // Cache for 24 hours
                .build(new CacheLoader<String, String>() {
                    @Override
                    public String load(String input) throws Exception {
                        return fetchLatestVersionFromAPI(input);
                    }
                });
    }

    private static String fetchLatestVersionFromAPI(String input){
        // Implement actual fetching from external API
        return "latest-version"; 
    }

    public static String processStringData(String input) {
        try{
            if(!rateLimiter.tryAcquire()){
                logger.log(Level.WARNING, "Rate limit exceeded");
                throw new Exception("Rate limit exceeded");
            }

            String latestVersion = cache.get(input);
            return computeMD5Hash(latestVersion);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error processing string data", e);
            // Handle exception gracefully and rethrow or return appropriate error response
            throw new RuntimeException("Failed to process string data", e);
        }
    }

    private static String computeMD5Hash(String input) {
        try{
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(input.getBytes(StandardCharsets.UTF_8));

            return Base64.getEncoder().encodeToString(hashBytes);
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Failed to compute MD5 hash", e);
            throw new RuntimeException("Failed to compute MD5 hash", e);
        }
    }
}
```
