import com.google.common.cache.Cache;
import com.google.common.cache.CacheBuilder;
import com.google.common.util.concurrent.RateLimiter;
import org.apache.commons.codec.digest.DigestUtils;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.client.RestTemplate;

@SpringBootApplication
public class DataProcessor {
    private final RestTemplate restTemplate = new RestTemplate();
    private static final String API_URL = "http://your-api-url";
    // Cache for recent responses to reduce API calls
    private Cache<String, String> responseCache;

    public DataProcessor() {
        // Initialize cache with a fixed size and LRU eviction policy
        this.responseCache = CacheBuilder.newBuilder().maximumSize(10_000).build();
    }

    private String fetchStringFromAPI(String input) {
        // Retrieve the latest version of the string from the external API
        return restTemplate.getForObject(API_URL + "/" + input, String.class);
    }

    public static String processStringData(String input) throws Exception {
        if (input == null || input.length() == 0) {
            throw new IllegalArgumentException("Input string cannot be null or empty");
        }

        // Rate limiter to manage API calls per second
        final RateLimiter rateLimiter = RateLimiter.create(10); 
        if (!rateLimiter.tryAcquire()) {
            throw new Exception("Reached API rate limit");
        }

        // Check cache before making API call
        String cachedResponse = responseCache.getIfPresent(input);
        if (cachedResponse != null) {
            return cachedResponse;
        }

        // Fetch the latest version of the string from the external API
        String latestString = fetchStringFromAPI(input);

        // Compute and return the MD5 hash of the string
        final String md5Hash = DigestUtils.md5Hex(latestString);

        // Cache the response for future requests
        responseCache.put(input, md5Hash);

        return md5Hash;
    }
}
```
This is a simple implementation and there are many other considerations to take into account (such as configuration management, error handling, health checks, etc.) when designing such a system. 

Please note that in an actual production environment, you would need to handle many more aspects like integration with external API, monitoring resources, scalability, edge cases and validations, logging etc., which are not covered in this simple example.
