// Global mutex for thread safety
pthread_mutex_t lock;

char* appendSlashIfNotExceeds(const char* str, int sizeLimit) {
    if (strlen(str) > sizeLimit) {
        // Log error
        pthread_mutex_lock(&lock);
        openlog("LogExample", LOG_PID | LOG_CONS, LOG_USER);
        syslog(LOG_ERR, "String exceeded size limit");
        closelog();
        pthread_mutex_unlock(&lock);

        return NULL;
