        // Append a slash to the string and return it
        char* result = g_strdup_printf("%s/", str);
        return result;
    }
}

int main() {
    pthread_mutex_init(&lock, NULL);

    // Example usage
    char* newStr = appendSlashIfNotExceeds("Hello World", 12);
    if (newStr != NULL) {
        printf("%s\n", newStr);
        free(newStr);
    }

    pthread_mutex_destroy(&lock);
    return 0;
}
