['```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;  // Assuming this is a randomly set flag for simplicity.
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

// Custom hash table to store RNTI and corresponding node.
typedef struct HashTable {
    int size;
    Node** nodes;
    pthread_mutex_t* locks;  // To ensure thread safety.
} HashTable;

HashTable* createHashTable(int size) {
    HashTable* table = malloc(sizeof(HashTable));
    table->size = size;
    table->nodes = calloc(table->size, sizeof(Node*));
    table->locks = malloc(table->size * sizeof(pthread_mutex_t));

    for (int i = 0; i < table->size; ++i) {
        pthread_mutex_init(&(table->locks[i]), NULL);
    }

    return table;
}

void freeHashTable(HashTable* table) {
    for (int i = 0; i < table->size; ++i) {
        Node* node = table->nodes[i];
        while (node != NULL) {
            Node* tempNode = node;
            node = node->next;
            free(tempNode->data);
            free(tempNode);
        }
    }

    for (int i = 0; i < table->size; ++i) {
        pthread_mutex_destroy(&(table->locks[i]));
    }

    free(table->nodes);
    free(table->locks);
    free(table);
}

// Simple hash function for demonstration purposes.
int hashFunction(int RNTI, int size) {
    return abs(RNTI) % size;
}

Node* createNode(NFAPI_CRC_INDICATION_PDU_T* data) {
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        // Out of memory.
        return NULL;
    }

    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

// Insert node in the hash table. 
int insert(HashTable* table, NFAPI_CRC_INDICATION_PDU_T* data) {
    int key = hashFunction(data->RNTI, table->size);
    pthread_mutex_lock(&(table->locks[key]));

    Node* newNode = createNode(data);
    if (newNode == NULL) {
        // Out of memory.
        pthread_mutex_unlock(&(table->locks[key]));
        return -1; 
    }

    newNode->next = table->nodes[key];
    table->nodes[key] = newNode;

    pthread_mutex_unlock(&(table->locks[key]));
    return key; // Return index in the hash table.
}

// Delete node from the hash table. 
void delete(HashTable* table, int RNTI) {
    int key = hashFunction(RNTI, table->size);
    pthread_mutex_lock(&(table->locks[key]));

    Node* node = table->nodes[key];
    Node* prevNode = NULL;

    while (node != NULL) {
        if (node->data->RNTI == RNTI) {
            // Remove the node from the linked list.
            if (prevNode == NULL) {
                table->nodes[key] = node->next;
            } else {
                prevNode->next = node->next;
            }

            free(node->data);
            free(node);
            break;
        }

        prevNode = node;
        node = node->next;
    }

    pthread_mutex_unlock(&(table->locks[key]));
}
```
Please note that this code does not handle situations where the hash table is full (all buckets are occupied) or when a requested element could not be found in the hash table. This is just for demonstration and further improvements can be made based on actual use case, such as resizing the hash table dynamically or using a different hash function that reduces collisions.
']

