['Here is how you could implement this Java method. It uses several libraries such as SnakeYAML for parsing YAML, Apache Commons for string manipulation and computing hash functions, SLF4J for logging and Java's built-in `java.util.concurrent` package for parallel processing and resource management:

```java
import org.apache.commons.codec.digest.DigestUtils;
import org.yaml.snakeyaml.Yaml;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.*;

public class UserActivityProcessor {
    private static final List<String> SUPPORTED_ACTIVITY_TYPES = Arrays.asList("type1", "type2");

    public Map<Integer, Object> processUserActivitiesWithTaskDetails(List<Map<String, String>> activityRecords, String yamlFilePath) {
        try {
            // Load YAML configuration file
            InputStream inputStream = new FileInputStream(new File(yamlFilePath));
            Map<String, Object> config = new Yaml().load(inputStream);

            ExecutorService executorService = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

            List<Future<BatchResult>> futures = new ArrayList<>();
            for (int i = 0; i < activityRecords.size(); i += 1000) {
                final List<Map<String, String>> batchActivities = activityRecords.subList(i, Math.min(i + 1000, activityRecords.size()));
                Future<BatchResult> future = executorService.submit(() -> processActivityBatch(batchActivities));
                futures.add(future);
            }

            Map<Integer, Object> resultMap = new HashMap<>();
            for (int i = 0; i < futures.size(); i++) {
                BatchResult batchResult = futures.get(i).get();
                resultMap.put(i, batchResult);
                // Update YAML configuration based on batch summary
                config.put("metrics", computeMetricsFromBatchSummary(batchResult));
            }

            String updatedYaml = new Yaml().dump(config);
            Files.write(Paths.get(yamlFilePath + ".new"), updatedYaml.getBytes());
            executorService.shutdown();
            return resultMap;
        } catch (IOException | InterruptedException | ExecutionException e) {
            throw new RuntimeException("Failed to process activities", e);
        }
    }

    private BatchResult processActivityBatch(List<Map<String, String>> batchActivities) {
        List<String> hashes = new ArrayList<>();
        for (Map<String, String> activity : batchActivities) {
            if (!isValidUserId(activity.get("userID")) || 
                !isValidTimestamp(activity.get("timestamp")) || 
                !isSupportedActivityType(activity.get("type"))) {
                continue; // skip invalid record
            }

            String concatenated = activity.values().stream()
                                            .reduce((s1, s2) -> s1 + "," + s2).orElse("");
            hashes.add(DigestUtils.sha256Hex(concatenated));
        }

