```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;

public class DataProcessor {
    private static final String MD5 = "MD5";
    private static final int MAX_CACHE_SIZE = 1000;
    private static Map<String, Future<byte[]>> cache = new LinkedHashMap<>() { // Use LinkedHashMap to provide LRU eviction policy
        @Override
        protected boolean removeEldestEntry(Map.Entry eldest) {
            return size() > MAX_CACHE_SIZE;
        }
    };

    private static ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors()); // Create a fixed thread pool

    public static byte[] processStringData(String input) throws InterruptedException, ExecutionException {
        if (input == null || input.isEmpty()) throw new IllegalArgumentException("Input string can't be null or empty");

        Future<byte[]> cachedHash = cache.get(input);
        if (cachedHash != null) return cachedHash.get(); // Return the cached result if available

        Future<byte[]> hashFuture = executor.submit(() -> computeMD5Hash(input)); // Compute the MD5 hash asynchronously
        cache.put(input, hashFuture);

        return hashFuture.get();
    }

    private static byte[] computeMD5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance(MD5);
            byte[] messageDigest = md.digest(input.getBytes(StandardCharsets.UTF_8));
            return messageDigest;
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("Could not find MD5 algorithm", e);
        }
    }
}
```
