public class DataProcessor {

    private static final int MAX_CACHE_SIZE = 100000;
    private static ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();
    private static CacheManager externalCacheManager;

    public static String processStringData(String input) {
        try {
            if (cache.containsKey(input)) {
                return cache.get(input);
            }

            String versionedInput = getLatestVersionFromAPI(input);
            String md5Hex = DigestUtils.md5Hex(versionedInput);

            if (cache.size() >= MAX_CACHE_SIZE) {
                cache.removeEldest(); // remove the least recently used entry
            }

            cache.put(input, md5Hex);

            return md5Hex;
        } catch (Exception e) {
            System.err.println("Error processing string data: " + e.getMessage());
            return null;
        }
    }

    private static String getLatestVersionFromAPI(String input) throws Exception {
