        Client client = ClientBuilder.newClient();
        WebTarget target = client.target("http://external-api.com/versionedStrings/" + input);
        Response response = target.request().get();

        if (response.getStatus() != 200) {
            throw new Exception("Failed to fetch data from external API: " + response.readEntity(String.class));
        }

        return response.readEntity(String.class);
    }
}
