// Structure for TCP_CONNECTION_CONTEXT_T
typedef struct {
    int ip;
    int tcpSessionId;
    void* packetHeaderBuffer;
    time_t lastActiveTime;
    size_t numPacketsStored;
    bool isConnectionActive;
} TCP_CONNECTION_CONTEXT_T;

// Global variables for array and mutex
TCP_CONNECTION_CONTEXT_T* connectionArray = NULL;
size_t arraySize = 0;
pthread_mutex_t lock;

// Function to add new connections, update existing ones
void manageConnection(int ip, int tcpSessionId, void* packetHeaderBuffer) {
    pthread_mutex_lock(&lock);

    // Find if the connection already exists in array
    for (size_t i = 0; i < arraySize; ++i) {
        if (connectionArray[i].tcpSessionId == tcpSessionId) {
            // Update existing connection
            connectionArray[i].ip = ip;
            connectionArray[i].packetHeaderBuffer = packetHeaderBuffer;

            pthread_mutex_unlock(&lock);
            return;
        }
    }

    // If connection does not exist, add new one
    arraySize++;
    connectionArray = realloc(connectionArray, sizeof(TCP_CONNECTION_CONTEXT_T) * arraySize);

    TCP_CONNECTION_CONTEXT_T newConnection;
    newConnection.ip = ip;
    newConnection.tcpSessionId = tcpSessionId;
    newConnection.packetHeaderBuffer = packetHeaderBuffer;
    connectionArray[arraySize - 1] = newConnection;

    pthread_mutex_unlock(&lock);
}
