    void* sibs; // dynamically allocated buffer for system information blocks (SIBs)
} LTE_RRC_UE_CONTEXT_T;

// Global Variables
LTE_RRC_UE_CONTEXT_T** contexts; // dynamic array of context structs
int contextCount;  // total number of contexts
int sibBufferSizeTotal;  // total size of all SIB buffers
