// Initialize the array and other variables
void initializeContexts() {
    contextCount = 0;
    sibBufferSizeTotal = 0;
}

// Add a new context to the array
void addContext(LTE_RRC_UE_CONTEXT_T* context) {
    pthread_mutex_lock(&lock);  // acquire lock for concurrent access control

    contexts = realloc(contexts, sizeof(*contexts) * (contextCount + 1));  // resize array
    contexts[contextCount] = context;
    contextCount++;

    sibBufferSizeTotal += getSibBufferSize(context);

    pthread_mutex_unlock(&lock);  // release lock
