    std::shared_ptr<ProtocolStack> protocolStack;
    std::shared_ptr<TransportLayer> transportLayer;
    std::shared_ptr<ApplicationLayer> applicationLayer;

    EventPriority priority;
};

class NetworkEventsManager {
public:
    void addEvent(NetworkEvent event) {
        // To ensure thread safety, lock the mutex before modifying shared data.
        const std::lock_guard<std::mutex> lock(mMutex);

        mEvents.push_back(event);
    }

    NetworkEvent getNextEvent() {
        // To ensure thread safety, lock the mutex before modifying shared data.
        const std::lock_guard<std::mutex> lock(mMutex);

        if (!mEvents.empty()) {
            // Find the event with highest priority and remove it from the list.
            auto highestPriorityIt = mEvents.begin();
            for (auto it = mEvents.begin() + 1; it != mEvents.end(); ++it) {
                if (static_cast<int>(it->priority) > static_cast<int>(highestPriorityIt->priority)) {
                    highestPriorityIt = it;
                }
            }

            NetworkEvent eventToProcess = *highestPriorityIt;
            mEvents.erase(highestPriorityIt);

            return eventToProcess;
        } else {
            // Return an empty NetworkEvent if no events are available.
            return {};
        }
    }

private:
    std::vector<NetworkEvent> mEvents;
    std::mutex mMutex;
};
```
