#include <time.h>

typedef struct AudioStream {
    int sampling_rate;
    int bit_depth;
    double duration;
} AudioStream;

typedef struct Node {
    AudioStream *stream;
    struct Node *next;
} Node;

typedef struct List {
    pthread_mutex_t mutex;  // to ensure thread safety.
    Node *head;
    int allocated_count;  // count of currently allocated streams.
    int max_allocated_count;  // maximum count of allocated streams at any point in time.
} List;

/* Allocate memory for a new AudioStream object */
AudioStream* allocate_stream(int sampling_rate, int bit_depth, double duration) {
    AudioStream *stream = (AudioStream*) malloc(sizeof(AudioStream));
    if (stream == NULL) {
        // handle allocation error
        return NULL;
    }
    stream->sampling_rate = sampling_rate;
    stream->bit_depth = bit_depth;
    stream->duration = duration;
    return stream;
}

/* Add a new AudioStream object to the list */
void add_stream(List *list, AudioStream *stream) {
    Node *newNode = (Node*) malloc(sizeof(Node));
    if (newNode == NULL) {
        // handle allocation error
        return;
    }
    newNode->stream = stream;
    pthread_mutex_lock(&list->mutex);
    ++list->allocated_count;
    if (list->allocated_count > list->max_allocated_count) {
        list->max_allocated_count = list->allocated_count;  // update max allocated count.
    }
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
}

/* Free memory of a AudioStream object */
void free_stream(AudioStream *stream) {
    free(stream);  // assuming stream is not NULL.
}
