struct setting* loadConfig(char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Failed to open file\n");
        return NULL;
    }

    struct setting *settings = malloc(sizeof(struct setting)*10); // Assuming a max of 10 settings for simplicity
