    while (fgets(buffer, sizeof(buffer), fp)) {
        sscanf(buffer, "%s %s", settings[i].name, settings[i].value);
        i++;
    }

    fclose(fp);
    return settings;
}

void saveConfig(char *filename, struct setting* settings) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        printf("Failed to open file\n");
        return;
    }

    for (int i = 0; settings[i].name[0] != '\0'; i++) {
        fprintf(fp, "%s %s\n", settings[i].name, settings[i].value);
    }

    fclose(fp);
}

void updateSetting(char *setting_name, char *new_value, struct setting* settings) {
    for (int i = 0; settings[i].name[0] != '\0'; i++) {
        if (strcmp(settings[i].name, setting_name) == 0) {
            strncpy(settings[i].value, new_value, sizeof(settings[i].value));
            break;
        }
    }
}

void displaySettings(struct setting* settings) {
    for (int i = 0; settings[i].name[0] != '\0'; i++) {
        printf("%s: %s\n", settings[i].name, settings[i].value);
    }
}

int main(int argc, char *argv[]) {
    struct setting* settings = malloc(sizeof(struct setting)*10); // Assuming a max of 10 settings for simplicity

    if (argc == 2 && strcmp(argv[1], "--help") == 0) {
        help();
    } else if (argc == 3 && strcmp(argv[1], "--load-config") == 0) {
        settings = loadConfig(argv[2]);
    } else if (argc == 4 && strcmp(argv[1], "--update-setting") == 0) {
        updateSetting(argv[2], argv[3], settings);
    } else if (argc == 3 && strcmp(argv[1], "--save-config") == 0) {
        saveConfig(argv[2], settings);
    }

    displaySettings(settings);
    free(settings);
    return 0;
}
