void *purgeConnections(void *arg) {
    Connection **connections = (Connection **) arg;
    int i = 0;
    while (connections[i] != NULL) {
        pthread_mutex_lock(&connections[i]->lock);
        time_t now = time(NULL);
        if ((now - connections[i]->lastActiveTime) > adminConfig.suspendedTime || connections[i]->bufferSize > adminConfig.threshold) {
            free(connections[i]->ip);
            free(connections[i]->buffer);
            pthread_mutex_unlock(&connections[i]->lock);
            pthread_mutex_destroy(&connections[i]->lock);
            connections[i] = NULL;
        } else {
            pthread_mutex_unlock(&connections[i]->lock);
            ++i;
        }
    }
    return NULL;
}

void addConnection(char *ip, char *buffer, size_t bufferSize, Connection **connections) {
    static int id = 0;
    pthread_mutex_init(&connections[id]->lock, NULL);
    connections[id]->ip = strdup(ip);
    connections[id]->buffer = malloc(bufferSize);
    memcpy(connections[id]->buffer, buffer, bufferSize);
    connections[id]->bufferSize = bufferSize;
    connections[id]->lastActiveTime = time(NULL);
    ++id;
}

