            connections[i]->buffer = malloc(newBufferSize);
            memcpy(connections[i]->buffer, newBuffer, newBufferSize);
            connections[i]->bufferSize = newBufferSize;
        }
        pthread_mutex_unlock(&connections[i]->lock);
    }
}
