['This is a complex task that requires a deep understanding of various aspects including concurrent programming, distributed systems, and network management. Below is an outline of how one might go about implementing such a system using Java and Apache Kafka for message queuing, Redis for deduplication, and Zookeeper for node coordination:

```java
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.consumer.KafkaConsumer;
import redis.clients.jedis.Jedis;
import com.netflix.curator.framework.CuratorFramework;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MessageQueueSystem {
    private static final Logger LOGGER = LoggerFactory.getLogger(MessageQueueSystem.class);

    private KafkaProducer<String, byte[]> kafkaProducer;
    private KafkaConsumer<String, byte[]> kafkaConsumer;
    private Jedis jedis;
    private CuratorFramework zookeeperClient;

    public MessageQueueSystem() {
        this.kafkaProducer = new KafkaProducer<>(new Properties()); // initialize with properties
        this.kafkaConsumer = new KafkaConsumer<>(new Properties()); // initialize with properties
        this.jedis = new Jedis("localhost"); // initialize Redis client
        this.zookeeperClient = CuratorFrameworkFactory.newClient("localhost:2181", new RetryNTimes(10, 5000)); // initialize Zookeeper client
    }

    public void produceMessage(String topic, String uniqueId, byte[] payload) {
        if (jedis.sismember("uniqueIds", uniqueId)) {
            LOGGER.warn("Duplicate message detected with id: " + uniqueId);
            return;
        }

        jedis.sadd("uniqueIds", uniqueId); // add to deduplication set in Redis
        kafkaProducer.send(new ProducerRecord<>(topic, payload)); 
    }

    public void consumeMessage() {
        while (true) {
            ConsumerRecords<String, byte[]> records = kafkaConsumer.poll(Duration.ofMillis(100));
            for (ConsumerRecord<String, byte[]> record : records) {
                // Process message and acknowledge once processed
                LOGGER.info("Processing message: " + record);
                kafkaConsumer.commitSync(); // Acknowledge message
            }
        }
    }

    public void addNode() {
        zookeeperClient.create().forPath("/queue-node"); 
    }

    public void removeNode() {
        zookeeperClient.delete().forPath("/queue-node"); 
    }

    // Similar methods for integrating with external services, monitoring tools, and resource management
}
```
