['Here is an example of how you might implement this in C. This code doesn't cover everything your specification asks for (like the periodic purging), but it should provide a good starting point. It uses linked lists for managing contexts, and serializes/deserializes them to/from a file using a simple text format:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char MAC[10];  // example of valid MAC entity
} LTE_RRC_UE_CONTEXT_T;

// Linked list node to store context data
struct Node {
    LTE_RRC_UE_CONTEXT_T *context;
    struct Node* next;
};

void serializeContext(FILE* file, LTE_RRC_UE_CONTEXT_T* context) {
    fprintf(file, "%s\n", context->MAC);  // example of how to serialize MAC
}

LTE_RRC_UE_CONTEXT_T* deserializeContext(FILE* file) {
    LTE_RRC_UE_CONTEXT_T *context = malloc(sizeof(LTE_RRC_UE_CONTEXT_T));
    if (fscanf(file, "%s\n", context->MAC) != 1) {  // example of how to deserialize MAC
        free(context);
        return NULL;
    }
    return context;
}

void serializeContextList(FILE* file, struct Node *node) {
    while (node != NULL) {
        serializeContext(file, node->context);
        node = node->next;
    }
}

struct Node* deserializeContextList(FILE* file) {
    struct Node *head = NULL;
    struct Node *tail = NULL;

    while (!feof(file)) {
        LTE_RRC_UE_CONTEXT_T* context = deserializeContext(file);
        if (context == NULL) break;  // error or end of file

        struct Node* newNode = malloc(sizeof(struct Node));
        newNode->context = context;
        newNode->next = NULL;

        if (head == NULL) {
            head = newNode;
        } else {
            tail->next = newNode;
        }
        tail = newNode;
    }

    return head;
}

void saveContextsToFile(const char* filename, struct Node *node) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) return;  // handle error here...

    serializeContextList(file, node);

    fclose(file);
}

struct Node* loadContextsFromFile(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return NULL;  // handle error here...

    struct Node* node = deserializeContextList(file);

    fclose(file);

    return node;
}
```
