void *allocateMemory(size_t size) {
    void *result = NULL;

    if (sem_trywait(&memorySemaphore) == 0) {
        pthread_mutex_lock(&allocationMutex);

        if ((totalAllocatedMemory + size) <= MAXIMUM_ALLOCATED_MEMORY) {
            result = malloc(size);

            if (result != NULL) {
                totalAllocatedMemory += size;
                successfullAllocationsCount++;
                lastAllocationTime = clock();
            } else {
                failedAllocationsCount++;
            }
        } else {
            failedAllocationsCount++;
        }

        pthread_mutex_unlock(&allocationMutex);
    }

    return result;
}

AudioStream *createStream(int samplingRate, int bitDepth, double duration) {
    AudioStream *stream = allocateMemory(sizeof(AudioStream));

    if (stream != NULL) {
        stream->samplingRate = samplingRate;
        stream->bitDepth = bitDepth;
        stream->duration = duration;

        /* Initialize other fields of the AudioStream */

        numOfStreams++;
    }

    return stream;
}

void releaseStream(AudioStream *stream) {
    if (stream != NULL) {
        pthread_mutex_lock(&allocationMutex);

        totalAllocatedMemory -= sizeof(AudioStream);
        numOfStreams--;

        pthread_mutex_unlock(&allocationMutex);

        free(stream);
    }
}

void releaseAllResources() {
    /* Release all streams and other resources */
}
```

