public class TransactionProcessor {
    private static final Set<String> SUPPORTED_CURRENCIES = new HashSet<>(Arrays.asList("USD", "EUR"));
    private static final LocalDate MIN_DATE = LocalDate.of(2015, 1, 1);
    private static final LocalDate MAX_DATE = LocalDate.now();

    public static Map<String, Object> processFinancialTransactions(List<TransactionRecord> records) throws Exception {
        List<Map<String, String>> results = new ArrayList<>();

        for (TransactionRecord record : records) {
            if (!isValidRecord(record)) {
                System.out.println("Invalid record: " + record);
                continue;
            }

            MessageDigest md = MessageDigest.getInstance("MD5");
            String hashInput = record.getCustomerId() + "," + record.getAmount() + "," + 
                    record.getCurrencyType() + "," + record.getTransactionDate();
            byte[] digest = md.digest(hashInput.getBytes());
            String hashOutput = DatatypeConverter.printHexBinary(digest);

            Map<String, String> result = new HashMap<>();
            result.put("customerId", record.getCustomerId());
            result.put("amount", String.valueOf(record.getAmount()));
            result.put("currencyType", record.getCurrencyType());
            result.put("transactionDate", record.getTransactionDate().toString());
            result.put("hash", hashOutput);

            results.add(result);
        }

        return summarizeResults(results);
    }

    private static boolean isValidRecord(TransactionRecord record) {
        if (StringUtils.isBlank(record.getCustomerId())) {
            return false;
        }

        if (record.getAmount() <= 0) {
            return false;
        }

        if (!SUPPORTED_CURRENCIES.contains(record.getCurrencyType())) {
            return false;
        }

        LocalDate transactionDate = record.getTransactionDate();
        if (transactionDate.isBefore(MIN_DATE) || transactionDate.isAfter(MAX_DATE)) {
            return false;
        }

        return true;
    }

