import threading
import logging

lock = threading.Lock() # Lock for thread-safe access
metrics = [] # List of metrics

def read_and_sort(filepath):
    global metrics

    lock.acquire()
    try:
        with open(filepath, 'r') as file:
            metrics = sorted([line.strip() for line in file])

        logging.info('Metrics sorted and loaded from {}'.format(filepath))

    except Exception as e:
        logging.error('Failed to read and sort metrics: {}'.format(str(e)))

    finally:
        lock.release()
