typedef struct {
    uint8_t RNTI;
    uint8_t RX_UE_INFORMATION_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Thread-safe function to generate a unique random number in the specified range.
uint8_t genRandom(pthread_mutex_t* mutex, uint8_t lower, uint8_t upper) {
    pthread_mutex_lock(mutex);
    uint8_t num = rand() % (upper - lower + 1) + lower;
    pthread_mutex_unlock(mutex);
    return num;
}

NFAPI_CRC_INDICATION_PDU_T* createListOfStructs(int N, uint8_t RNTI_lower, uint8_t RNTI_upper) {
    // Error checking and edge cases.
    if (N <= 0 || N > 256) { 
        printf("Error: Invalid input. Input must be between 1 and 256.\n");
        return NULL;
    }

    uint8_t RNTI[256] = { [0 ... 255] = 0 }; // Initialize an array to track used RNTIs.

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(*list));

    if (list == NULL) {
        printf("Error: Failed to allocate memory.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // For thread safety.

    for(int i = 0; i < N; ++i) {
        uint8_t rnti;

        do {
            rnti = genRandom(&mutex, RNTI_lower, RNTI_upper);
        } while (RNTI[rnti] != 0); // Ensure uniqueness.

        RNTI[rnti] = 1;

        list[i].RX_UE_INFORMATION_TAG = rnti;
        list[i].RNTI = genRandom(&mutex, RNTI_lower, RNTI_upper);
    }

    return list;
}
``` 

