    public Map<String, Object> processAndOptimizeCustomerFeedback(List<Map<String, String>> feedbackRecords, File jsonConfigFile, Map<String, String> request) throws Exception {
        String configContent;
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(Files.newInputStream(jsonConfigFile.toPath())))) {
            configContent = reader.lines().reduce("", (a, b) -> a + b);
        }

        Map<String, String> settings = gson.fromJson(configContent, new TypeToken<Map<String, String>>(){}.getType());
        SettingsValidator validator = new SettingsValidator();
        if(!validator.validateSettingsForReadHeavyOperations(settings)) {
            throw new Exception("Invalid database configuration for read-heavy operations.");
        }

        List<String> invalidRecords = new ArrayList<>();
        Map<String, String> hashes = new HashMap<>();
        for (Map<String, String> record : feedbackRecords) {
            if (!validateRecord(record)) {
                invalidRecords.add(gson.toJson(record));
            } else {
                MessageDigest md = MessageDigest.getInstance("MD5");
                String concatenatedData = record.getOrDefault("customerID", "") + ", " + 
                                         record.getOrDefault("feedbackText", "") + ", " +
                                         record.getOrDefault("rating", "") + ", " +
                                         record.getOrDefault("timestamp", "");
                hashes.put(record.getOrDefault("customerID", ""), bytesToHex(md.digest(concatenatedData.getBytes())));
            }
        }

        logInvalidRecords(invalidRecords);

        if (feedbackRecords.size() > 500) {
            processInParallel(feedbackRecords, settings);
        } else {
            processSequentially(feedbackRecords, settings);
        }

        Map<String, Object> result = new HashMap<>();
        result.put("hashes", hashes);

        String action = request.getOrDefault("action", "");
        if ("archive".equalsIgnoreCase(action)) {
            archiveFeedback(request.get("customerID"));
        } else if (request.containsKey("customerID")) {
            updateCustomerDetails(request);
        }

        String updatedConfigContent = optimizeSettingsForReadHeavyOperations(settings);
        Files.writeString(jsonConfigFile.toPath(), updatedConfigContent, StandardOpenOption.CREATE);

        return result;
    }

    private boolean validateRecord(Map<String, String> record) {
