        sqlite3_close(db);

        return 1;
    }

    // execute a query
    char *sql = "SELECT * FROM table";

    rc = sqlite3_exec(db, sql, NULL, 0, &err_msg);

    if (rc != SQLITE_OK ){

        fprintf(stderr, "SQL error: %s\n", err_msg);
        sqlite3_free(err_msg);        
        sqlite3_close(db);

        return 1;
    } 

    printf("Operation done successfully\n");

    sqlite3_close(db);

    return 0;
}
```
