// Structure for context management
typedef struct {
  char* MAC;
  unsigned C_RNTI;
  void* SIBs;
  char* IP;
} LTE_RRC_UE_CONTEXT_T;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
LTE_RRC_UE_CONTEXT_T* contexts[10000]; // Array for context management
unsigned int current_contexts = 0; // Counter for number of contexts

// Add a new context to the array, checking for duplicates and updating existing contexts as necessary.
void addContext(LTE_RRC_UE_CONTEXT_T* newContext) {
  pthread_mutex_lock(&lock);

  // Check if we have reached maximum contexts limit
  if (current_contexts >= 10000) {
    log_message("Maximum number of contexts reached!\n");
    return;
  }

  // Check for duplicate MAC addresses
  for(int i = 0; i < current_contexts; ++i) {
      if (strcmp(newContext->MAC, contexts[i]->MAC) == 0) {
          log_message("Attempted to add a duplicate context with MAC %s\n", newContext->MAC);
          return;
      }
  }

  // Add the new context to the array
  contexts[current_contexts++] = newContext;

  log_message("Added context for MAC: %s\n", newContext->MAC);

  pthread_mutex_unlock(&lock);
}

// Update an existing context, checking if it exists and updating as necessary.
void updateContext(LTE_RRC_UE_CONTEXT_T* updatedContext) {
  pthread_mutex_lock(&lock);

  // Find the context to update
  for(int i = 0; i < current_contexts; ++i) {
      if (strcmp(updatedContext->MAC, contexts[i]->MAC) == 0) {
          free(contexts[i]->SIBs); // Free old SIBs buffer before updating

          // Update the context with new values
          contexts[i] = updatedContext;

          log_message("Updated context for MAC: %s\n", updatedContext->MAC);
          return;
      }
  }

  log_message("Attempted to update a non-existent context with MAC: %s\n", updatedContext->MAC);

  pthread_mutex_unlock(&lock);
}

// Delete an existing context, checking if it exists and deleting as necessary.
void deleteContext(char* MAC) {
  pthread_mutex_lock(&lock);

  // Find the context to delete
  for(int i = 0; i < current_contexts; ++i) {
      if (strcmp(MAC, contexts[i]->MAC) == 0) {
          free(contexts[i]->SIBs); // Free SIBs buffer before deleting

          // Shift all remaining contexts left to fill the gap
          for(int j = i; j < current_contexts - 1; ++j) {
              contexts[j] = contexts[j + 1];
          }

          --current_contexts;

          log_message("Deleted context for MAC: %s\n", MAC);
          return;
      }
  }

  log_message("Attempted to delete a non-existent context with MAC: %s\n", MAC);

  pthread_mutex_unlock(&lock);
}
```
