    public void handleUserAccountChangesWithTransactionProcessing(List<Map<String, Object>> transactions, File jsonFile, Map<String, String> request) throws Exception {
        long start = System.nanoTime();

        JSONParser parser = new JSONParser();
        Object obj = parser.parse(new FileReader(jsonFile));
        JSONObject jsonObj = (JSONObject) obj;

        if (!isValidJson(jsonObj)) {
            logError("Invalid JSON file");
            throw new Exception("Invalid JSON file");
        }

        String pokemonType = (String) jsonObj.get("type");
        String saltedHashPassword = getSaltedHash((String) jsonObj.get("password"), pokemonType);

        ExecutorService executorService = Executors.newFixedThreadPool(5); // adjust the pool size according to your requirements
        for (int i = 0; i < transactions.size(); i += BATCH_SIZE) {
            final int startIndex = i;
            final int endIndex = Math.min(i + BATCH_SIZE, transactions.size());

            executorService.execute(() -> processBatch(transactions.subList(startIndex, endIndex), request, saltedHashPassword));
        }

        // shutdown the ExecutorService
        executorService.shutdown();
        while (!executorService.isTerminated()) { }

        logInfo("Processing time: " + (System.nanoTime() - start) / 1e6);
    }

    private void processBatch(List<Map<String, Object>> batch, Map<String, String> request, String saltedHashPassword) {
        long start = System.nanoTime();

        List<String> validRecords = new ArrayList<>();
        double totalAmount = 0;

        for (Map<String, Object> record : batch) {
            if (!isValidRecord(record)) continue;

            String recordStr = getConcatenatedRecord(record);
            byte[] hashBytes = computeHash(recordStr.getBytes(StandardCharsets.UTF_8));
            validRecords.add(new String(hashBytes, StandardCharsets.UTF_8));
            totalAmount += (Double) record.get("amount");
        }

        logInfo("Batch processing time: " + (System.nanoTime() - start) / 1e6);

        if (!validRecords.isEmpty()) {
            double avgAmount = totalAmount / validRecords.size();

            String batchId = computeHash(String.join("", validRecords).getBytes(StandardCharsets.UTF_8));
            updateUserAccountBatch(batchId, avgAmount, saltedHashPassword);
        }
    }

    private boolean isValidJson(JSONObject jsonObj) {
        // validate the JSON file as per your requirement
        return true;
    }

    private String getSaltedHash(String password, String salt) throws NoSuchAlgorithmException, InvalidKeyException {
        SecretKeySpec secretKey = new SecretKeySpec(salt.getBytes(), HMAC_SHA256);
        Mac mac = Mac.getInstance(HMAC_SHA256);
        mac.init(secretKey);

        return bytesToHex(mac.doFinal(password.getBytes()));
    }

    private byte[] computeHash(byte[] input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        return md.digest(input);
    }

    private boolean isValidRecord(Map<String, Object> record) {
        // validate the transaction record as per your requirement
        String id = (String) record.get("id");
        Double amount = (Double) record.get("amount");
        String currencyType = (String) record.get("currency_type");
        LocalDate date = LocalDate.parse((CharSequence) record.get("date")); // assuming the date format is YYYY-MM-DD

        return id != null && amount > 0 && SUPPORTED_CURRENCIES.contains(currencyType) && date.isAfter(LocalDate.now().minusDays(365));
    }

    private String getConcatenatedRecord(Map<String, Object> record) {
        return String.format("%s,%f,%s,%s", record.get("id"), record.get("amount"), record.get("currency_type"), record.get("date"));
    }

