['Below is a high level implementation of your task using Java. Please note that this code will need further adjustment according to the specifics of your environment (e.g., you might want to use other libraries for date parsing, cryptographic hashing, etc.), as well as it does not cover all possible edge cases which should be handled in a real-world application.

```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.LocalDate;
import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.validator.routines.CurrencyValidator;
import com.google.common.hash.Hashing;

public class TransactionProcessor {
    private static final String[] SUPPORTED_CURRENCIES = {"USD", "EUR"};
    private static final int MAX_BATCH_SIZE = 500;
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public static Map<String, String> processFinancialTransactions(List<TransactionRecord> transactions) {
        List<Future<?>> futures = new ArrayList<>();
        ConcurrentMap<String, String> hashes = new ConcurrentHashMap<>();

        for (int i = 0; i < transactions.size(); i += MAX_BATCH_SIZE) {
            int end = Math.min(i + MAX_BATCH_SIZE, transactions.size());
            List<TransactionRecord> batch = new ArrayList<>(transactions.subList(i, end));

            Future<?> future = executor.submit(() -> processBatch(batch, hashes));
            futures.add(future);
        }

        for (Future<?> future : futures) {
            try {
                future.get(); // Wait until all tasks are completed
            } catch (InterruptedException | ExecutionException e) {
                Thread.currentThread().interrupt();
                throw new RuntimeException(e);
            }
        }

        return hashes;
    }

    private static void processBatch(List<TransactionRecord> batch, ConcurrentMap<String, String> hashes) {
        for (TransactionRecord record : batch) {
            if (!isValidRecord(record)) {
                continue; // Skip invalid records
            }

            try {
                String concat = concatenateFields(record);
                String hash = computeMd5Hash(concat);

                hashes.put(hash, record.getCustomerId());
            } catch (NoSuchAlgorithmException e) {
                System.err.println("Failed to process transaction: " + e.getMessage());
            }
        }
    }

    private static boolean isValidRecord(TransactionRecord record) {
        String customerId = record.getCustomerId();
        double amount = record.getAmount();
        String currency = record.getCurrency();
        LocalDate date = record.getDate();

        if (customerId == null || customerId.isEmpty()) {
            System.out.println("Invalid customer ID: " + customerId);
            return false;
        }

        if (amount <= 0) {
            System.out.println("Invalid amount: " + amount);
            return false;
        }

        if (!Arrays.asList(SUPPORTED_CURRENCIES).contains(currency)) {
            System.out.println("Unsupported currency: " + currency);
            return false;
        }

        // Implement date validation here as per your requirement

        return true;
    }

    private static String concatenateFields(TransactionRecord record) {
        return record.getCustomerId() + ',' + record.getAmount() + ',' + record.getCurrency() + ',' + record.getDate();
    }

    private static String computeMd5Hash(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));

        return Hashing.md5().hashString(new String(digest), StandardCharsets.UTF_8).toString();
    }
}
```
The `TransactionRecord` class is not defined in this code snippet, but it should have the required fields and getter methods. Please implement it according to your needs. 

