    if (pthread_create(&ipThread, NULL, validateIP, (void*)IP)) {
        printf("Failed to create thread\n");
        return;
    }
    pthread_join(ipThread, NULL);  // wait for the IP validation to finish

    // Check if memory usage is below threshold before adding a new context
    double memUsage = (double)nextFreeIndex / maxContexts;
    if (memUsage >= memUsageThreshold && arraySize < maxContexts) {
        printf("Memory limit reached. Couldn't add new context\n");
        return;
    } else if (arraySize >= maxContexts) {
        // If memory cap is reached, purge contexts to free up space
        for (int i = 0; i < arraySize; i++) {
            if (contextArray[i] == NULL) {  // context marked as unused
                free(contextArray[i]->buffer);
                free(contextArray[i]);
                contextArray[i] = NULL;
            } else {
                nextFreeIndex = i + 1;
            }
        }
    }

    LTE_RRC_UE_CONTEXT_T* newContext = allocContext();
    // Fill the new context with data
    newContext->MAC = MAC;
    newContext->C_RNTI = C_RNTI;
    newContext->IP = IP;

    if (nextFreeIndex < arraySize) {  // reuse previously allocated memory
        contextArray[nextFreeIndex] = newContext;
    } else {  // allocate a new slot in the array
        contextArray = realloc(contextArray, sizeof(LTE_RRC_UE_CONTEXT_T*) * (arraySize + 1));
        contextArray[arraySize++] = newContext;
        nextFreeIndex = arraySize;
    }

    if (loggingEnabled) {  // log the addition of a new context
        printf("Added new context with MAC: %d, C_RNTI: %d, IP: %s\n", MAC, C_RNTI, IP);
