    public void processUserActivitiesWithTaskDetails(List<UserActivity> activities, Path yamlConfigPath) throws Exception {

        Yaml yaml = new Yaml();
        Map<String, Object> config = yaml.load(Files.newInputStream(yamlConfigPath));

