            int end = Math.min(i + 1000, activities.size());

            List<UserActivity> batchActivities = activities.subList(i, end);

            Future<String> futureBatchHash = executorService.submit(() -> { 
                return processBatchAndGetSHA256(batchActivities, config);
            });
        }

