    }

    private String processBatchAndGetSHA256(List<UserActivity> activities, Map<String, Object> config) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");

        for (UserActivity activity : activities) {
            if (!isValidActivity(activity)) {
                System.out.println("Invalid user activity record found, skipping...");
                continue;
            }

            StringBuilder sb = new StringBuilder();
            sb.append(activity.getUserId());
            sb.append(",");
            sb.append(activity.getActivityTimestamp().toString());
            sb.append(",");
            sb.append(activity.getType());
            // Append other fields similarly

            byte[] hash = digest.digest(sb.toString().getBytes("UTF-8"));
            String encodedHash = Base64.getEncoder().encodeToString(hash);
        }

        return encodedHash;
    }

    private boolean isValidActivity(UserActivity activity) {
        // Validate user ID, timestamp format and type here
        if (activity.getUserId() == null || activity.getUserId().trim().isEmpty()) {
            return false;
        } else if (!Arrays.asList(SUPPORTED_TYPES).contains(activity.getType())) {
            return false;
        }

        // Add other validation checks here

        return true;
    }

    private void updateYamlConfigFile(Map<String, Object> config, Path yamlConfigPath) throws Exception {
        Yaml yaml = new Yaml();

        Files.write(yamlConfigPath, Collections.singletonList(yaml.dumpAsMap(config)), StandardOpenOption.WRITE); // Update the file
    }
