void destroy_dynamic_array(DynamicArray* arr) {
    for (size_t i = 0; i < arr->size; ++i) {
        free(arr->array[i]); // Assuming LTEPHY_RxPdu is allocated separately, free memory here.
    }

    pthread_mutex_destroy(&arr->lock);
    free(arr->array);
    free(arr);
}

void append_dynamic_array(DynamicArray* arr, LTEPHY_RxPdu* item) {
    pthread_mutex_lock(&arr->lock);

    if (arr->size >= arr->capacity) {
        // Grow the array when it is full. You might want to adjust this based on your use case.
        arr->capacity *= 2; 
        LTEPHY_RxPdu** newArray = realloc(arr->array, arr->capacity * sizeof(LTEPHY_RxPdu*));

        if (newArray == NULL) {
            pthread_mutex_unlock(&arr->lock);
            return;
        }

        arr->array = newArray;
    }

    arr->array[arr->size++] = item;

    pthread_mutex_unlock(&arr->lock);
}
