#include <pthread.h>
#include <time.h>
#include <stdio.h>
#define MAX_SESSIONS 1024
#define INACTIVITY_THRESHOLD 3600 //in seconds

typedef struct Session{
    int userID;
    time_t startTime;
    time_t lastActive;
}Session;

typedef struct SessionManager{
    pthread_mutex_t lock;
    Session sessions[MAX_SESSIONS];
}SessionManager;

void initialize(SessionManager *manager){
    pthread_mutex_init(&(manager->lock), NULL);
}

int createSession(SessionManager *manager, int userID){
    pthread_mutex_lock(&(manager->lock));
    for(int i=0;i<MAX_SESSIONS;++i) {
        if (manager->sessions[i].userID == -1) {
            manager->sessions[i].userID = userID;
            time(&(manager->sessions[i].startTime));
            manager->sessions[i].lastActive = manager->sessions[i].startTime;
            pthread_mutex_unlock(&(manager->lock));
            printf("Session created for user %d\n", userID);
            return 0;
        } else if (manager->sessions[i].userID == userID) {
            pthread_mutex_unlock(&(manager->lock));
            printf("User already has a session\n");
            return -1;
        }
    }
    pthread_mutex_unlock(&(manager->lock));
    printf("Max sessions reached\n");
    return -2;
}

void updateSession(SessionManager *manager, int userID){
    pthread_mutex_lock(&(manager->lock));
    for(int i=0;i<MAX_SESSIONS;++i) {
        if (manager->sessions[i].userID == userID) {
            time(&(manager->sessions[i].lastActive));
            printf("Session updated for user %d\n", userID);
            break;
        }
    }
    pthread_mutex_unlock(&(manager->lock));
}

void terminateSession(SessionManager *manager, int userID){
    pthread_mutex_lock(&(manager->lock));
    for(int i=0;i<MAX_SESSIONS;++i) {
        if (manager->sessions[i].userID == userID) {
            manager->sessions[i].userID = -1;
            printf("Session terminated for user %d\n", userID);
            break;
        }
    }
    pthread_mutex_unlock(&(manager->lock));
}

void purgeSessions(SessionManager *manager){
    time_t currentTime, inactivityThreshold = time(NULL) - INACTIVITY_THRESHOLD;
    pthread_mutex_lock(&(manager->lock));
    for(int i=0;i<MAX_SESSIONS;++i) {
        if (manager->sessions[i].userID != -1 && manager->sessions[i].lastActive < inactivityThreshold){
            printf("Session purged for user %d\n", manager->sessions[i].userID);
            manager->sessions[i].userID = -1;
        }
    }
    pthread_mutex_unlock(&(manager->lock));
}
