int add(dynamic_nic_array *arr, nic_config *new_nic) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->count >= MAX_NIC) {
        return -1; // Array is full
    }
    arr->array[arr->count++] = new_nic;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}

int remove(dynamic_nic_array *arr, int index) {
    pthread_mutex_lock(&arr->mutex);
    if (index < 0 || index >= arr->count) {
        return -1; // Invalid index
    }
    free(arr->array[index]);
    for (int i = index; i < arr->count - 1; ++i) {
        arr->array[i] = arr->array[i + 1];
    }
    --arr->count;
    pthread_mutex_unlock(&arr->mutex);
    return 0;
}
