typedef struct nfapi_crc_indication_pdu {
    int RNTI;
    //...other fields...
} NFAPI_CRC_INDICATION_PDU_T;

struct hash_entry {
    int key;
    NFAPI_CRC_INDICATION_PDU_T *value;
    struct hash_entry *next;
};

typedef struct {
    pthread_mutex_t mutex;
    struct hash_entry **table;
    int tableSize;
} HashTable;

HashTable *createHashTable(int size) {
    HashTable *ht = malloc(sizeof(HashTable));
    ht->table = calloc(size, sizeof(struct hash_entry*));
    ht->tableSize = size;
    pthread_mutex_init(&ht->mutex, NULL);
    return ht;
}

int simpleHashFunction(int key, int tableSize) {
    return abs(key % tableSize); // use a more complex hash function in real world usage
}

void insertEntry(HashTable *ht, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&ht->mutex);
    int index = simpleHashFunction(pdu->RNTI, ht->tableSize);
    struct hash_entry *newEntry = malloc(sizeof(struct hash_entry));
    newEntry->key = pdu->RNTI;
    newEntry->value = pdu;
    newEntry->next = ht->table[index];
    ht->table[index] = newEntry;
    pthread_mutex_unlock(&ht->mutex);
}

NFAPI_CRC_INDICATION_PDU_T *findEntry(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->mutex);
    int index = simpleHashFunction(key, ht->tableSize);
    struct hash_entry *currentEntry = ht->table[index];
    while (currentEntry != NULL && currentEntry->key != key) {
        currentEntry = currentEntry->next;
    }
    pthread_mutex_unlock(&ht->mutex);
    return (currentEntry == NULL) ? NULL : currentEntry->value;
}

void deleteEntry(HashTable *ht, int key) {
    pthread_mutex_lock(&ht->mutex);
    int index = simpleHashFunction(key, ht->tableSize);
    struct hash_entry **currentLink = &(ht->table[index]);
    while (*currentLink != NULL && (*currentLink)->key != key) {
        currentLink = &((*currentLink)->next);
    }
    if(*currentLink != NULL){
        struct hash_entry *toDelete = *currentLink;
        *currentLink = toDelete->next;
        free(toDelete->value);
        free(toDelete);
    }
    pthread_mutex_unlock(&ht->mutex);
}
```
This code represents a basic hash table data structure that uses linked lists for handling collisions. It provides insertion, finding and deletion operations. Also it uses mutex for thread safety. Please modify as per your needs.
