#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char *client_ip;
    void *buffer;
    size_t buffer_size;
    time_t timestamp;
} tcp_conn_t;

typedef struct {
    pthread_mutex_t lock;
    tcp_conn_t **connections;
    int connection_count;
} conn_manager_t;

int add_connection(conn_manager_t *mgr, const char *ip) {
    tcp_conn_t *new_conn = malloc(sizeof(tcp_conn_t));
    new_conn->client_ip = strdup(ip);
    new_conn->buffer = NULL;
    new_conn->buffer_size = 0;
    new_conn->timestamp = time(NULL);

    pthread_mutex_lock(&mgr->lock);
    mgr->connections[mgr->connection_count++] = new_conn;
    pthread_mutex_unlock(&mgr->lock);

    return mgr->connection_count - 1; // Return the index of the added connection.
}

void update_buffer(tcp_conn_t *conn, void *new_data, size_t new_size) {
    if (conn->buffer != NULL) {
        free(conn->buffer);
    }

    conn->buffer = malloc(new_size);
    memcpy(conn->buffer, new_data, new_size);
    conn->buffer_size = new_size;
}

void update_connection(conn_manager_t *mgr, int idx, void *new_data, size_t new_size) {
    pthread_mutex_lock(&mgr->lock);

    tcp_conn_t *conn = mgr->connections[idx];
    update_buffer(conn, new_data, new_size);
    conn->timestamp = time(NULL);

    pthread_mutex_unlock(&mgr->lock);
}

void remove_connection(conn_manager_t *mgr, int idx) {
    pthread_mutex_lock(&mgr->lock);

    tcp_conn_t *conn = mgr->connections[idx];
    free(conn->client_ip);
    if (conn->buffer != NULL) {
        free(conn->buffer);
    }
    free(conn);

    // Move the last connection to the removed index, then decrease the count.
    mgr->connections[idx] = mgr->connections[--mgr->connection_count];

    pthread_mutex_unlock(&mgr->lock);
}
```
