    if (action == 'A') {  // Adding a context
        if (active_contexts < max_contexts) {
            contexts[active_contexts++] = context;
        } else {
            printf("Error: Maximum number of contexts reached\n");
        }
    } else if (action == 'D') {  // Deleting a context
        for (int i = 0; i < active_contexts; i++) {
            if (contexts[i] == context) {
                free(context);  // Free the memory
                contexts[i] = contexts[--active_contexts];  // Shift remaining elements down
                break;
            }
        }
    } else if (action == 'U') {  // Updating a context
        for (int i = 0; i < active_contexts; i++) {
            if (contexts[i] == context) {
                contexts[i] = context;  // Replace the old context with the new one
                break;
            }
        }
    } else {
        printf("Error: Invalid action\n");
    }

    // Release the lock
