<?php
function updateClinicStatuses(PDO $pdo, array $clinics) {
    try {
        $pdo->beginTransaction();

        // Assuming clinic data is an associative array with 'id', 'status', and 'ip' keys.
        foreach ($clinics as $clinic) {
            $stmt = $pdo->prepare('SELECT COUNT(*) FROM clinics WHERE id = :id');
            $stmt->execute([':id' => $clinic['id']]);
            if ($stmt->fetchColumn() == 0) {
                throw new Exception("Clinic ID '{$clinic['id']}' does not exist.");
            }

            // Get the current clinic data.
            $getStmt = $pdo->prepare('SELECT * FROM clinics WHERE id = :id FOR UPDATE');
            $getStmt->execute([':id' => $clinic['id']]);
            $currentData = $getStmt->fetch(PDO::FETCH_ASSOC);

            // Update only necessary fields.
            $updateFields = ['status', 'last_modified_ip', 'last_modified_date'];
            foreach ($updateFields as $field) {
                if (isset($clinic[$field]) && $currentData[$field] != $clinic[$field]) {
                    $pdo->prepare("UPDATE clinics SET `{$field}` = :value WHERE id = :id")
                        ->execute([':value' => $clinic[$field], ':id' => $clinic['id']]);
                }
            }

            // Call the external API.
            callExternalApi($currentData, $clinic);
        }

        $pdo->commit();
    } catch (Exception $e) {
        error_log("Error updating clinics: " . $e->getMessage());
        $pdo->rollBack();
    }
}
?>
```
