LTE_RRC_UE_CONTEXT_T** contexts = NULL;
size_t numContexts = 0;
pthread_mutex_t contextMutex = PTHREAD_MUTEX_INITIALIZER;
time_t lastPurgeTime = 0;

// Function to add a new context
void addContext(LTE_RRC_UE_CONTEXT_T* ctx) {
    pthread_mutex_lock(&contextMutex);
    numContexts++;
    contexts = realloc(contexts, numContexts * sizeof(*contexts));
    contexts[numContexts - 1] = ctx;
    pthread_mutex_unlock(&contextMutex);
}

// Function to update an existing context
void updateContext(LTE_RRC_UE_CONTEXT_T* oldCtx, LTE_RRC_UE_CONTEXT_T* newCtx) {
    pthread_mutex_lock(&contextMutex);
    for (size_t i = 0; i < numContexts; ++i) {
        if (contexts[i] == oldCtx) {
            contexts[i] = newCtx;
            break;
        }
    }
    pthread_mutex_unlock(&contextMutex);
}

// Function to purge unused contexts periodically
void periodicPurge(time_t purgeInterval, time_t inactiveThreshold) {
    time_t now = time(NULL);

    if (now - lastPurgeTime >= purgeInterval) {
        pthread_mutex_lock(&contextMutex);

        for (size_t i = 0; i < numContexts; ++i) {
            // Check context's inactive time against threshold
            if (now - contexts[i]->lastActivityTime >= inactiveThreshold) {
                free(contexts[i]);  // Free the memory associated with this context

                // Shift remaining elements to fill the gap and decrease numContexts
                for (; i < numContexts - 1; ++i) {
                    contexts[i] = contexts[i + 1];
                }
                numContexts--;
            }
        }

        pthread_mutex_unlock(&contextMutex);
    }
}
```

This code is for a high-level overview and might need modifications based on specific requirements. For instance, in real-world scenario, context purging should be offloaded to an idle thread or separate process to avoid blocking other critical tasks. Also, the actual memory freeing operation may not be as simple as just `free()` depending on your system architecture.
