bool isValidIpAddress(char *ipAddress) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ipAddress, &(sa.sin_addr)) != 0;
}

// Function to add a new context
void addContext(LTE_RRC_UE_CONTEXT_T *context) {
    if (!isValidIpAddress(context->ip)) {
        printf("Invalid IP address\n");
        return;
    }

    pthread_mutex_lock(&contextLock);

    // Check for maximum context limit
    if (contextCount >= 10000) {
        printf("Maximum contexts reached\n");
        pthread_mutex_unlock(&contextLock);
        return;
    }

    // Find the next available slot and add the context
    for(int i = 0; i < 10000; ++i) {
       if (contextArray[i] == NULL) {
            contextArray[i] = context;
            ++contextCount;
            break;
        }
    }

    pthread_mutex_unlock(&contextLock);
}
