void addNewCell(LTE_RRC_CELL_T *newCell, LTE_RRC_CELL_T **cellArray) {
    pthread_mutex_lock(&lock);

    if (currentSize >= maxSize) {
        /* Adjust the size of cellArray dynamically */
        maxSize = maxSize + 5000;
        cellArray = realloc(cellArray, maxSize * sizeof(LTE_RRC_CELL_T*));
