    for (int i = 0; i < currentSize; i++) {
        if (!cellArray[i]->isUsed) { /* assuming that there's a flag to check cell usage */
            free(cellArray[i]->macEntity);
            free(cellArray[i]->SIBBuffer);
            free(cellArray[i]);

            for (int j = i; j < currentSize - 1; j++) {
                cellArray[j] = cellArray[j + 1];
            }

            --currentSize;
        }
    }

    pthread_mutex_unlock(&lock);
}

