typedef struct NFAPI_CRC_INDICATION_PDU {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int generateUniqueRNTI(void) {
