    return __sync_fetch_and_add(&nextRNTI, 1);
}

NFAPI_CRC_INDICATION_PDU_T* createListOfStructures(int N, void (*reportError)(const char*)) {
    pthread_mutex_lock(&lock);

    if (N <= 0) {
        reportError("Cannot generate less than one structure");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * N);
    if (list == NULL) {
        reportError("Memory allocation failed");
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        list[i].RNTI = generateUniqueRNTI();
    }

    pthread_mutex_unlock(&lock);

    return list;
}
