#include <iostream>
#include <map>
#include <string>
#include <memory>
#include <ctime>

class NetworkDeviceConfig {
public:
    // For simplicity, assume all parameters are ints and buffer is just a char array.
    // In real code you would likely use more complex types.
    using Params = std::map<std::string, int>;
    using Buffer = std::unique_ptr<char[]>;

    NetworkDeviceConfig(const std::string& id, const Params& params) : 
        mId{id}, mParams{params} { }

    void setBufferSize(size_t size) {
        if (mBuffer && sizeof(mBuffer.get()) == size) return;
        mBuffer = std::make_unique<char[]>(size);
        lastAccessTime = time(nullptr);
    }

    const Params& getParams() const { 
        lastAccessTime = time(nullptr);
        return mParams; 
    }

    void setParam(const std::string& param, int value) {
        mParams[param] = value;
        lastAccessTime = time(nullptr);
    }

private:
    const std::string mId; // Unique identifier for the configuration.
    Params mParams;       // Set of configurable parameters.
    Buffer mBuffer;       // Dynamically allocated buffer for network statistics.
    std::time_t lastAccessTime; // Last time this config was accessed.
};

class NetworkDeviceManager {
public:
    ~NetworkDeviceManager() = default;

    void addConfig(const NetworkDeviceConfig& config) { 
        mConfigs[config.getId()] = config;
    }

    // This is an example of error handling for updating a configuration.
    bool updateConfig(const std::string& id, const NetworkDeviceConfig::Params& params) {
        auto it = mConfigs.find(id);
        if (it == mConfigs.end()) return false;
        try {
            it->second.setParams(params);
        } catch (const std::exception& e) {
            std::cerr << "Error updating configuration: " << e.what() << '\n';
            return false;
        }
        return true;
    }

private:
    // Store configurations in a map for efficient lookup by unique identifier.
    std::map<std::string, NetworkDeviceConfig> mConfigs; 
};
```
This implementation creates two classes. The first class `NetworkDeviceConfig` represents an individual network device configuration and manages the set of configurable parameters and a dynamically allocated buffer for network statistics. The second class `NetworkDeviceManager` manages these configurations in a map for efficient lookup by unique identifier. In this code, all operations that can potentially throw exceptions are wrapped in try-catch blocks to provide robust error handling.
