void insert(int RNTI, RX_UE_INFORMATION_TAG* rx_ue_info, CRC_INDICATION_REL8_TAG* crc_ind_rel8) {
    pthread_mutex_lock(&lock);

    NFAPI_CRC_INDICATION_PDU_T* newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (newNode == NULL) {
