["Here's a basic implementation of such functionality in C using pthread mutexes for thread safety. Please note that this is a simplified version and doesn't handle all edge cases.

```c
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int crcErrors = 0;

void addElement(int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&lock);

    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&lock);
        return;
    }

    newNode->data.RNTI = RNTI;
    newNode->data.CRCFLAG = CRCFLAG;
    newNode->next = head;
    head = newNode;

    if (CRCFLAG != 0) {
        crcErrors++;
    }

    pthread_mutex_unlock(&lock);
}

void removeByRNTI(int RNTI) {
    pthread_mutex_lock(&lock);

    Node** indirect = &head;
    while (*indirect != NULL) {
        if ((*indirect)->data.RNTI == RNTI) {
            Node* nextNode = (*indirect)->next;

            if ((*indirect)->data.CRCFLAG != 0) {
                crcErrors--;
            }

            free(*indirect);
            *indirect = nextNode;
        } else {
            indirect = &((*indirect)->next);
        }
    }

    pthread_mutex_unlock(&lock);
}

void updateCRCFLAG(int RNTI, int newCRCFLAG) {
    pthread_mutex_lock(&lock);

    Node* current = head;
    while (current != NULL) {
        if (current->data.RNTI == RNTI) {
            if (current->data.CRCFLAG != 0 && newCRCFLAG == 0) {
                crcErrors--;
            } else if (current->data.CRCFLAG == 0 && newCRCFLAG != 0) {
                crcErrors++;
            }

            current->data.CRCFLAG = newCRCFLAG;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&lock);
}
``` 
Please make sure to handle any errors that might occur while allocating memory for a new node, updating the CRCFLAG when removing a node, or handling other edge cases. Also note that this code doesn't free any allocated memory after removing elements because it's unclear what kind of resource management strategy you would want to use (for example, should all nodes be freed upon program termination?).
