```cpp
#include <unordered_map>
#include <chrono>
#include <mutex>
#include <vector>
#include <memory>
#include <iostream>
#include <thread>

class Session { 
    // Assume there is a session class with necessary functions.
};

struct NetworkEntityContext {
    int networkID;
    std::shared_ptr<Session> session;
    std::vector<std::string> services;
    std::chrono::time_point<std::chrono::system_clock> lastUsedTime;
};

class NetworkEntityContextManager {
public:
    void addOrUpdate(int networkID, const std::shared_ptr<Session> &session, const std::vector<std::string> &services) {
        std::lock_guard<std::mutex> lock(mMutex);
        NetworkEntityContext context;
        context.networkID = networkID;
        context.session = session;
        context.services = services;
        context.lastUsedTime = std::chrono::system_clock::now();
        mEntities[networkID] = context;
    }

    void purgeInactiveContexts(const int duration) {
        auto now = std::chrono::system_clock::now();
        for (auto it = mEntities.cbegin(); it != mEntities.cend() /* not safe to increase iterator in range-based loop */; ){
            if ((now - it->second.lastUsedTime) > std::chrono::seconds(duration)) {
                std::lock_guard<std::mutex> lock(mMutex);  // Lock for thread safety
                mEntities.erase(it++);    // Increment iterator before erasing the element it points to
            } else {
                ++it;
            }
        }
    }

private:
    std::unordered_map<int, NetworkEntityContext> mEntities;
    mutable std::mutex mMutex;  // Mutex for thread safety
};
```
This `NetworkEntityContextManager` class uses an `std::unordered_map` to efficiently store and manage the contexts. It provides methods to add or update contexts, and a method to purge inactive contexts that have not been used for more than a specified duration. Note that this is a simple example and does not include error handling for concurrent access and logging of operations for auditing purposes which would require a more complex design considering the requirements.
