typedef struct AudioStream {
    int sampling_rate;
    int bit_depth;
    double duration;
} AudioStream;

typedef struct AllocatedStreams {
    AudioStream **streams;
    size_t count;
    pthread_mutex_t lock;
} AllocatedStreams;

AllocatedStreams *allocated_streams = NULL;
pthread_mutex_t allocation_lock = PTHREAD_MUTEX_INITIALIZER;
size_t allocated_count = 0;
size_t max_limit = 1000;  // predefined limit

AudioStream *createStream(int sampling_rate, int bit_depth, double duration) {
    if (allocated_count >= max_limit) return NULL;

    AudioStream *stream = malloc(sizeof(AudioStream));
    stream->sampling_rate = sampling_rate;
    stream->bit_depth = bit_depth;
    stream->duration = duration;

    pthread_mutex_lock(&allocation_lock);
    allocated_streams->streams[allocated_count] = stream;
    allocated_count++;
    pthread_mutex_unlock(&allocation_lock);

    return stream;
}

void freeAllStreams() {
    for (size_t i = 0; i < allocated_count; i++) {
        free(allocated_streams->streams[i]);
    }
    free(allocated_streams);

    pthread_mutex_lock(&allocation_lock);
    allocated_count = 0;
    pthread_mutex_unlock(&allocation_lock);
}
```
