['Here is the C++ code:

```cpp
#include <vector>
#include <mutex>
#include <chrono>
#include <thread>
#include <algorithm>

struct ServiceComponent { /* some service component properties */ };
typedef std::unique_ptr<ServiceComponent[]> ServicePtr;

struct NFV_Instance {
    int instanceID;  // Unique ID for each instance.
    char* configBuffer;  // Dynamically allocated buffer.
    ServicePtr services;  // Associated service components.
    std::chrono::system_clock::time_point lastActiveTime;  // Last active time.
};

class NFVManager {
public:
    void AddInstance(int instanceID, char* configBuffer, ServicePtr&& services) {
        std::lock_guard<std::mutex> lock(mtx);
        instances.push_back({instanceID, configBuffer, std::move(services), std::chrono::system_clock::now()});
    }

    void UpdateInstance(int instanceID, char* newConfigBuffer) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& instance : instances) {
            if (instance.instanceID == instanceID) {
                delete[] instance.configBuffer;  // Delete old buffer.
                instance.configBuffer = newConfigBuffer;  // Assign new buffer.
                instance.lastActiveTime = std::chrono::system_clock::now();  // Update last active time.
                break;
            }
        }
    }

    void EvaluateAndDeprovision(std::chrono::seconds idlePeriod) {
        std::lock_guard<std::mutex> lock(mtx);
        auto now = std::chrono::system_clock::now();
        instances.erase(std::remove_if(instances.begin(), instances.end(), [&](const NFV_Instance& instance) {
            return (now - instance.lastActiveTime) > idlePeriod;  // If instance is idle for specified period.
        }), instances.end());
    }

private:
    std::vector<NFV_Instance> instances;
    std::mutex mtx;
};
```

This class `NFVManager` manages a collection of Network Function Virtualization (NFV) instances. It provides methods for adding new instances, updating existing ones, and periodically evaluating and deprovisioning idle instances. The functions are thread-safe as they use a mutex to lock the critical sections while accessing or modifying the data.
']

