pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
FILE* logfile;
int isLoggingEnabled = 0; // set to 1 to enable logging

void initLog() {
    if (isLoggingEnabled) {
        logfile = fopen("log.txt", "a");
        if (logfile == NULL) {
            printf("Failed to open the file.\n");
            exit(1);
        }
    }
}

void writeToLog(const char* message) {
    if (!isLoggingEnabled || logfile == NULL) return;

    pthread_mutex_lock(&lock);
    fprintf(logfile, "%s\n", message);
    fflush(logfile); // flush to disk immediately
    pthread_mutex_unlock(&lock);
}

void closeLog() {
    if (isLoggingEnabled) {
        fclose(logfile);
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocateMemoryForArrayOfStructs(int N) {
    if (N < 0) {
        printf("Negative array size\n");
        exit(1);
    }

    pthread_mutex_lock(&lock); // lock for thread-safe allocation
    NFAPI_CRC_INDICATION_PDU_T* array = calloc(N, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        printf("Failed to allocate memory\n");
        exit(1);
    }

    srand(time(NULL)); // seed the random number generator
    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // random 0 or 1
    }

    writeToLog("Memory allocated and initialized");
    pthread_mutex_unlock(&lock); // unlock after allocation complete

    return array;
}

void freeAllocatedMemory(NFAPI_CRC_INDICATION_PDU_T* array) {
    if (array != NULL) {
        writeToLog("Freeing allocated memory");
        free(array);
    }
}
