```javascript
class FileLoader {
    constructor(fileList) {
        this.fileList = fileList;
        this.loadedFiles = [];
    }

    async loadFile(url) {
        return new Promise((resolve, reject) => {
            let scriptTag = document.createElement('script');
            scriptTag.src = url;
            scriptTag.onload = () => resolve();
            scriptTag.onerror = () => reject(new Error("Failed to load " + url));
            document.head.appendChild(scriptTag);
        });
    }

    async loadAllFiles() {
        for (let file of this.fileList) {
            try {
                await this.loadFile(file.url);
                console.log("Loaded: " + file.url);
                this.loadedFiles.push(file);
            } catch (error) {
                console.error("Failed to load: ", error);
                if (file.fallbackUrl) {
                    try {
                        await this.loadFile(file.fallbackUrl);
                        console.log("Fallback loaded: " + file.fallbackUrl);
                        this.loadedFiles.push(file);
                    } catch (error) {
                        console.error("Failed to load fallback: ", error);
                    }
                } else {
                    console.warn("No fallback for: " + file.url);
                }
            }
        }
    }
}
