// Signal handler function prototype
void signal_handler(int signum);

pid_t child_pid;  // Global variable to store child process ID
char *logfile = "/path/to/your/logfile";
FILE *logfd;
time_t start, end;
struct sigaction sa;

// Function to execute command in background and return status
int run_command(const char* cmd) {
    child_pid = fork(); // Create a child process

    if (child_pid < 0) { 
        perror("fork failed"); 
        return 1; 
    } 

    else if (child_id == 0) { // Child process
        sa.sa_handler = signal_handler; // Set up signal handler for child process
        sigaction(SIGINT, &sa, NULL);
        sigaction(SIGTERM, &sa, NULL);

        start = time(NULL);
        fprintf(logfd, "Starting command: %s at %ld\n", cmd, start);  // Write to logfile
        system(cmd);  // Execute the command

        end = time(NULL);
        fprintf(logfd, "Command ended: %s at %ld\n", cmd, end); //Write to logfile again.

        exit(0);   // Child process terminates after execution is done.
    } 

    else {  // Parent process continues here
        sa.sa_handler = signal_handler; // Set up signal handler for parent process
        sigaction(SIGINT, &sa, NULL);
        sigaction(SIGTERM, &sa, NULL);

        return 0; 
    } 
}

// Signal handling function.
void signal_handler(int signum) {
    kill(child_pid, SIGKILL); // Send SIGKILL to child process when parent receives a signal.
    exit(signum);             // Parent process also exits gracefully.
}
```
