```c
#include <stdio.h>
#include <pthread.h>
#include <time.h>
#include <unistd.h>
#include <stdlib.h>

typedef struct {
    int log_level;
    time_t timestamp;
    pthread_t thread_id;
    char message[256];
} LOG_ENTRY;

FILE* file = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int index = 0;
const int maxSize = 1e6;
LOG_ENTRY *logEntries = NULL;

void initialize(int logLevel, time_t timestamp) {
    if (index < maxSize) {
        pthread_mutex_lock(&mutex);
        logEntries[index].log_level = logLevel;
        logEntries[index].timestamp = timestamp;
        logEntries[index].thread_id = pthread_self();

        // Simulate a message here for brevity
        sprintf(logEntries[index].message, "Dummy message for log level %d at timestamp %ld", 
                logLevel, timestamp);
        ++index;

        if (index == maxSize) {
            // Flush the buffer to a file here
            flushToFile();
        }
        pthread_mutex_unlock(&mutex);
    } else {
        printf("Maximum size reached. Cannot log anymore.\n");
    }
}

void flushToFile() {
    if (file == NULL) file = fopen("logs.txt", "w");

    if (file != NULL && index > 0) {
        for(int i = 0; i < index; ++i) {
            fprintf(file, "%d %ld %lu %s\n", logEntries[i].log_level, 
                    logEntries[i].timestamp, (unsigned long)logEntries[i].thread_id, 
                    logEntries[i].message);
        }

        fflush(file);
        index = 0;
    }
}

void *loggingThreadFunction(void *arg) {
    int randomLogLevel = rand() % 5 + 1; // Generate a random log level between 1 and 5
    time_t timestamp = time(NULL); // Get the current time

    initialize(randomLogLevel, timestamp);
    return NULL;
}
```
