```cpp
#include <mutex>
#include <condition_variable>
#include <unordered_map>
#include <vector>
#include <string>

class ConnectionContext {
public:
    std::string sessionId;
    int uniqueConnectionIdentifier;
    std::vector<char> buffer;
};

class TCPConnectionsManager {
private:
    mutable std::mutex mtx_;
    std::unordered_map<int, ConnectionContext> connectionsMap_;
    std::condition_variable cv_;
    size_t maxBufferSize = 1024*1024; // Max buffer size 1MB

public:
    void addConnection(std::string sessionId, int uniqueConnectionIdentifier) {
        std::unique_lock<std::mutex> lock(mtx_);

        cv_.wait(lock, [this] { return connectionsMap_.size() < maxBufferSize; });

        ConnectionContext context = {sessionId, uniqueConnectionIdentifier, std::vector<char>()};
        connectionsMap_[uniqueConnectionIdentifier] = context;
    }

    void updateConnection(int uniqueConnectionIdentifier, char dataPacket) {
        std::lock_guard<std::mutex> lock(mtx_);

        if (connectionsMap_.count(uniqueConnectionIdentifier)) {
            connectionsMap_[uniqueConnectionIdentifier].buffer.push_back(dataPacket);

            cv_.notify_one(); // Notify if buffer size is small enough
        } else {
            throw std::runtime_error("Connection not found");
        }
    }

    void terminateConnection(int uniqueConnectionIdentifier) {
        std::lock_guard<std::mutex> lock(mtx_);

        if (connectionsMap_.count(uniqueConnectionIdentifier)) {
            connectionsMap_.erase(uniqueConnectionIdentifier);

            cv_.notify_all(); // Notify all waiting threads to check buffer size
        } else {
            throw std::runtime_error("Connection not found");
        }
    }
};
```
