    private String readFromURL(String urlStr) throws Exception {
        URL url = new URL(urlStr);
        try (BufferedReader in = new BufferedReader(new InputStreamReader(url.openStream()))) {
            return in.lines().reduce("", (a, b) -> a + "\n" + b);  // Combine lines into one string
        }
    }

    private String readFromFile(String filePath) throws Exception {
        Path path = Paths.get(filePath);
        byte[] bytes = Files.readAllBytes(path);
        return new String(bytes, "UTF-8");  // Convert bytes to string using UTF-8 encoding
