#include <stdlib.h>
#include <string.h>
#include <assert.h>

typedef struct UE_CONNECTION_STATS_T {
    int RRC_STATE;
    int RNTI;
    int TX_POWER_LEVEL;
    int COUNTER;
    struct UE_CONNECTION_STATS_T *next;
} UE_CONNECTION_STATS_T;

static UE_CONNECTION_STATS_T *head = NULL;

UE_CONNECTION_STATS_T* createNode(int rrcState, int rnti, int txPowerLevel) {
    UE_CONNECTION_STATS_T *newNode = malloc(sizeof(UE_CONNECTION_STATS_T));

    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    newNode->RRC_STATE = rrcState;
    newNode->RNTI = rnti;
    newNode->TX_POWER_LEVEL = txPowerLevel;
    newNode->COUNTER = 0; // initialize COUNTER with a value drawn from a predefined distribution.

    return newNode;
}

int insert(int rrcState, int rnti, int txPowerLevel) {
    UE_CONNECTION_STATS_T *newNode = createNode(rrcState, rnti, txPowerLevel);

    if (newNode == NULL) return -1; // memory allocation failed.

    newNode->next = head;
    head = newNode;

    return 0; // insertion successful.
}

void traverse() {
    UE_CONNECTION_STATS_T *temp = head;

    while (temp != NULL) {
        assert(temp->RRC_STATE > 0 && temp->RNTI > 0 && temp->TX_POWER_LEVEL > 0); // verify the integrity of allocated memory.

        /* perform operations on temp node */

        temp = temp->next;
    }
}

void freeList() {
    UE_CONNECTION_STATS_T *currentNode = head, *nextNode = NULL;

    while (currentNode != NULL) {
        nextNode = currentNode->next;
        free(currentNode);

        currentNode = nextNode;
    }

    head = NULL; // ensure that dangling pointers are not left.
}
