} NFAPI_CRC_INDICATION_PDU_T;

void generateNfarCipherPduList(int n, const uint8_t *encryptionKey, const uint8_t *iv, uint8_t *encryptedData, size_t *encryptedSize) {
    if (n <= 0 || encryptionKey == NULL || iv == NULL || encryptedData == NULL || encryptedSize == NULL) {
        // Handle invalid parameters
        return;
    }

    // Create and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T *pduList = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (pduList == NULL) {
        // Handle allocation failure
        return;
    }

    for (int i = 0; i < n; ++i) {
        pduList[i].RX_UE_INFORMATION_TAG = /* some value */;
        pduList[i].RNTI = /* some value */;
        pduList[i].CRC_INDICATION_REL8_TAG = /* some randomly set CRCFLAG */;
    }

    // Encrypt the list using AES-CBC with the provided encryption key and IV
    AES_KEY aesKey;
    if (AES_set_encrypt_key(encryptionKey, 128 /* in bits */, &aesKey) != 0) {
        // Handle encryption failure
        free(pduList);
        return;
    }

    // Calculate padding size and ensure sufficient buffer
    int blockSize = AES_BLOCK_SIZE;
    *encryptedSize = n * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (*encryptedSize % blockSize != 0) {
        *encryptedSize += blockSize - (*encryptedSize % blockSize);
    }

    // Check enough buffer size for encryptedData
    if (encryptedSize <= n) {
        // Handle insufficient buffer size for encryptedData
        free(pduList);
        return;
    }

    uint8_t *padding = malloc(*encryptedSize);
    if (padding == NULL) {
        // Handle allocation failure for padding
        free(pduList);
        return;
    }

    memcpy(padding, pduList, n);

    AES_cbc_encrypt(padding, encryptedData, *encryptedSize, &aesKey, iv, AES_ENCRYPT);

