#define MAX_SERIALIZED_SIZE 2048

typedef struct {
    // Add fields for your message broker structure here
} MessageBroker;

typedef struct EventNode {
    int event;
    char* serializedMsg;
    struct EventNode* next;
} EventNode;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

EventNode* createEventList(int* events, int numEvents, MessageBroker* broker, int lastEvent, int threshold) {
    if (numEvents == 0 || broker == NULL || lastEvent < 0 || threshold <= 0) return NULL;

    EventNode *head = NULL, *tail = NULL;

    for (int i = 0; i < numEvents; ++i) {
        int event = events[i];
        if (event <= lastEvent || event % 10 != threshold) continue;

        // Potentially serialize message and append newline character
        char* serializedMsg = malloc(MAX_SERIALIZED_SIZE);
        if (serializedMsg == NULL) {
            freeEventList(&head);
            return NULL;
        }
        // SerializeMessage function is not provided here. It should be implemented based on your business logic. 
        serializeMessage(broker, event, serializedMsg);

        EventNode* newNode = malloc(sizeof(EventNode));
        if (newNode == NULL) {
            freeEventList(&head);
            return NULL;
        }
        newNode->event = event;
        newNode->serializedMsg = serializedMsg;

        pthread_mutex_lock(&lock);
        if (head == NULL) {
            head = tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
        pthread_mutex_unlock(&lock);
    }

    return head;
}

void freeEventList(EventNode** head) {
    EventNode* current = *head, *temp;
    while (current != NULL) {
        temp = current->next;
        free(current->serializedMsg);
        free(current);
        current = temp;
    }
    *head = NULL;
}
```

