import java.net.*;
import java.io.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.regex.*;

public class HttpStatusCodeFetcher {
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private ConcurrentMap<String, Integer> cache;

    public HttpStatusCodeFetcher() {
        this.cache = new ConcurrentHashMap<>();
    }

    public Map<String, Integer> fetchHttpStatuses(List<URL> urls, Pattern pattern) {
        for (URL url : urls) {
            if (pattern == null || pattern.matcher(url.getHost()).matches()) {
                executor.submit(() -> {
                    try {
                        HttpURLConnection connection = (HttpURLConnection) url.openConnection();
                        int responseCode = connection.getResponseCode();
                        cache.put(url.toString(), responseCode);
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                });
            }
        }

        return new HashMap<>(cache); // Return a copy of the current cache.
    }
}
```
