#include <semaphore.h>

typedef struct JPEG_DECODE_PDU_T {
    void *metadata;   // Assume metadata can be any type, need external data source for fetching this.
    int width;
    int height;
    int qualityRating; 
} JPEG_DECODE_PDU_T;

typedef struct Pool {
    sem_t mutex;
    size_t capacity;
    size_t count;
    void *memory;
} Pool;

Pool *createPool(size_t capacity) {
    Pool *pool = malloc(sizeof(Pool));
    if (pool == NULL) return NULL;
    sem_init(&pool->mutex, 0, 1);
    pool->capacity = capacity;
    pool->count = 0;
    pool->memory = calloc(capacity, sizeof(JPEG_DECODE_PDU_T));
    if (pool->memory == NULL) {
        free(pool);
        return NULL;
    }
    return pool;
}

void *allocatePoolMemory(Pool *pool) {
    sem_wait(&pool->mutex);
    void *ptr = NULL;
    if (pool->count < pool->capacity) {
        ptr = ((JPEG_DECODE_PDU_T*)pool->memory) + pool->count++;
    }
    sem_post(&pool->mutex);
    return ptr;
}

void freePoolMemory(Pool *pool, void* memoryToFree) {
    // Implementation depends on specific use-case but typically involves moving freed memory to end of pool and decrementing count.
    // Logging mechanism should be integrated here for any cleanup failures. 
}
