['This task requires a lot of code and handling different aspects of system programming like process management, signal handling, logging, resource control etc. However, I will provide an example of how you might start implementing some parts of this function:

```c
#include <stdio.h>
#include <signal.h>
#include <sys/types.h>
#include <unistd.h>
#include <sys/resource.h>
#include <time.h>
#include <fcntl.h>

int run_command(char *command, char* logfile) {
    pid_t child;
    int status;

    if ((child = fork()) < 0) {
        perror("fork failed");
        return 0;
    }

    // Child process
    else if (child == 0) {
        // Limit CPU usage to 50%
        struct rlimit cpu_limiter;
        getrlimit(RLIMIT_CPU, &cpu_limiter);
        cpu_limiter.rlim_cur = cpu_limiter.rlim_max / 2;
        setrlimit(RLIMIT_CPU, &cpu_limiter);

        // Log start time
        FILE *log = fopen(logfile, "a");
        if (log == NULL) {
            perror("Failed to open log file");
            return 0;
        }
        time_t now = time(NULL);
        char* timestr = ctime(&now);
        fprintf(log, "%d - Started command at %s\n", getpid(), timestr);

        // Execute the command
        if (system(command) == -1) {
            perror("Failed to execute command");
            return 0;
        }

        now = time(NULL);
        timestr = ctime(&now);
        fprintf(log, "%d - Command finished at %s\n", getpid(), timestr);
        fclose(log);
    }

    // Parent process
    else {
        signal(SIGINT, SIG_IGN);   // ignore interrupt signal
        wait(&status);            // wait for child to finish

        if (WIFEXITED(status)) {
            return 1;
        } else {
            return 0;
        }
    }
}
```
This code is a simplified version of the function you requested. It uses `fork()` to create a child process that executes the given command, and then waits for it using `wait(&status)` in the parent process. The CPU usage limit is implemented using `getrlimit()` and `setrlimit()`, and logging of start and end times is done with `fopen()`, `time()`, `ctime()` and `fprintf()`.

