// Define a structure to hold each transaction record
typedef struct {
    char *customerID;
    double transactionAmount;
    char *currencyType;
    char *transactionDate;
} TransactionRecord;

// Function to validate and compute MD5 hash of individual records
void* processRecord(void *arg) {
    // Cast the argument back to a pointer to a TransactionRecord
    TransactionRecord *record = (TransactionRecord*)arg;

    // Validate record here...

    // Concatenate customer ID, transaction amount, currency type, and transaction date into a single string
    char *concatenatedString = malloc(strlen(record->customerID) + strlen(record->currencyType) + strlen(record->transactionDate) + 30); // 30 is arbitrary, you should replace it with accurate value.
    sprintf(concatenatedString, "%s,%lf,%s,%s", record->customerID, record->transactionAmount, record->currencyType, record->transactionDate);

    // Compute MD5 hash of the concatenated string
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5((unsigned char*)concatenatedString, strlen(concatenatedString), md5Hash);

    /* Save or return the hashes and summary report for each batch */

    free(concatenatedString);
}

// Function to handle financial records processing
void manageFinancialRecords(TransactionRecord *records, int numOfRecords, char *configFile) {
    // Define a thread pool of maximum size 500
    pthread_t threads[500];

    for (int i = 0; i < numOfRecords; i += 500) { // Loop over each batch of records
        int currentBatchSize = (i + 500 > numOfRecords) ? (numOfRecords - i) : 500;

        for (int j = 0; j < currentBatchSize; j++) { // Spawn a thread for each record in the batch
            pthread_create(&threads[j], NULL, processRecord, &records[i + j]);
        }

        for (int j = 0; j < currentBatchSize; j++) { // Join all threads after they finish their tasks
            pthread_join(threads[j], NULL);
        }
    }

    /* Process configuration file */
}
```
This code provides a basic structure of how you can handle financial records in batches. It uses POSIX threads (pthreads) for parallel processing, OpenSSL's MD5 library for computing hash and json-c for parsing the JSON config file. The processing for each record is performed by separate threads, which allows for concurrent processing of multiple records simultaneously, thus improving performance.
The `processRecord` function validates and processes individual transaction records. This example only calculates an MD5 hash of concatenated string but in actual implementation you might want to do more complex computations. The code that processes the configuration file is not provided as it's quite complex and requires knowledge about the format of your JSON files and how you would like to manipulate them.
