#include <pthread.h>
#define MAX_CONCURRENT_REQUESTS 5000
#define MAX_QUEUE_CAPACITY 10000

typedef struct Request {
    int requestId;
    char* payload;
    struct Metadata {
        time_t timestamp;
        char* requestType;
        char* userIPAddress;
        int urgency; // higher value means more urgent
        int importance; // higher value means more important
    } metadata;
} Request;

Request queue[MAX_QUEUE_CAPACITY];
int front = 0, rear = -1, itemCount = 0;
pthread_mutex_t lock;
pthread_cond_t notFull, notEmpty;

void enqueue(Request data) {
    pthread_mutex_lock(&lock);
    while (itemCount == MAX_QUEUE_CAPACITY) {
        pthread_cond_wait(&notFull, &lock); // Wait until queue is not full.
    }

    if (rear == MAX_QUEUE_CAPACITY - 1) {
        rear = -1;            
    }       

    queue[++rear] = data;  
    itemCount++;
    pthread_cond_signal(&notEmpty); // Signal that the queue is not empty.
    pthread_mutex_unlock(&lock);
}

Request dequeue() {
    pthread_mutex_lock(&lock);
    while (itemCount == 0) {
        pthread_cond_wait(&notEmpty, &lock); // Wait until queue is not empty.
    }

    Request data = queue[front++];

    if (front == MAX_QUEUE_CAPACITY) {
        front = 0;
    }

    itemCount--;
    pthread_cond_signal(&notFull); // Signal that the queue is not full.
    pthread_mutex_unlock(&lock);
    return data;
}

void updateRequestStatus(int requestId, Request newData) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < itemCount; i++) {
        int index = (front + i) % MAX_QUEUE_CAPACITY;
        if (queue[index].requestId == requestId) {
            queue[index] = newData;
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}

void processUserRequestsInRealTime() {
