typedef struct {
    int capacity;
    double* data;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray createArray(int capacity) {
    DynamicArray array = {0};
    array.capacity = capacity;
    array.data = malloc(sizeof(double) * capacity);
    pthread_mutex_init(&array.mutex, NULL);
    return array;
}

void addElement(DynamicArray* array, double element) {
    pthread_mutex_lock(&array->mutex);

    if (array->capacity <= array->size) {
        // Resize the array when it's full
        array->data = realloc(array->data, sizeof(double) * array->capacity * 2);
        array->capacity *= 2;
    }

    array->data[array->size++] = element;

    pthread_mutex_unlock(&array->mutex);
}
