    int unique_id;
    void *config_data;
    time_t last_active;
} Node;

Node** nodes = NULL;
size_t node_count = 0;
size_t capacity = 10;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int purge_inactive_nodes(time_t inactive_duration) {
    pthread_mutex_lock(&mutex);

    time_t now = time(NULL);
    for (size_t i = 0; i < node_count;) {
        if (now - nodes[i]->last_active > inactive_duration) {
            free(nodes[i]->config_data);
            free(nodes[i]);
            nodes[i] = nodes[--node_count];
        } else {
            i++;
        }
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int add_or_update_node(char* mac, int id, void *config) {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < node_count; i++) {
        if (!strcmp(nodes[i]->mac_address, mac)) {
            free(nodes[i]->config_data);
            strncpy(nodes[i]->mac_address, mac, sizeof(nodes[i]->mac_address));
            nodes[i]->unique_id = id;
            nodes[i]->config_data = config;
            nodes[i]->last_active = time(NULL);

            pthread_mutex_unlock(&mutex);
            return 0;
        }
    }

    if (node_count >= capacity) {
        capacity *= 2;
        nodes = realloc(nodes, sizeof(*nodes) * capacity);
    }

    Node* new_node = malloc(sizeof(Node));
    strncpy(new_node->mac_address, mac, sizeof(new_node->mac_address));
    new_node->unique_id = id;
    new_node->config_data = config;
    new_node->last_active = time(NULL);

    nodes[node_count++] = new_node;

    pthread_mutex_unlock(&mutex);
    return 0;
}
```
