// Logging mutex to prevent data corruption when writing logs simultaneously 
pthread_mutex_t logMutex;

void* readStream(void *arg) {
    int input;
    FILE *logFile = fopen("logs", "a"); // Open a file for logging

    while (fscanf(stdin, "%d", &input) == 1) {
        pthread_mutex_lock(&logMutex); // Lock the mutex before writing to the log file

        fprintf(logFile, "Thread %ld: read integer %d\n", (long)arg, input);

        pthread_mutex_unlock(&logMutex); // Unlock the mutex after finishing writing to the log file
    }

    fclose(logFile);
}

int main() {
    int numThreads = 2;  // Number of threads, you can set according to your need.
    pthread_t threads[numThreads];
    pthread_mutex_init(&logMutex, NULL);

    for(long i=0; i<numThreads; i++) {
        pthread_create(&threads[i], NULL, readStream, (void*)i);
    }

    for(int i=0; i<numThreads; i++) {
        pthread_join(threads[i], NULL);  // Wait until all threads are finished
    }

    pthread_mutex_destroy(&logMutex);  // Destroy the mutex
}
```
This program creates multiple threads that read from standard input concurrently, and logs every integer it reads to a file. It uses a mutex to ensure thread-safety when writing to the log file.
