void *getIP(void *args) {
    ThreadInfo *info = (ThreadInfo *) args;
    struct hostent *host = gethostbyname(info->hostname);
    if (host == NULL) {
        // Handle error here. Log the error message and return appropriate error code.
    } else {
        char ip[INET6_ADDRSTRLEN];
        inet_ntop(host->h_addrtype, host->h_addr_list[0], ip, sizeof(ip));
        // You may want to log the resolved IP address here.
    }
    free(info);
}

int resolveDNS(char *hostname) {
    static unsigned int windowStart = 0;
    static int countInWindow = 0;

    sem_wait(&semaphore); // This will block if concurrency level is reached.
    countInWindow++;
    if (countInWindow > memoryLimit / chunkSize) {
        while(difftime(time(NULL), windowStart) < 1) {}
        windowStart = time(NULL);
        countInWindow = 0;
    }

    pthread_t thread;
    ThreadInfo *info = (ThreadInfo *) malloc(sizeof(*info));
    info->hostname = strdup(hostname);
    int ret = pthread_create(&thread, NULL, getIP, (void*) info);

