    // Log context ID and event type with timestamp
}

LTE_RRC_UE_CONTEXT_T getContextByIP(char* IP) {
    pthread_mutex_lock(&lock);  // Lock for thread safety
    for (int i = 0; i < context_count; i++) {
        if (strcmp(contexts[i].IP_address, IP) == 0) {
            pthread_mutex_unlock(&lock);  // Unlock after accessing context
            return contexts[i];
        }
    }
    pthread_mutex_unlock(&lock);  // Unlock if no matching context found
}

void addContext(int MAC_entity, int unique_C_RNTI, char* IP_address, void* SIB_buffer) {
    if (validateIP(IP_address)) {
        LTE_RRC_UE_CONTEXT_T newContext;
        newContext.MAC_entity = MAC_entity;
        newContext.unique_C_RNTI = unique_C_RNTI;
        newContext.IP_address = strdup(IP_address); // Duplicate string to ensure immutability and prevent memory leaks
        newContext.SIB_buffer = SIB_buffer;
        newContext.active = true;

        pthread_mutex_lock(&lock);  // Lock for thread safety
        contexts[context_count++] = newContext;
        pthread_mutex_unlock(&lock);  // Unlock after adding context

        logContextEvent(newContext.unique_C_RNTI, "Added");
    } else {
        printf("Invalid IP: %s\n", IP_address);
        // Log invalid IP for auditing purposes
    }
}

void updateContext(int unique_C_RNTI, void* SIB_buffer) {
    pthread_mutex_lock(&lock);  // Lock for thread safety
    for (int i = 0; i < context_count; i++) {
        if (contexts[i].unique_C_RNTI == unique_C_RNTI) {
            contexts[i].SIB_buffer = SIB_buffer; // Update buffer of existing context

            logContextEvent(unique_C_RNTI, "Updated");
        }
    }
    pthread_mutex_unlock(&lock);  // Unlock after updating context
}

void purgeInactiveContexts() {
    pthread_mutex_lock(&lock);  // Lock for thread safety
    for (int i = 0; i < context_count; i++) {
        if (!contexts[i].active) {
            free(contexts[i].IP_address); // Free memory allocated to string
            free(contexts[i].SIB_buffer);  // Free memory for SIB buffer

            contexts[i] = contexts[--context_count]; // Swap with last context and decrement count
            i--; // Retry current position as it's now a different context
        }
    }
    pthread_mutex_unlock(&lock);  // Unlock after purging inactive contexts
}
