    pthread_mutex_lock(&arr->mutex);
    if (arr->size == arr->capacity) {
        // Reallocate memory
        arr->capacity *= 2;
        arr->data = realloc(arr->data, arr->capacity * sizeof(LTE_PDCP_PDU));
