int validateIP(char* ipAddress) {
    struct sockaddr_in sa;
    return inet_pton(AF_INET, ipAddress, &(sa.sin_addr)) != 0;
}

int addOrUpdateConnection(char* mac, int connID, char* clientIP, void* data) {
    if (!validateIP(clientIP)) return -1; //Invalid IP address

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < numConnections; ++i) {
        if (connections[i].connectionID == connID) {
            strncpy(connections[i].mac, mac, sizeof(connections[i].mac));
            connections[i].clientIP = inet_addr(clientIP);
            free(connections[i].dataBuffer); //Free old buffer before allocating new memory
            connections[i].dataBuffer = malloc(sizeof(/*appropriate size*/));
            if (connections[i].dataBuffer != NULL) {
                memcpy(connections[i].dataBuffer, data, /*appropriate size*/);
            } else {
                //Handle allocation failure
            }
            pthread_mutex_unlock(&mutex);
            return 0; //Connection updated successfully
        }
    }

    if (numConnections >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&mutex);
        return -2; //Max connections reached
    }

    TCP_CONNECTION_T newConnection = {{0}};
    strncpy(newConnection.mac, mac, sizeof(newConnection.mac));
    newConnection.connectionID = connID;
    newConnection.clientIP = inet_addr(clientIP);
    newConnection.dataBuffer = malloc(/*appropriate size*/);
    if (newConnection.dataBuffer != NULL) {
        memcpy(newConnection.dataBuffer, data, /*appropriate size*/);
    } else {
        //Handle allocation failure
    }

    connections[numConnections++] = newConnection;
    pthread_mutex_unlock(&mutex);
    return 0; //New connection added successfully
}

void purgeUnusedConnections() {
    time_t now = time(NULL);
    for (size_t i = 0; i < numConnections; ++i) {
        if ((now - connections[i].lastActiveTime) > PURGE_INTERVAL) {
            free(connections[i].dataBuffer); //Free unused connection's buffer
            memmove(&connections[i], &connections[i + 1], (numConnections - i - 1) * sizeof(*connections));
            --numConnections;
        }
    }
}

/* Other functions, including logging mechanism and XML export function, need to be implemented. */
