class DistributedSessionManager {
private:
    std::vector<SessionContext> sessions;
    std::mt19937 generator;
    std::mutex mtx;

public:
    DistributedSessionManager(int seed = std::random_device{}()) : generator(seed) {}

    void addSession(const SessionContext& session) {
        std::lock_guard<std::mutex> lock(mtx);
        sessions.push_back(session);
    }

    void updateSession(int id, const SessionContext& updatedSession) {
        std::lock_guard<std::mutex> lock(mtx);
        for (auto& session : sessions) {
            if (session.sessionId == id) {
                session = updatedSession;
                break;
            }
        }
    }

    void resetRandomGenerator(int newSeed) {
        std::lock_guard<std::mutex> lock(mtx);
        generator.seed(newSeed);
    }

    int getUniformDistribution(int min, int max) {
        std::uniform_int_distribution<> distribution(min, max);
        return distribution(generator);
    }

    double getNormalDistribution(double mean, double stddev) {
        std::normal_distribution<double> distribution(mean, stddev);
        return distribution(generator);
