import os, threading
from queue import Queue

class WorkerThread(threading.Thread):
    def __init__(self, queue):
        threading.Thread.__init__(self)
        self.queue = queue

    def run(self):
        while True:
            file_path = self.queue.get()
            self.process_log(file_path)
            self.queue.task_done()

    def process_log(self, file_path):
        with open(file_path, 'r') as log_file:
            for line in log_file:
                if "ERROR" in line or "CRITICAL" in line:  # adjust severity level as per your needs
                    print(line)

def main():
    queue = Queue()

    for i in range(4):  # number of threads you want to process logs
        worker = WorkerThread(queue)
        worker.daemon = True
        worker.start()

    for file_name in os.listdir('logs/'):  # directory containing log files, replace with your path
        queue.put('logs/{}'.format(file_name))

    queue.join()

if __name__ == '__main__':
    main()
```
