    char *session_id;
    char *response_headers;
    char ip[INET_ADDRSTRLEN];
    int port;
} HTTP_CLIENT_T;

#define MAX_CLIENTS 3000
#define BUFFER_SIZE 1024
#define PURGE_INTERVAL 60

HTTP_CLIENT_T *clients[MAX_CLIENTS];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int client_count = 0;

void* purge_inactive_clients(void* arg) {
    while (1) {
        sleep(PURGE_INTERVAL); // Every 60 seconds

        pthread_mutex_lock(&lock);
        for (int i = 0; i < client_count; i++) {
            if (!is_active(clients[i])) {
                remove_client(clients[i]);
                --client_count;
            }
        }
        pthread_mutex_unlock(&lock);
    }

    return NULL;
}

int add_or_update_client(HTTP_CLIENT_T* client) {
    if (validate_ip_and_port(client->ip, client->port)) {
        pthread_mutex_lock(&lock);

        for (int i = 0; i < client_count; i++) {
            if (strcmp(clients[i]->session_id, client->session_id) == 0) { // updating existing client
                free(clients[i]);
                clients[i] = client;

                pthread_mutex_unlock(&lock);
                return 1; // updated
            }
        }

        if (client_count < MAX_CLIENTS) {
            clients[client_count++] = client;

            pthread_mutex_unlock(&lock);
            return 0; // added
        }

        pthread_mutex_unlock(&lock);
    }

    return -1; // validation failed or max limit reached
}

int remove_client(HTTP_CLIENT_T* client) {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < client_count; i++) {
        if (clients[i] == client) {
            free(clients[i]->session_id);
            free(clients[i]->response_headers);

            clients[i] = clients[--client_count];
            close(client->socket);

            pthread_mutex_unlock(&lock);
            return 0; // removed
        }
    }

    pthread_mutex_unlock(&lock);
    return -1; // not found
}

char* get_clients_as_json() {
    // Implement this to convert clients array to JSON format. You may use a library like cJSON for easy conversion.
    return NULL;
}
```
