    pid_t childPID = fork();

    if (childPID == 0) { // Child process
        signal(SIGTERM, SIG_DFL); // Reset the termination signal to its default behaviour in child process

        // Your command execution here

    } else if (childPID > 0) { // Parent process
        int status;
        waitpid(childPID, &status, 0); // Wait for the child process to finish

        clock_gettime(CLOCK_MONOTONIC, &tpEnd);
        long executionTime = (tpEnd.tv_sec - tpStart.tv_sec) * 1e9 + (tpEnd.tv_nsec - tpStart.tv_nsec);

        if (executionTime > maxExecutionTime * 1e6) { // If execution time exceeds the limit, send SIGTERM to child process
            kill(childPID, SIGTERM);

            // Your log handling and external logging service integration here
            char* log = "Command exceeded maximum allowed execution time";
