        logLevelMap.put("ERROR", 40);
        logLevelMap.put("FATAL", 50);
        logLevelMap.put("AUDIT", 60);
    }

    public String formatLogMessage(String message, int logLevel) {
        Date date = new Date();
        return String.format("%s [Thread-%d] %s: %s", this.dateFormat.format(date), Thread.currentThread().getId(), getCurrentLogLevelName(logLevel), message);
    }

    public String getCurrentLogLevelName(int logLevel) {
        for (Map.Entry<String, Integer> entry : logLevelMap.entrySet()) {
            if (entry.getValue() == logLevel) return entry.getKey();
        }

        throw new IllegalArgumentException("Invalid log level: " + logLevel);
    }

    public int convertLogLevelToValue(String logLevelName) {
        Integer value = logLevelMap.get(logLevelName.toUpperCase());
        if (value == null) {
            throw new IllegalArgumentException("Invalid log level name: " + logLevelName);
        }

        return value;
    }

    @Override
    public String toString() {
        return String.format("Log Formatter: [DateFormat: %s, LogLevelMap: %s]", this.dateFormat.toPattern(), logLevelMap);
    }
}
