// Function to allocate memory and initialize a new context
LTE_RRC_UE_CONTEXT_T* createContext(int mac, unsigned long crnti) {
    LTE_RRC_UE_CONTEXT_T* ctx = (LTE_RRC_UE_CONTEXT_T*) malloc(sizeof(LTE_RRC_UE_CONTEXT_T));
    if (!ctx) return NULL; // Handle memory allocation failure

    ctx->mac_entity = mac;
    ctx->unique_crnti = crnti;
    ctx->sibu = malloc(sizeof(void*)); 
    if(!ctx->sibu){ 
        free(ctx); // Handle memory allocation failure
        return NULL;
    }

    return ctx;
}

// Function to expand the dynamic array if necessary
int ensureCapacity() {
    pthread_mutex_lock(&lock);
    if (array_size < array_capacity) {
        pthread_mutex_unlock(&lock);
        return 1; // No need to expand array
    }

    LTE_RRC_UE_CONTEXT_T** new_ctx_arr = realloc(context_array, sizeof(LTE_RRC_UE_CONTEXT_T*) * (array_capacity + 10));
    if (!new_ctx_arr) {
        pthread_mutex_unlock(&lock);
        return 0; // Handle memory allocation failure
    }

    context_array = new_ctx_arr;
    array_capacity += 10;
    pthread_mutex_unlock(&lock);
    return 1;
}

// Function to add a new context
int addContext(int mac, unsigned long crnti) {
    if (!ensureCapacity()) return 0; // Handle memory allocation failure

    LTE_RRC_UE_CONTEXT_T* ctx = createContext(mac, crnti);
    if (!ctx) return 0; // Handle context creation failure

    pthread_mutex_lock(&lock);
    context_array[array_size++] = ctx;
    pthread_mutex_unlock(&lock);
    return 1;
}
