size_t contextCount = 0;
pthread_mutex_t contextMutex = PTHREAD_MUTEX_INITIALIZER;

void addContext(MAC_ENTITY macEntity, int cRnti) {
    pthread_mutex_lock(&contextMutex);

    // Reallocate memory to append new context
    contexts = realloc(contexts, (++contextCount)*sizeof(*contexts));

    LTE_RRC_UE_CONTEXT_T* newContext = malloc(sizeof(*newContext));
    newContext->macEntity = macEntity;
    newContext->cRnti = cRnti;
    newContext->sibBuffer = NULL; // Allocate memory for sibBuffer if needed

    contexts[contextCount - 1] = newContext;

    pthread_mutex_unlock(&contextMutex);
}

void updateContext(int cRnti, MAC_ENTITY macEntity) {
    pthread_mutex_lock(&contextMutex);

    for (size_t i = 0; i < contextCount; ++i) {
        if (contexts[i]->cRnti == cRnti) {
            contexts[i]->macEntity = macEntity;
            break;
        }
    }

    pthread_mutex_unlock(&contextMutex);
}

void purgeUnusedContexts() {
    pthread_mutex_lock(&contextMutex);

    // Find unused contexts and release their memory
    for (size_t i = 0; i < contextCount;) {
        if (!isContextUsed(contexts[i])) { 
            free(contexts[i]->sibBuffer);
            free(contexts[i]);

            // Shift other contexts to fill the gap
            for (size_t j = i; j < contextCount - 1; ++j)
                contexts[j] = contexts[j + 1];

            --contextCount;
        } else {
            ++i;
        }
    }

    // Reallocate memory to shrink array if necessary
    contexts = realloc(contexts, contextCount*sizeof(*contexts));

    pthread_mutex_unlock(&contextMutex);
}
