['Sure, here is a simple example of how to implement this in C. Please note that you need to install `<dirent.h>`, `<sys/stat.h>`, `<time.h>`, and `<unistd.h>` libraries for this code to work. Also please note that reading large directories or handling multiple files can be resource-intensive processes depending on the system's capacity, so always make sure you have enough resources available before attempting such operations:

```c
#include <stdio.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <unistd.h>
#include <string.h>

struct log_event {
    time_t timestamp;
    int severity;
};

void process_file(const char *filename, const struct tm start, const struct tm end) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        printf("Failed to open file %s\n", filename);
        return;
    }

    struct log_event event;
    int count = 0;
    float sum_severity = 0.0f;

    while(fscanf(file, "%ld %d", &event.timestamp, &event.severity) == 2) {
        if (difftime(mktime(gmtime(&event.timestamp)), mktime((struct tm*)&start)) >= 0 && 
            difftime(mktime(gmtime(&event.timestamp)), mktime((struct tm*)&end)) <= 0) {
            ++count;
            sum_severity += event.severity;
        }
    }

    fclose(file);

    printf("File: %s\nTotal events: %d\nAverage severity: %f\n", filename, count, (float)sum_severity / count);
}

void process_directory(const char *dirname, const struct tm start, const struct tm end) {
    DIR* dir = opendir(dirname);
    if (dir == NULL) {
        printf("Failed to open directory %s\n", dirname);
        return;
    }

    struct dirent *ent;
    while ((ent = readdir(dir)) != NULL) {
        if (strcmp(ent->d_name, ".") != 0 && strcmp(ent->d_name, "..") != 0) {
            char path[1024];
            snprintf(path, sizeof(path), "%s/%s", dirname, ent->d_name);

            struct stat st;
            if (stat(path, &st) == 0 && S_ISREG(st.st_mode)) {
                process_file(path, start, end);
            } else if (S_ISDIR(st.st_mode)) {
                // recursive call to process subdirectories
                process_directory(path, start, end);
            }
        }
    }

    closedir(dir);
}

int main(int argc, char* argv[]) {
    if (argc != 5) {
        printf("Usage: %s <directory> <start_date> <end_date>\n", argv[0]);
        return 1;
    }

    struct tm start = {0}, end = {0};
    strptime(argv[2], "%Y-%m-%d %H:%M:%S", &start);
    strptime(argv[3], "%Y-%m-%d %H:%M:%S", &end);

    process_directory(argv[1], start, end);

    return 0;
}
```
This program reads the command line arguments for a directory name and date range. For each file in the directory (and its subdirectories), it processes the log files and prints out the total number of events and average severity per file. Each log event is represented by `log_event` struct, which includes a timestamp and a severity level. The `process_file()` function reads the log file line by line and increments the counter for each event that falls within the specified date range.

Please modify this code according to your specific needs (e.g., more complex command-line arguments parsing, different log file formats etc.). It's also recommended to add error handling in real world applications, e.g., checking if `fopen()` succeeded before trying to read from the file. The above program does not include these checks for simplicity and clarity.
