import java.util.*;
import java.util.concurrent.*;
import org.json.*;

public class EventManager {
    private ConcurrentHashMap<String, AtomicInteger> events = new ConcurrentHashMap<>();
    private ExecutorService executor = Executors.newFixedThreadPool(10); // custom thread pool

    public void addEvent(String eventId, Object eventData) {
        if (events.containsKey(eventId)) {
            throw new IllegalArgumentException("Event with ID " + eventId + " already exists.");
        }

        JSONObject event = new JSONObject();
        event.put("id", eventId);
        event.put("timestamp", System.currentTimeMillis());
        event.put("data", eventData);

        events.put(eventId, event);

        // asynchronous logging
        executor.execute(() -> logEvent(event, "ADDED")); 
    }

    public void updateEvent(String eventId, Object newEventData) {
        if (!events.containsKey(eventId)) {
            throw new IllegalArgumentException("No such event exists.");
        }

        JSONObject oldEvent = events.get(eventId);
        JSONObject updatedEvent = new JSONObject();
        updatedEvent.put("id", eventId);
        updatedEvent.put("timestamp", System.currentTimeMillis());
        updatedEvent.put("data", newEventData);

        // asynchronous logging of update
        executor.execute(() -> logEvent(oldEvent, "UPDATED"));

        events.replace(eventId, oldEvent, updatedEvent);
    }

    public void deleteEvent(String eventId) {
        if (!events.containsKey(eventId)) {
            throw new IllegalArgumentException("No such event exists.");
        }

        JSONObject deletedEvent = events.remove(eventId);

        // asynchronous logging of deletion
        executor.execute(() -> logEvent(deletedEvent, "DELETED")); 
    }

    private void logEvent(JSONObject event, String action) {
        System.out.println("Event with ID: " + event.get("id") + " has been " + action);
        // add your logging mechanism here
    }

    public JSONArray getEvents() {
        return new JSONArray(events.values());
    }
}
