    int count;
    pthread_mutex_t lock;  // Mutex for synchronization
} ContextArray;

ContextArray* createContextArray() {
    ContextArray* arr = malloc(sizeof(ContextArray));
    if (arr == NULL) return NULL;

    arr->array = NULL;
    arr->count = 0;
    pthread_mutex_init(&arr->lock, NULL);
    return arr;
}

void addToArray(ContextArray* array, LTE_RRC_UE_CONTEXT_T context) {
    pthread_mutex_lock(&array->lock);  // Lock for synchronization

    array->count++;
    array->array = realloc(array->array, sizeof(LTE_RRC_UE_CONTEXT_T)*array->count);

    if (array->array != NULL) {
        array->array[array->count - 1] = context;
    } else {
        // Handle memory allocation failure here...
    }

    pthread_mutex_unlock(&array->lock);  // Unlock after operation is done
}

void updateInArray(ContextArray* array, int index, LTE_RRC_UE_CONTEXT_T context) {
    pthread_mutex_lock(&array->lock);  // Lock for synchronization

    if (index >= 0 && index < array->count) {
        array->array[index] = context;
    } else {
        // Handle out of bounds error here...
    }

    pthread_mutex_unlock(&array->lock);  // Unlock after operation is done
}

void freeContextArray(ContextArray* array) {
    pthread_mutex_lock(&array->lock);  // Lock for synchronization

    for (int i = 0; i < array->count; ++i) {
        free(array->array[i].sibBuffer);  // Free the SIB buffer
    }

    free(array->array);  // Free the array itself
    pthread_mutex_unlock(&array->lock);  // Unlock after operation is done
}
