#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // ... fill this out as needed ...
} LTE_PHY_RX_INDICATION_T;

// Memory pool node
typedef struct mpNode{
    LTE_PHY_RX_INDICATION_T *structure;
    struct mpNode *next;
} memoryPoolNode;

memoryPoolNode *poolHead = NULL; // Memory Pool's head
pthread_mutex_t poolLock = PTHREAD_MUTEX_INITIALIZER;

// Allocate from the memory pool
LTE_PHY_RX_INDICATION_T* allocate() {
    pthread_mutex_lock(&poolLock); // Lock for thread safety
    if(poolHead == NULL){
        // If memory pool is empty, then create a new structure 
        LTE_PHY_RX_INDICATION_T *newStructure = malloc(sizeof(LTE_PHY_RX_INDICATION_T));
        return newStructure;
    } else {
        // If memory pool is not empty, then reuse the first available structure 
        LTE_PHY_RX_INDICATION_T *structure = poolHead->structure;
        memoryPoolNode* oldHead = poolHead;
        poolHead = poolHead->next;
        free(oldHead); // Free memory of node but not the data
        return structure; 
    }
}

// Deallocate to the memory pool
void deallocate(LTE_PHY_RX_INDICATION_T *structure) {
    pthread_mutex_lock(&poolLock); // Lock for thread safety
    memoryPoolNode* newNode = malloc(sizeof(memoryPoolNode));
    newNode->structure = structure;
    newNode->next = poolHead;
    poolHead = newNode;
}
```
