static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static AudioStream* streamsHead = NULL;
static int streamCount = 0;
static const int MAX_STREAMS = 1024; // or whatever limit you want to set

void allocateStream(AudioStreamMetadata metadata) {
    pthread_mutex_lock(&lock);

    if (streamCount >= MAX_STREAMS) {
        printf("Max streams reached\n");
        return;
    }

    AudioStream* newStream = malloc(sizeof(AudioStream));
    newStream->metadata = metadata;
    newStream->next = streamsHead;
    streamsHead = newStream;

    streamCount++;

    pthread_mutex_unlock(&lock);
}

void releaseAllResources() {
    pthread_mutex_lock(&lock);

    AudioStream* current = streamsHead;
    while(current) {
        AudioStream* temp = current;
        current = current->next;
        free(temp);
    }
    streamsHead = NULL;
    streamCount = 0;

    pthread_mutex_unlock(&lock);
}
``` 

