    }

    private String concatFieldsAndHash(Map<String, Object> log) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        // Concatenate the fields and compute the hash.
        String concatenated = "";
        byte[] bytesOfMessage = concatenated.getBytes();
        byte[] hashedBytes = md.digest(bytesOfMessage);
        return bytesToHex(hashedBytes);
    }

    private static String bytesToHex(byte[] hash) {
        StringBuilder hexString = new StringBuilder(2 * hash.length);
        for (int i = 0; i < hash.length; i++) {
            String hex = Integer.toHexString(0xff & hash[i]);
            if(hex.length() == 1) {
                hexString.append('0');
            }
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private String encryptPassword(YamlConfig config) throws Exception {
        KeyGenerator keyGen = KeyGenerator.getInstance("AES");
        keyGen.init(128);
        SecretKey secretKey = keyGen.generateKey();
        byte[] encoded = secretKey.getEncoded();
        SecretKeySpec skeySpec = new SecretKeySpec(encoded, "AES");
        Cipher cipher = Cipher.getInstance("AES");
        cipher.init(Cipher.ENCRYPT_MODE, skeySpec);
        byte[] encryptedPasswordBytes = cipher.doFinal(config.userId.getBytes());
        return new String(encryptedPasswordBytes);
    }

    private YamlConfig replacePlaceholdersAndAddPassword(YamlConfig config, String password) {
        // Replace placeholders and add the encrypted password to the configuration file.
