void requestListInit(RequestList *list) {
    list->size = 0;
    list->capacity = 10; // Initial capacity
    list->requests = malloc(sizeof(ConnectionRequest) * list->capacity);
    if (list->requests == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
}

void requestListAdd(RequestList *list, ConnectionRequest *req) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        // Resize the list when full
        list->capacity *= 2;
        list->requests = realloc(list->requests, sizeof(ConnectionRequest) * list->capacity);

        if (list->requests == NULL) {
            perror("Memory allocation failed");
            exit(EXIT_FAILURE);
        }
    }

    // Copy the request into the list
    memcpy(&list->requests[list->size], req, sizeof(ConnectionRequest));
    list->size++;

    get_config(req->configTag, &req->param1, &req->param2); // Fetch latest protocol parameters from the external configuration service

    pthread_mutex_unlock(&list->lock);
}
