typedef struct {
    int mac_entity;
    int c_rnti;
    void* buffer;
    time_t last_accessed;
} LTE_RRC_UE_CONTEXT_T;

LTE_RRC_UE_CONTEXT_T contexts[10000];
pthread_mutex_t context_lock = PTHREAD_MUTEX_INITIALIZER;
void (*expire_callback)(int c_rnti) = NULL;

// Comparison function for qsort()
int compare(const void * a, const void * b){
    return (((LTE_RRC_UE_CONTEXT_T*)a)->c_rnti - ((LTE_RRC_UE_CONTEXT_T*)b)->c_rnti);
}

// Binary search helper function
int binary_search(LTE_RRC_UE_CONTEXT_T arr[], int l, int r, int x){
    if (r >= l) { 
        int mid = l + (r - l)/2; 

        if (arr[mid].c_rnti == x)  return mid; 

        if (arr[mid].c_rnti > x) return binary_search(arr, l, mid-1, x); 

        return binary_search(arr, mid+1, r, x); 
   } 
   return -1;
}

// Find a context by C-RNTI
LTE_RRC_UE_CONTEXT_T* find_context(int c_rnti){
    qsort(contexts, sizeof(contexts)/sizeof(*contexts), sizeof(*contexts), compare);

    int index = binary_search(contexts, 0, sizeof(contexts)/sizeof(*contexts)-1, c_rnti);
    if(index != -1){
        contexts[index].last_accessed = time(NULL);
        return &contexts[index];
    }

    return NULL;
}

// Add a new context with C-RNTI checking for duplicates
void add_context(LTE_RRC_UE_CONTEXT_T *new_context){
    pthread_mutex_lock(&context_lock);
    LTE_RRC_UE_CONTEXT_T* found = find_context(new_context->c_rnti);

    if(found != NULL){
        printf("Duplicate C-RNTI assignment detected. Handle gracefully.\n");
