    } else {
        for(int i = 0; i < 10000; ++i){
            if(contexts[i].c_rnti == 0){
                contexts[i] = *new_context;
                break;
            }
        }
    }

    pthread_mutex_unlock(&context_lock);
}

// Update a context with C-RNTI checking for validity and existence
void update_context(LTE_RRC_UE_CONTEXT_T *updated_context){
    pthread_mutex_lock(&context_lock);

    LTE_RRC_UE_CONTEXT_T* found = find_context(updated_context->c_rnti);
    if(found != NULL) *found = *updated_context;
    else printf("Context with given C-RNTI not found.\n");

    pthread_mutex_unlock(&context_lock);
}

// Delete a context by C-RNTI and free its memory
void delete_context(int c_rnti){
    pthread_mutex_lock(&context_lock);

    LTE_RRC_UE_CONTEXT_T* found = find_context(c_rnti);
    if(found != NULL) {
        free(found->buffer);  // Assuming buffer needs to be freed
        *found = (LTE_RRC_UE_CONTEXT_T){0};
    } else printf("Context with given C-RNTI not found.\n");

    pthread_mutex_unlock(&context_lock);
}

// Periodically purge contexts that have been idle for more than 5 minutes
void purge_idle_contexts(){
    time_t current_time = time(NULL);

    pthread_mutex_lock(&context_lock);

    for(int i = 0; i < 10000; ++i){
        if((current_time - contexts[i].last_accessed) > 5*60 /* 5 minutes */ ){
            delete_context(contexts[i].c_rnti);
        }
    }

    pthread_mutex_unlock(&context_lock);
}

