app.put('/resources/:id', async (req, res) => {
    try {
        const updatedResource = await Resource.findByIdAndUpdate(
            req.params.id, 
            req.body, 
            { new: true }
        );

        if (!updatedResource) return res.status(404).send();

        // Fetch additional metadata related to the resource
        const metadata = await fetchMetadataRelatedTo(updatedResource);

        updatedResource.metadata = metadata;

        await updatedResource.save();

        res.json(updatedResource);
    } catch (error) {
        console.log(error);
        res.status(500).send('Error updating resource');
    }
});

app.delete('/resources/:id', async (req, res) => {
    try {
        const deletedResource = await Resource.findByIdAndDelete(req.params.id);

        if (!deletedResource) return res.status(404).send();

        // Return a new resource with default values
