        free(key);
        return -4; // Failed to open file
    }

    struct stat st;
    if (fstat(fd, &st) != 0) {
        close(fd);
        free(key);
        return -5; // Failed to get file stats
    }

    unsigned char* buffer = malloc(st.st_size);
    if (buffer == NULL) {
        close(fd);
