    DataPacket* packets;
    size_t capacity;
    size_t count;

    // Lock for concurrent access
    pthread_mutex_t lock; 
} PacketArray;

void init_packet_array(PacketArray* array, size_t initialCapacity) {
   array->capacity = initialCapacity;
   array->count = 0;
   array->packets = malloc(initialCapacity * sizeof(DataPacket));

   // Initialize the lock
   pthread_mutex_init(&array->lock, NULL);
}

void add_packet(PacketArray* array, DataPacket packet) {
    pthread_mutex_lock(&array->lock); 

    if (array->count == array->capacity) {
        // If necessary, reallocate more space to handle new packets
        array->capacity *= 2;
        array->packets = realloc(array->packets, array->capacity * sizeof(DataPacket)); 
    }

    array->packets[array->count++] = packet;

    pthread_mutex_unlock(&array->lock); 
}

