            buffers[i][j] = charset[rand() % len];
        }
        buffers[i][256] = '\0'; // null-terminate the string
    }
}

void check_uniqueness(char** buffers, size_t num_buffers) {
    for (size_t i = 0; i < num_buffers - 1; ++i) {
        for (size_t j = i + 1; j < num_buffers; ++j) {
            assert(strcmp(buffers[i], buffers[j]) != 0); // strings should be unique
        }
    }
}

