#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Node {
    int key;
    struct Node *next;
} Node;

Node* head = NULL;
Node* tail = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void insertAtBeginning(int value) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node *)malloc(sizeof(Node));

    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }

    newNode->key = value;
    newNode->next = head;
    head = newNode;

    if (tail == NULL) {
        tail = newNode;
    }

    pthread_mutex_unlock(&lock);
}

void insertAtEnd(int value) {
    pthread_mutex_lock(&lock);

    Node *newNode = (Node *)malloc(sizeof(Node));

    if (!newNode) {
        printf("Memory allocation failed\n");
        return;
    }

    newNode->key = value;
    newNode->next = NULL;

    if (tail == NULL) {
        head = tail = newNode;
    } else {
        tail->next = newNode;
        tail = newNode;
    }

    pthread_mutex_unlock(&lock);
}

void modifyKeys(int divisor, int newValue) {
    Node *node = head;

    while (node != NULL) {
        if (node->key % divisor == 0) {
            node->key = newValue;
        }

        node = node->next;
    }
}

void reverseList() {
    Node *prevNode = NULL;
    Node *currNode = head;
    Node *nextNode = NULL;

    tail = head;

    while (currNode != NULL) {
        nextNode = currNode->next;
        currNode->next = prevNode;
        prevNode = currNode;
        currNode = nextNode;
    }

    head = prevNode;
}

void freeList() {
    pthread_mutex_lock(&lock);

    Node *node = head;
    Node *nextNode = NULL;

    while (node != NULL) {
        nextNode = node->next;
        free(node);
        node = nextNode;
    }

    head = tail = NULL;

    pthread_mutex_unlock(&lock);
}
```
