        if (session->UE_ID == 0 || session->Serving_Cell_ID <= 0) {
            free(session);
            pthread_mutex_unlock(&sessionLock);
            return -3;  // Invalid UE_ID or Serving_Cell_ID
        }

        sessions[i] = session;  
        pthread_mutex_unlock(&sessionLock);
    }

    return 0;  // Success
