int executeCommandInBackground(char *cmd) {
    pid_t pid;

    if ((pid = fork()) < 0) {
        perror("Fork failed");
        return 0;
    } else if (pid == 0) { // child process
        signal(SIGINT, signalHandler);
        signal(SIGTERM, signalHandler);

        logEvent("Starting command execution", LOG_INFO);

        execl("/bin/sh", "sh", "-c", cmd, (char *) NULL);
    } else { // parent process
        struct sigaction sa;
        sa.sa_handler = signalHandler;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;

        if (sigaction(SIGINT, &sa, NULL) == -1) {
            perror("Could not set SIGINT handler");
            return 0;
        }

        if (sigaction(SIGTERM, &sa, NULL) == -1) {
            perror("Could not set SIGTERM handler");
            return 0;
        }
    }

    logEvent("Command started in the background", LOG_INFO);

    return 1;
}
