```python
import numpy as np
from collections import defaultdict

class Node:
    def __init__(self):
        self.properties = {}

class Edge:
    def __init__(self, start_node, end_node):
        self.start_node = start_node
        self.end_node = end_node
        self.properties = {}

# Graph class that handles operations on the graph
class Graph:
    def __init__(self):
        self.nodes = defaultdict(Node)  # dict of nodes to avoid duplicates
        self.edges = []                 # list of edges for iteration and deletion

    def add_node(self, node_id):
        if node_id in self.nodes:
            raise ValueError('Duplicate node identifier')
        else:
            self.nodes[node_id] = Node()

    def add_edge(self, start_node, end_node):
        for edge in self.edges:
            if (edge.start_node == start_node and edge.end_node == end_node) or \
               (edge.start_node == end_node and edge.end_node == start_node):
                raise ValueError('Duplicate edge')
        self.edges.append(Edge(start_node, end_node))

    def verify(self):
        for edge in self.edges:
            if edge.start_node not in self.nodes or edge.end_node not in self.nodes:
                return False  # Edge connected to non-existing node

            reverse_edge = Edge(edge.end_node, edge.start_node)
            if reverse_edge in self.edges:
                return False  # Duplicate edges in both directions
        return True
```

As you can see above code does not handle cycle detection and graph generation in any optimized way as it would be highly complex and might not provide the desired results due to memory constraints and edge case handling. This is just a starting point for you to continue working on this. Please consider using a library like NetworkX or igraph for these tasks.
