typedef struct {
    int user_id;
    time_t start_time;
    time_t last_active;
    // ... other session data fields
} Session;

Session* sessions = NULL;
int sessionCount = 0;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Implement a function to create a new session
Session* createSession(int userId) {
    // Ensure that no two sessions have the same user ID
    pthread_mutex_lock(&lock);
    for (int i = 0; i < sessionCount; ++i) {
        if (sessions[i].user_id == userId) {
            return NULL;
        }
    }

    Session* newSession = malloc(sizeof(Session));
    newSession->user_id = userId;
    time(&newSession->start_time);
    newSession->last_active = newSession->start_time;
    // ... other session initialization code

    ++sessionCount;
    sessions = realloc(sessions, sizeof(Session*) * sessionCount);
    sessions[sessionCount - 1] = newSession;

    pthread_mutex_unlock(&lock);

    return newSession;
}

// Implement a function to update the last active timestamp of a session
void updateLastActive(int userId) {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < sessionCount; ++i) {
        if (sessions[i].user_id == userId) {
            time(&sessions[i].last_active);
            break;
        }
    }
    pthread_mutex_unlock(&lock);
}
```
The above code block includes a simple example of how to create and update sessions in a thread-safe manner using `pthread_mutex`. This is a basic implementation and does not include features like logging, invalidating sessions when a user logs out from another device, purging inactive sessions periodically based on a configurable inactivity threshold, or network failures handling.
