#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct NIC_config {
    char MAC[18];
    int IP;
    void* buffer;
} NIC_config_t;

typedef struct NICArray {
    pthread_mutex_t mutex;
    NIC_config_t** array;
    size_t size;
    size_t capacity;
} NICArray_t;

void add_nic(NICArray_t* nic_array, NIC_config_t* new_nic) {
    pthread_mutex_lock(&nic_array->mutex);

    if (nic_array->size == nic_array->capacity) {
        // Reallocate memory with increased capacity
        nic_array->capacity *= 2;
        nic_array->array = realloc(nic_array->array, nic_array->capacity * sizeof(NIC_config_t*));
    }

    // Deep copy of new_nic
    NIC_config_t* copied_nic = malloc(sizeof(NIC_config_t));
    memcpy(copied_nic, new_nic, sizeof(NIC_config_t));

    nic_array->array[nic_array->size] = copied_nic;
    nic_array->size++;

    pthread_mutex_unlock(&nic_array->mutex);
}
```
This is a simplified version. In real code, you would want to handle errors properly and check for memory allocation failure. Also, the function `add_nic` doesn't update an existing configuration but adds a new one. You could add a mechanism to compare MAC addresses and IPs or use hash-based data structure (like unordered map in C++) to ensure uniqueness of MAC address and set of IP addresses.

