['Here is a basic skeleton code for your problem statement in C language, but this does not cover all aspects as stated above. You would need to add logic according to your specific requirements. The DNS querying part is done using the `res_query` function from c-ares library. For logging and error handling you could use a custom defined error enum, and for concurrent requests management you can use threads or processes depending upon your requirement. 

```c
#include <stdio.h>
#include <string.h>
#include <arpa/nameser.h>
#include <ares.h>

typedef struct {
    int timeout;
    int max_response_size;
    int logging_level;
} dns_config;

typedef enum {
    SUCCESS = 0,
    TIMEOUT,
    SERVER_UNAVAILABLE,
    MALFORMED_HOSTNAME
} error_code;

error_code resolve_dns(const char* hostname, dns_config config, u_char* result) {

    ares_channel channel;
    int status;
    struct ares_options options;
    int optionmask = 0;
    fd_set read_fds, write_fds;

    if ((status = ares_init(&channel)) != ARES_SUCCESS) {
        return SERVER_UNAVAILABLE; // replace with your error code
    }

    options.timeout = config.timeout;
    optionmask |= ARES_OPT_TIMEOUTMS;
    ares_set_options(channel, &options, optionmask);

    struct hostent* host;
    int err = gethostbyname_r(hostname, &host, buffer, sizeof(buffer), &result, &herr);
    if (err != 0 || herr != 0) {
        return MALFORMED_HOSTNAME; // replace with your error code
    }

    ares_destroy(channel);

    memcpy(result, host->h_addr_list[0], sizeof(u_char)*4);
    if (!result) { 
        return SERVER_UNAVAILABLE; // replace with your error code
    }

    return SUCCESS;
}
```
This is a very basic implementation. It does not include logging, error handling for DNS resolution failures (like timeout), memory management and system scaling considerations. You may need to modify the function according to the actual requirements of your application. 
