class DataException : public std::exception {
public:
    explicit DataException(const char* message) : msg_(message) {}
    virtual const char* what() const throw() {
        return msg_.c_str();
    }
private:
    std::string msg_;
};

void deserialize(std::vector<uint8_t>& buffer, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (buffer.size() < sizeof(*pdu)) {
        throw DataException("Buffer size is smaller than expected");
    }

    memcpy(pdu, &buffer[0], sizeof(*pdu));

    if (calculateCRC(pdu) != pdu->CRCFLAG) {
        throw DataException("Data corrupted. CRC mismatch");
    }
}
