log = logging.getLogger(__name__)

class UserManager:
    def __init__(self, max_records=MAX_SIZE):
        self.max_records = max_records
        self.current_size = 0
        self.queue = deque(maxlen=max_records)
        self.lock = threading.Lock()

    def add_record(self, record: USER_DATA_RECORD_T):
        if self.current_size >= self.max_records:
            log.warning("Max records reached")
            return

        with self.lock:
            self.queue.append(record)
            self.current_size += 1

    def update_record(self, uid: str, record: USER_DATA_RECORD_T):
        with self.lock:
            for i in range(len(self.queue)):
                if self.queue[i]['uid'] == uid:
                    self.queue[i] = record
                    break

    def remove_record(self, uid: str):
        with self.lock:
            for i in range(len(self.queue)):
                if self.queue[i]['uid'] == uid:
                    del self.queue[i]
                    self.current_size -= 1
                    break

    def purge_expired_records(self):
        with self.lock:
            for i in range(len(self.queue)):
                if self.queue[i].is_expired():  # You need to define this function based on your requirements
