// Define a record structure with a unique integer key and corresponding long offset value.
typedef struct {
    _Atomic int id;  // We use atomic to ensure thread safety.
    unsigned long offset;
} Record;

Record* records = NULL;
size_t numRecords = 0;
pthread_rwlock_t rwLock = PTHREAD_RWLOCK_INITIALIZER;

// Function to asynchronously fetch keys from an external data source.
