}

// Allocate a record with the given key. Returns NULL if allocation failed.
Record* allocateRecord(_Atomic int key) {
    Record* newRecords = realloc(records, sizeof(Record) * (numRecords + 1));
    if (!newRecords) {
        return NULL;  // Allocation failed.
    }
    records = newRecords;

    pthread_rwlock_wrlock(&rwLock);  
    records[numRecords].id = key;
    srand(key + time(NULL));  // Seed the random number generator with a unique identifier derived from the record's key.
    records[numRecords].offset = rand();  // Generate offset.
    ++numRecords;
    pthread_rwlock_unlock(&rwLock);  

    return &records[numRecords - 1];
}

// Delete a record with the given key, if it exists. Returns non-zero on error.
int deleteRecord(_Atomic int key) {
    // Find the record with the given id and swap it with the last one then resize the array.

    pthread_rwlock_wrlock(&rwLock);  
    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i].id == key) {
            records[i] = records[numRecords - 1];
            --numRecords;

            Record* newRecords = realloc(records, sizeof(Record) * numRecords);
            if (!newRecords && numRecords > 0) {
                return EXIT_FAILURE;  // Couldn't shrink the array.
            }
            records = newRecords;

            pthread_rwlock_unlock(&rwLock);  
            return EXIT_SUCCESS;
        }
    }

    pthread_rwlock_unlock(&rwLock);  
    return 1;  // Record not found.
}
```

